inline void loadDiscordTargetMode() {
  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    fs::path modeFile = fs::path(appData) / "DiscordUnlock" / "discord_target_mode.txt";
    std::error_code ec;
    if (fs::exists(modeFile, ec)) {
      std::ifstream f(modeFile.string());
      std::string m;
      if (f >> m) {
        if (m == "web" || m == "desktop") {
          g_discordTargetMode = m;
          g_discordTargetModeSet = true;
          return;
        }
      }
    }
  }
  g_discordTargetMode = "desktop";
  g_discordTargetModeSet = false;
}

inline void saveDiscordTargetMode(const std::string &mode) {
  g_discordTargetMode = (mode == "web") ? "web" : "desktop";
  g_discordTargetModeSet = true;
  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    fs::path dataDir = fs::path(appData) / "DiscordUnlock";
    std::error_code ec;
    if (!fs::exists(dataDir, ec)) fs::create_directories(dataDir, ec);
    fs::path modeFile = dataDir / "discord_target_mode.txt";
    std::ofstream f(modeFile.string());
    if (f.is_open()) {
      f << g_discordTargetMode;
      f.close();
    }
  }
}

