std::string extractHostOrIp(const std::string &endpoint) {
  if (endpoint.empty()) return "";
  size_t p = endpoint.find("://");
  std::string s = (p != std::string::npos) ? endpoint.substr(p + 3) : endpoint;
  size_t colon = s.find(':');
  if (colon != std::string::npos) s = s.substr(0, colon);
  return s;
}

