std::wstring toWide(const std::string &str) {
  if (str.empty()) return L"";
  const int size = MultiByteToWideChar(CP_UTF8, 0, str.c_str(), -1, nullptr, 0);
  if (size <= 0) return L"";
  std::wstring result(static_cast<size_t>(size), L'\0');
  if (MultiByteToWideChar(CP_UTF8, 0, str.c_str(), -1, result.data(), size) <= 0) return L"";
  result.pop_back();
  return result;
}

std::string toUtf8(const std::wstring &wstr) {
  if (wstr.empty()) return "";
  const int size = WideCharToMultiByte(CP_UTF8, 0, wstr.c_str(), -1, nullptr, 0, nullptr, nullptr);
  if (size <= 0) return "";
  std::string result(static_cast<size_t>(size), '\0');
  if (WideCharToMultiByte(CP_UTF8, 0, wstr.c_str(), -1, result.data(), size, nullptr, nullptr) <= 0) return "";
  result.pop_back();
  return result;
}

std::string escapeJsonString(const std::string &input) {
  std::string output;
  for (char c : input) {
    if (c == '"') output += "\\\"";
    else if (c == '\\') output += "\\\\";
    else if (c == '\b') output += "\\b";
    else if (c == '\f') output += "\\f";
    else if (c == '\n') output += "\\n";
    else if (c == '\r') output += "\\r";
    else if (c == '\t') output += "\\t";
    else output += c;
  }
  return output;
}

