// =========================================================================
// RESILIENT MULTI-TIER NETWORK ENGINE (WinHTTP + WinInet + Native curl.exe)
// =========================================================================

std::string downloadViaWinInet(const std::string &fullUrl) {
  HINTERNET hInet = InternetOpenA("Mozilla/5.0 (Windows NT 10.0; Win64; x64)", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
  if (!hInet) return "";

  DWORD flags = INTERNET_FLAG_RELOAD | INTERNET_FLAG_NO_CACHE_WRITE | INTERNET_FLAG_SECURE;
  HINTERNET hUrl = InternetOpenUrlA(hInet, fullUrl.c_str(), NULL, 0, flags, 0);
  if (!hUrl) {
    InternetCloseHandle(hInet);
    return "";
  }

  std::string response;
  char buffer[8192];
  DWORD bytesRead = 0;
  while (InternetReadFile(hUrl, buffer, sizeof(buffer) - 1, &bytesRead) && bytesRead > 0) {
    buffer[bytesRead] = '\0';
    response.append(buffer, bytesRead);
  }

  InternetCloseHandle(hUrl);
  InternetCloseHandle(hInet);
  return response;
}

std::string downloadViaCurl(const std::string &fullUrl) {
  // _popen starts cmd.exe on Windows. Besides being needless here, that can
  // briefly flash a console when the app has no parent terminal.
  return downloadViaWinInet(fullUrl);
}

std::string downloadUrl(const std::wstring &host, const std::wstring &path) {
  std::string response;

  // 1. WinHTTP with explicit TLS 1.2/1.3 and strict certificate validation
  try {
    HINTERNET hSession = WinHttpOpen(L"Mozilla/5.0 (Windows NT 10.0; Win64; x64)", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0);
    if (hSession) {
      DWORD protocols = WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_2 | WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_3;
      WinHttpSetOption(hSession, WINHTTP_OPTION_SECURE_PROTOCOLS, &protocols, sizeof(protocols));
      WinHttpSetTimeouts(hSession, 5000, 5000, 5000, 7000);

      HINTERNET hConnect = WinHttpConnect(hSession, host.c_str(), INTERNET_DEFAULT_HTTPS_PORT, 0);
      if (hConnect) {
        HINTERNET hRequest = WinHttpOpenRequest(hConnect, L"GET", path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, WINHTTP_FLAG_SECURE);
        if (hRequest) {
          LPCWSTR headers = L"User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64)\r\nAccept: */*\r\n";
          if (WinHttpSendRequest(hRequest, headers, (DWORD)-1L, WINHTTP_NO_REQUEST_DATA, 0, 0, 0) &&
              WinHttpReceiveResponse(hRequest, nullptr)) {
            DWORD bytesRead = 0;
            char buffer[8192];
            while (WinHttpReadData(hRequest, buffer, sizeof(buffer) - 1, &bytesRead) && bytesRead > 0) {
              buffer[bytesRead] = '\0';
              response.append(buffer, bytesRead);
            }
          }
          WinHttpCloseHandle(hRequest);
        }
        WinHttpCloseHandle(hConnect);
      }
      WinHttpCloseHandle(hSession);
    }
  } catch (...) {}

  if (!response.empty()) return response;

  // 2. WinInet fallback (inherits Edge/Chrome system proxy & network configuration)
  std::string fullUrl = "https://" + toUtf8(host) + toUtf8(path);
  response = downloadViaWinInet(fullUrl);
  if (!response.empty()) return response;

  // 3. Native curl.exe fallback (independent network engine)
  response = downloadViaCurl(fullUrl);
  return response;
}

// Declarada aqui para que a verificacao inicial consulte as duas fontes.
// A implementacao fica junto do atualizador, depois do downloader binario.
std::string getLatestUpdateVersionFromAllSources();

// Compara versoes no formato "MAJOR.MINOR" corretamente.
// std::stod("8.10") == 8.1 < 8.7 — ERRADO. Esta funcao evita esse bug.
static std::pair<int,int> parseVersion(const std::string& v) {
  int major2 = 0, minor2 = 0;
  auto dot = v.find('.');
  try {
    if (dot == std::string::npos) {
      major2 = std::stoi(v);
    } else {
      major2 = std::stoi(v.substr(0, dot));
      minor2 = std::stoi(v.substr(dot + 1));
    }
  } catch (...) {}
  return {major2, minor2};
}
// Retorna true se a > b (versao a e mais nova que b)
static bool updateVersionNumber(const std::string& a, const std::string& b) {
  auto pa = parseVersion(a), pb = parseVersion(b);
  if (pa.first != pb.first) return pa.first > pb.first;
  return pa.second > pb.second;
}

