void checkForUpdatesPreAuth() {
  std::thread([]() {
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
    std::string remoteVer = getLatestUpdateVersionFromAllSources();
    remoteVer.erase(std::remove_if(remoteVer.begin(), remoteVer.end(), ::isspace), remoteVer.end());
    std::replace(remoteVer.begin(), remoteVer.end(), ',', '.');

    if (!remoteVer.empty()) {
      try {
        auto remoteOrd  = (long long)parseVersion(remoteVer).first * 100000LL + parseVersion(remoteVer).second;
        auto currentOrd = (long long)parseVersion(CURRENT_VERSION).first * 100000LL + parseVersion(CURRENT_VERSION).second;
        if (remoteOrd > currentOrd) {
          std::string updateJson = "{\"type\":\"update_available\",\"currentVersion\":\"" + CURRENT_VERSION + "\",\"latestVersion\":\"" + remoteVer + "\"}";
          postJsonToUI(updateJson);
        }
      } catch (...) {}
    }
  }).detach();
}

int getProxyLatency(const std::string &proxyUrl) {
  std::string url = proxyUrl;
  size_t protoPos = url.find("://");
  if (protoPos != std::string::npos) {
    url = url.substr(protoPos + 3);
  }

  size_t colon = url.find(':');
  if (colon == std::string::npos) return -1;

  std::string host = url.substr(0, colon);
  int port = 1080;
  try {
    port = std::stoi(url.substr(colon + 1));
  } catch (...) {
    return -1;
  }

  auto start = std::chrono::high_resolution_clock::now();

  SOCKET s = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
  if (s == INVALID_SOCKET) return -1;

  DWORD timeout = 2500;
  setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, (char *)&timeout, sizeof(timeout));
  setsockopt(s, SOL_SOCKET, SO_SNDTIMEO, (char *)&timeout, sizeof(timeout));

  sockaddr_in addr;
  addr.sin_family = AF_INET;
  addr.sin_port = htons(port);
  inet_pton(AF_INET, host.c_str(), &addr.sin_addr);

  if (connect(s, (sockaddr *)&addr, sizeof(addr)) != 0) {
    closesocket(s);
    return -1;
  }

  unsigned char req1[] = { 0x05, 0x01, 0x00 };
  if (send(s, (char *)req1, sizeof(req1), 0) != (int)sizeof(req1)) {
    closesocket(s);
    return -1;
  }

  unsigned char resp1[2];
  if (recv(s, (char *)resp1, 2, 0) != 2 || resp1[0] != 0x05 || resp1[1] != 0x00) {
    closesocket(s);
    return -1;
  }

  std::string testDomain = "discord.com";
  std::vector<unsigned char> req2;
  req2.push_back(0x05);
  req2.push_back(0x01);
  req2.push_back(0x00);
  req2.push_back(0x03);
  req2.push_back((unsigned char)testDomain.length());
  for (char c : testDomain) req2.push_back(c);
  req2.push_back(0x01);
  req2.push_back(0xBB);

  if (send(s, (char *)req2.data(), (int)req2.size(), 0) != (int)req2.size()) {
    closesocket(s);
    return -1;
  }

  unsigned char resp2[10];
  int r = recv(s, (char *)resp2, sizeof(resp2), 0);
  if (r < 4 || resp2[0] != 0x05 || resp2[1] != 0x00) {
    closesocket(s);
    return -1;
  }

  closesocket(s);

  auto end = std::chrono::high_resolution_clock::now();
  return (int)std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
}

