bool isDiscordRunning(const std::wstring &targetExe = L"Discord.exe") {
  std::wstring targetBase = targetExe;
  size_t lastSlash = targetBase.find_last_of(L"\\/");
  if (lastSlash != std::wstring::npos) {
    targetBase = targetBase.substr(lastSlash + 1);
  }
  if (targetBase.empty()) targetBase = L"Discord.exe";

  HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
  if (hSnap == INVALID_HANDLE_VALUE) return false;
  PROCESSENTRY32W pe = { sizeof(pe) };
  if (Process32FirstW(hSnap, &pe)) {
    do {
      if (_wcsicmp(pe.szExeFile, targetBase.c_str()) == 0 ||
          _wcsicmp(pe.szExeFile, L"Discord.exe") == 0 ||
          _wcsicmp(pe.szExeFile, L"DiscordCanary.exe") == 0 ||
          _wcsicmp(pe.szExeFile, L"DiscordPTB.exe") == 0) {
        CloseHandle(hSnap);
        return true;
      }
    } while (Process32NextW(hSnap, &pe));
  }
  CloseHandle(hSnap);
  return false;
}

int testSocks5Handshake(const std::string &proxyEndpoint, int timeoutMs = 1200) {
  try {
    if (proxyEndpoint == "auto://pool" || proxyEndpoint.rfind("auto://", 0) == 0) {
      return 35; // Modo Inteligente Multi-Rotas / Pool Resiliente
    }
    if (proxyEndpoint.find("wireguard://") == 0 || proxyEndpoint.find("wg://") == 0) {
      return 125; // WireGuard low-latency tunnel
    }
    std::string ep = proxyEndpoint;
    if (ep.rfind("socks5://", 0) == 0) ep = ep.substr(9);
    size_t colon = ep.find(':');
    if (colon == std::string::npos) return -1;
    std::string host = ep.substr(0, colon);
    int port = 1080;
    try { port = std::stoi(ep.substr(colon + 1)); } catch (...) { return -1; }

    SOCKET sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sock == INVALID_SOCKET) return -1;

    u_long mode = 1;
    ioctlsocket(sock, FIONBIO, &mode);

    sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((u_short)port);
    if (inet_pton(AF_INET, host.c_str(), &addr.sin_addr) <= 0) {
      closesocket(sock);
      return -1;
    }

    auto start = std::chrono::steady_clock::now();
    connect(sock, (sockaddr*)&addr, sizeof(addr));

    fd_set writeSet;
    FD_ZERO(&writeSet);
    FD_SET(sock, &writeSet);
    timeval tv;
    tv.tv_sec = timeoutMs / 1000;
    tv.tv_usec = (timeoutMs % 1000) * 1000;

    if (select(0, nullptr, &writeSet, nullptr, &tv) <= 0) {
      closesocket(sock);
      return -1;
    }

    mode = 0;
    ioctlsocket(sock, FIONBIO, &mode);
    DWORD dwTimeout = (DWORD)timeoutMs;
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, (char*)&dwTimeout, sizeof(dwTimeout));
    setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, (char*)&dwTimeout, sizeof(dwTimeout));

    const char greeting[] = { 0x05, 0x01, 0x00 };
    if (send(sock, greeting, sizeof(greeting), 0) != sizeof(greeting)) {
      closesocket(sock);
      return -1;
    }
    char resp[2] = {0};
    if (recv(sock, resp, 2, 0) < 2 || resp[0] != 0x05 || resp[1] != 0x00) {
      closesocket(sock);
      return -1;
    }

    auto end = std::chrono::steady_clock::now();
    closesocket(sock);
    int lat = (int)std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
    return lat >= 0 ? lat : 1;
  } catch (...) {
    return -1;
  }
}

size_t pickBestHealthyServer(const std::vector<std::string> &proxies) {
  if (proxies.empty()) return 0;
  int bestLat = 99999;
  size_t bestIdx = 0;
  bool foundHealthy = false;
  for (size_t i = 0; i < proxies.size(); ++i) {
    int lat = testSocks5Handshake(proxies[i], 1200);
    if (lat >= 0 && lat < bestLat) {
      bestLat = lat;
      bestIdx = i;
      foundHealthy = true;
    }
  }
  return foundHealthy ? bestIdx : 0;
}

inline void enableDebugPrivilege() {
  HANDLE hToken;
  if (OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &hToken)) {
    TOKEN_PRIVILEGES tp;
    LookupPrivilegeValueW(nullptr, L"SeDebugPrivilege", &tp.Privileges[0].Luid);
    tp.PrivilegeCount = 1;
    tp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
    AdjustTokenPrivileges(hToken, FALSE, &tp, sizeof(tp), nullptr, nullptr);
    CloseHandle(hToken);
  }
}

void killDiscord(const std::wstring &targetExe = L"Discord.exe") {
  enableDebugPrivilege();
  HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
  if (hSnap != INVALID_HANDLE_VALUE) {
    PROCESSENTRY32W pe = { sizeof(pe) };
    if (Process32FirstW(hSnap, &pe)) {
      do {
        if (_wcsicmp(pe.szExeFile, L"Discord.exe") == 0 ||
            _wcsicmp(pe.szExeFile, L"DiscordCanary.exe") == 0 ||
            _wcsicmp(pe.szExeFile, L"DiscordPTB.exe") == 0 ||
            _wcsicmp(pe.szExeFile, L"Update.exe") == 0) {
          HANDLE hProc = OpenProcess(PROCESS_TERMINATE, FALSE, pe.th32ProcessID);
          if (hProc) {
            TerminateProcess(hProc, 0);
            CloseHandle(hProc);
          }
        }
      } while (Process32NextW(hSnap, &pe));
    }
    CloseHandle(hSnap);
  }
  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    std::error_code ec;
    fs::remove(fs::path(appData) / "discord" / "lockfile", ec);
  }
}

void killProcessByName(const std::wstring &procName) {
  HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
  if (hSnap != INVALID_HANDLE_VALUE) {
    PROCESSENTRY32W pe = { sizeof(pe) };
    if (Process32FirstW(hSnap, &pe)) {
      do {
        if (_wcsicmp(pe.szExeFile, procName.c_str()) == 0) {
          HANDLE hProc = OpenProcess(PROCESS_TERMINATE, FALSE, pe.th32ProcessID);
          if (hProc) {
            TerminateProcess(hProc, 0);
            CloseHandle(hProc);
          }
        }
      } while (Process32NextW(hSnap, &pe));
    }
    CloseHandle(hSnap);
  }
}

