inline fs::path getCustomServersJsonPath() {
  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    fs::path p = fs::path(appData) / "DiscordUnlock" / "custom_servers.json";
    return p;
  }
  return L"C:/DiscordUnlock\\custom_servers.json";
}

inline void loadSavedCustomServers(std::vector<ServerProfile> &list) {
  try {
    fs::path p = getCustomServersJsonPath();
    if (!fs::exists(p)) return;
    std::ifstream in(p.string());
    if (!in.is_open()) return;
    std::string json((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
    in.close();

    size_t pos = 0;
    while ((pos = json.find('{', pos)) != std::string::npos) {
      size_t end = json.find('}', pos);
      if (end == std::string::npos) break;
      std::string obj = json.substr(pos, end - pos + 1);
      pos = end + 1;

      std::string endpoint = extractJsonField(obj, "endpoint");
      if (endpoint.empty()) continue;
      std::string id = extractJsonField(obj, "id");
      std::string name = extractJsonField(obj, "name");
      std::string country = extractJsonField(obj, "country");
      std::string code = extractJsonField(obj, "code");

      ServerProfile prof;
      prof.id = id.empty() ? ("custom_" + endpoint) : id;
      prof.name = name.empty() ? ("Meu Servidor (" + endpoint + ")") : name;
      prof.country = country.empty() ? prof.name : country;
      prof.code = code.empty() ? "US" : code;
      prof.endpoint = endpoint;

      prof.isDirect = false;
      prof.isCustom = true;
      list.push_back(prof);
    }
  } catch (...) {}
}

inline void saveCustomServersToDisk(const std::vector<ServerProfile> &profiles) {
  try {
    fs::path p = getCustomServersJsonPath();
    std::error_code ec;
    if (!fs::exists(p.parent_path(), ec)) fs::create_directories(p.parent_path(), ec);

    std::string json = "[\n";
    bool first = true;
    for (const auto &prof : profiles) {
      if (!prof.isCustom) continue;
      if (!first) json += ",\n";
      first = false;
      json += "  {\n";
      json += "    \"id\": \"" + escapeJsonString(prof.id) + "\",\n";
      json += "    \"name\": \"" + escapeJsonString(prof.name) + "\",\n";
      json += "    \"country\": \"" + escapeJsonString(prof.country) + "\",\n";
      json += "    \"code\": \"" + escapeJsonString(prof.code) + "\",\n";
      json += "    \"endpoint\": \"" + escapeJsonString(prof.endpoint) + "\"\n";
      json += "  }";
    }
    json += "\n]\n";
    std::ofstream out(p.string(), std::ios::trunc);
    if (out.is_open()) {
      out << json;
      out.close();
    }
  } catch (...) {}
}

