inline fs::path getCachedServersPath() {
  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    fs::path p = fs::path(appData) / "DiscordUnlock" / "cached_remote_servers.json";
    return p;
  }
  return L"C:/DiscordUnlock\\cached_remote_servers.json";
}

inline bool parseServersJson(const std::string &json, std::vector<ServerProfile> &out) {
  try {
    if (json.empty() || json.find("endpoint") == std::string::npos) return false;
    std::vector<ServerProfile> parsed;
    size_t pos = 0;
    while ((pos = json.find('{', pos)) != std::string::npos) {
      size_t end = json.find('}', pos);
      if (end == std::string::npos) break;
      std::string obj = json.substr(pos, end - pos + 1);
      pos = end + 1;

      std::string endpoint = extractJsonField(obj, "endpoint");
      if (endpoint.empty()) continue;

      ServerProfile prof;
      prof.id = extractJsonField(obj, "id");
      prof.name = extractJsonField(obj, "name");
      prof.country = extractJsonField(obj, "country");
      prof.code = extractJsonField(obj, "code");
      prof.endpoint = endpoint;

      if (prof.id.empty()) prof.id = "server_" + std::to_string(parsed.size() + 1);
      if (prof.name.empty()) prof.name = prof.endpoint;
      if (prof.country.empty()) prof.country = prof.name;
      if (prof.code.empty()) prof.code = "US";      prof.isDirect = false;
      prof.isCustom = false;
      parsed.push_back(prof);
    }
    if (!parsed.empty()) {
      out = parsed;
      return true;
    }
  } catch (...) {}
  return false;
}

