void logThemeEngine(const std::string &action, const std::string &status, const std::string &details) {
  try {
    SYSTEMTIME st;
    GetLocalTime(&st);
    char timeBuf[64];
    sprintf_s(timeBuf, "[%04d-%02d-%02d %02d:%02d:%02d.%03d]", st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);

    std::string logLine = std::string(timeBuf) + " [" + action + "] [" + status + "] " + details + "\n";

    std::vector<fs::path> logPaths = {
      fs::path(L"C:/DiscordUnlock\\themes_engine.log")
    };
    wchar_t appData[MAX_PATH];
    if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
      logPaths.push_back(fs::path(appData) / "DiscordUnlock" / "themes_engine.log");
    }

    for (const auto &p : logPaths) {
      if (!fs::exists(p.parent_path())) {
        std::error_code ec;
        fs::create_directories(p.parent_path(), ec);
      }
      std::ofstream f(p.string(), std::ios::app);
      if (f.is_open()) {
        f << logLine;
        f.close();
      }
    }
  } catch(...) {}
}

static std::string urlEncode(const std::string &value) {
  std::ostringstream escaped;
  escaped.fill('0');
  escaped << std::hex;
  for (unsigned char c : value) {
    if (isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') {
      escaped << c;
    } else {
      escaped << std::uppercase << '%' << std::setw(2) << int(c) << std::nouppercase;
    }
  }
  return escaped.str();
}

static std::string fileToBase64DataUri(const fs::path &filePath) {
  try {
    std::ifstream file(filePath.string(), std::ios::binary);
    if (!file.is_open()) return "";
    file.seekg(0, std::ios::end);
    size_t size = file.tellg();
    if (size == 0 || size > 25 * 1024 * 1024) return ""; // 25MB max
    file.seekg(0, std::ios::beg);
    std::vector<unsigned char> buffer(size);
    file.read(reinterpret_cast<char*>(buffer.data()), size);
    file.close();

    static const char base64_chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    std::string encoded;
    encoded.reserve(((size + 2) / 3) * 4);
    for (size_t i = 0; i < size; i += 3) {
      unsigned int b = (static_cast<unsigned int>(buffer[i]) << 16) | 
                       (i + 1 < size ? (static_cast<unsigned int>(buffer[i + 1]) << 8) : 0) | 
                       (i + 2 < size ? static_cast<unsigned int>(buffer[i + 2]) : 0);
      encoded.push_back(base64_chars[(b >> 18) & 0x3F]);
      encoded.push_back(base64_chars[(b >> 12) & 0x3F]);
      encoded.push_back(i + 1 < size ? base64_chars[(b >> 6) & 0x3F] : '=');
      encoded.push_back(i + 2 < size ? base64_chars[b & 0x3F] : '=');
    }

    std::string ext = filePath.extension().string();
    std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
    std::string mime = "image/jpeg";
    if (ext == ".png") mime = "image/png";
    else if (ext == ".gif") mime = "image/gif";
    else if (ext == ".webp") mime = "image/webp";

    return "data:" + mime + ";base64," + encoded;
  } catch(...) {
    return "";
  }
}

inline fs::path getExeDir() {
  wchar_t exePath[MAX_PATH] = {0};
  if (GetModuleFileNameW(NULL, exePath, MAX_PATH) > 0) {
    return fs::path(exePath).parent_path();
  }
  return fs::path(L"C:/DiscordUnlock");
}

inline fs::path getLocalTemasDir() {
  static fs::path s_temasDir;
  if (!s_temasDir.empty()) return s_temasDir;
  wchar_t exePath[MAX_PATH] = {0};
  if (GetModuleFileNameW(NULL, exePath, MAX_PATH) > 0) {
    fs::path exeDir = fs::path(exePath).parent_path();
    s_temasDir = exeDir / "temas";
  } else {
    s_temasDir = fs::path(L"C:/DiscordUnlock\\temas");
  }
  std::error_code ec;
  if (!fs::exists(s_temasDir, ec)) {
    fs::create_directories(s_temasDir, ec);
  }
  return s_temasDir;
}

