inline void ensureDiscordUnlockBypassInstalled(const fs::path &appDir) {
  try {
    fs::path resDir = appDir / "resources";
    if (!fs::exists(resDir)) return;

    fs::path originalAsar = resDir / "_app.asar";
    fs::path currentAsar = resDir / "app.asar";

    std::error_code ec;
    // 1. If app.asar is a directory stub from old v1.x bypass, remove it completely
    if (fs::exists(currentAsar, ec) && fs::is_directory(currentAsar, ec)) {
      fs::remove_all(currentAsar, ec);
    }

    // 2. Ensure genuine pristine app.asar is restored from _app.asar
    if (fs::exists(originalAsar, ec)) {
      if (!fs::exists(currentAsar, ec) || (fs::is_regular_file(currentAsar, ec) && fs::file_size(currentAsar, ec) < 100000)) {
        fs::copy_file(originalAsar, currentAsar, fs::copy_options::overwrite_existing, ec);
      }
    }

    // 3. Purge all legacy v1.x shims that broke Discord Electron
    fs::remove(resDir / "golivebypass.js", ec);
    fs::remove(resDir / "golive-shim.js", ec);
    fs::remove(resDir / "settings.json", ec);
    fs::remove(resDir / "state.json", ec);
    fs::remove(resDir / "app.asar.old", ec);

    // 4. Remove stale lockfile from %APPDATA%\discord\lockfile
    wchar_t appData[MAX_PATH];
    if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
      fs::remove(fs::path(appData) / "discord" / "lockfile", ec);
    }
  } catch (...) {}
}

