    installDiscordThemeHook(g_targetExe);

    logThemeEngine("THEME_APPLY", "SUCCESS", "Theme applied: " + themeId + " (isVideo=" + (isVideo ? "true" : "false") + ", videoUri=" + videoUri + ")");
