void notifyDiscordRealStatus(bool enabled) {
  try {
    HINTERNET hSession = WinHttpOpen(L"DiscordUnlock/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0);
    if (hSession) {
      WinHttpSetTimeouts(hSession, 2500, 2500, 2500, 2500);
      HINTERNET hConnect = WinHttpConnect(hSession, L"127.0.0.1", 45123, 0);
      if (hConnect) {
        std::wstring wPath = L"/set_real_status_detector?enabled=" + std::wstring(enabled ? L"true" : L"false");
        HINTERNET hRequest = WinHttpOpenRequest(hConnect, L"GET", wPath.c_str(), NULL, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, 0);
        if (hRequest) {
          WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
          WinHttpReceiveResponse(hRequest, NULL);
          WinHttpCloseHandle(hRequest);
        }
        std::wstring wPath2 = L"/reload_plugin?name=NitroStreamUnlock";
        HINTERNET hRequest2 = WinHttpOpenRequest(hConnect, L"GET", wPath2.c_str(), NULL, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, 0);
        if (hRequest2) {
          WinHttpSendRequest(hRequest2, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
          WinHttpReceiveResponse(hRequest2, NULL);
          WinHttpCloseHandle(hRequest2);
        }
        WinHttpCloseHandle(hConnect);
      }
      WinHttpCloseHandle(hSession);
    }
  } catch (...) {}
}

