void installBetterDiscordPlugin(const std::string &pluginId, const std::string &pluginName) {
  std::string pluginJs =
      "/**\n"
      " * @name " + pluginId + "\n"
      " * @author DiscordUnlock\n"
      " * @description " + pluginName + " injetado via Discord Unlock Pro.\n"
      " * @version 1.0.0\n"
      " */\n"
      "module.exports = class " + pluginId + " {\n"
      "  start() { console.log('" + pluginId + " ativado com sucesso'); }\n"
      "  stop() {}\n"
      "};\n";

  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    fs::path bdPluginsDir = fs::path(appData) / "BetterDiscord" / "plugins";
    if (!fs::exists(bdPluginsDir)) fs::create_directories(bdPluginsDir);
    fs::path pluginFile = bdPluginsDir / (pluginId + ".plugin.js");
    std::ofstream f(pluginFile.string());
    if (f.is_open()) {
      f << pluginJs;
      f.close();
    }

    fs::path vencordPluginsDir = fs::path(appData) / "Vencord" / "plugins";
    if (fs::exists(fs::path(appData) / "Vencord")) {
      if (!fs::exists(vencordPluginsDir)) fs::create_directories(vencordPluginsDir);
      std::ofstream fV((vencordPluginsDir / (pluginId + ".plugin.js")).string());
      if (fV.is_open()) { fV << pluginJs; fV.close(); }
    }
  }
}


inline std::string base64Encode(const std::string &in) {
  static const char s_b64[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  std::string out;
  int val = 0, valb = -6;
  for (unsigned char c : in) {
    val = (val << 8) + c;
    valb += 8;
    while (valb >= 0) {
      out.push_back(s_b64[(val >> valb) & 0x3F]);
      valb -= 6;
    }
  }
  if (valb > -6) out.push_back(s_b64[((val << 8) >> (valb + 8)) & 0x3F]);
  while (out.size() % 4) out.push_back('=');
  return out;
}

inline std::string base64Decode(const std::string &in) {
  static const std::string b64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  std::vector<int> T(256, -1);
  for (int i = 0; i < 64; i++) T[b64[i]] = i;
  std::string out;
  int val = 0, valb = -8;
  for (unsigned char c : in) {
    if (T[c] == -1) break;
    val = (val << 6) + T[c];
    valb += 6;
    if (valb >= 0) {
      out.push_back(char((val >> valb) & 0xFF));
      valb -= 8;
    }
  }
  return out;
}


inline void ensureDiscordSkipUpdateFlags() {
  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    fs::path sPath = fs::path(appData) / "discord" / "settings.json";
    std::error_code ec;
    if (fs::exists(sPath, ec)) {
      try {
        std::ifstream fIn(sPath.string());
        std::string content((std::istreambuf_iterator<char>(fIn)), std::istreambuf_iterator<char>());
        fIn.close();
        bool changed = false;
        if (content.find("SKIP_HOST_UPDATE") == std::string::npos) {
          size_t brace = content.rfind('}');
          if (brace != std::string::npos) {
            std::string extra = ",\n  \"SKIP_HOST_UPDATE\": true,\n  \"SKIP_MODULE_UPDATE\": true,\n  \"DESKTOP_TTI_EARLY_UPDATE_CHECK\": false\n}\n";
            content = content.substr(0, brace) + extra;
            changed = true;
          }
        }
        if (changed) {
          std::ofstream fOut(sPath.string());
          if (fOut.is_open()) {
            fOut << content;
            fOut.close();
          }
        }
      } catch (...) {}
    }
  }
}

inline void ensureDiscordModules(const std::wstring &realExe) {
  try {
    fs::path appDir = fs::path(realExe).parent_path();
    std::string ver = appDir.filename().string();
    if (ver.find("app-") == 0) ver = ver.substr(4);
    if (ver.empty()) return;

    wchar_t appData[MAX_PATH];
    if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) == 0) return;
    fs::path targetModulesDir = fs::path(appData) / "discord" / ver / "modules";
    fs::path coreTarget = targetModulesDir / "discord_desktop_core";

    if (!fs::exists(coreTarget)) {
      std::error_code ec;
      fs::create_directories(targetModulesDir, ec);
      fs::path srcModulesDir = appDir / "modules";
      if (fs::exists(srcModulesDir, ec)) {
        for (const auto &item : fs::directory_iterator(srcModulesDir, ec)) {
          if (item.is_directory()) {
            for (const auto &inner : fs::directory_iterator(item.path(), ec)) {
              if (inner.is_directory()) {
                fs::path dest = targetModulesDir / inner.path().filename();
                if (!fs::exists(dest, ec)) {
                  fs::copy(inner.path(), dest, fs::copy_options::recursive | fs::copy_options::overwrite_existing, ec);
                }
              }
            }
          }
        }
      }
    }

    fs::path installedJson = targetModulesDir / "installed.json";
    if (!fs::exists(installedJson)) {
      std::ofstream fOut(installedJson.string());
      if (fOut.is_open()) {
        fOut << "{\n"
             << "  \"discord_desktop_core\": { \"installedVersion\": 1 },\n"
             << "  \"discord_voice\": { \"installedVersion\": 1 },\n"
             << "  \"discord_krisp\": { \"installedVersion\": 1 },\n"
             << "  \"discord_utils\": { \"installedVersion\": 1 },\n"
             << "  \"discord_spellcheck\": { \"installedVersion\": 1 },\n"
             << "  \"discord_notifications\": { \"installedVersion\": 1 },\n"
             << "  \"discord_rpc\": { \"installedVersion\": 1 },\n"
             << "  \"discord_erlpack\": { \"installedVersion\": 1 },\n"
             << "  \"discord_zstd\": { \"installedVersion\": 1 },\n"
             << "  \"discord_media\": { \"installedVersion\": 1 },\n"
             << "  \"discord_game_utils\": { \"installedVersion\": 1 },\n"
             << "  \"discord_overlay2\": { \"installedVersion\": 1 },\n"
             << "  \"discord_dispatch\": { \"installedVersion\": 1 },\n"
             << "  \"discord_hook\": { \"installedVersion\": 1 },\n"
             << "  \"discord_modules\": { \"installedVersion\": 1 },\n"
             << "  \"discord_clips\": { \"installedVersion\": 1 },\n"
             << "  \"discord_cloudsync\": { \"installedVersion\": 1 }\n"
             << "}\n";
        fOut.close();
      }
    }
  } catch (...) {}
}

// Prepara e valida a integração antes de encerrar uma sessão já aberta.
// Assim uma falha de arquivo não derruba o Discord que o usuário já está usando.
bool prepareDiscordForLaunch(const std::wstring &exePath, std::wstring *resolvedExe = nullptr) {
  ensureDiscordSkipUpdateFlags();
  std::wstring realExe = exePath;
  if (realExe.empty()) realExe = locateDiscordExe();
  if (realExe.empty() || !fs::exists(fs::path(realExe))) return false;

  ensureDiscordModules(realExe);
  syncBetterDiscordThemesConfig();
  installDiscordThemeHook(realExe);

  bool hookReady = false;
  try {
    fs::path modulesDir = fs::path(realExe).parent_path() / "modules";
    if (fs::exists(modulesDir)) {
      for (const auto &entry : fs::directory_iterator(modulesDir)) {
        if (!entry.is_directory() || entry.path().filename().string().find("discord_desktop_core") != 0) continue;
        fs::path nested = entry.path() / "discord_desktop_core";
        fs::path indexJs = (fs::exists(nested) ? nested : entry.path()) / "index.js";
        std::ifstream input(indexJs.string(), std::ios::binary);
        if (!input.is_open()) continue;
        std::string content((std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
        if (content.find("Discord Unlock Master Core Hook") != std::string::npos) {
          hookReady = true;
          break;
        }
      }
    }
  } catch (...) {}

  if (resolvedExe) *resolvedExe = realExe;
  return hookReady;
}
// Alguns instaladores recentes do Discord encerram quando iniciados por um processo elevado.
// Esta alternativa usa o token normal do Explorer e só é ativada na edição de suporte individual.
bool launchDiscordFromExplorer(const std::wstring &exePath, const std::wstring &args) {
  DWORD activeSession = 0;
  ProcessIdToSessionId(GetCurrentProcessId(), &activeSession);
  HANDLE snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
  if (snapshot == INVALID_HANDLE_VALUE) return false;

  DWORD explorerPid = 0;
  PROCESSENTRY32W entry = { sizeof(entry) };
  if (Process32FirstW(snapshot, &entry)) {
    do {
      if (_wcsicmp(entry.szExeFile, L"explorer.exe") != 0) continue;
      DWORD explorerSession = 0;
      if (ProcessIdToSessionId(entry.th32ProcessID, &explorerSession) && explorerSession == activeSession) {
        explorerPid = entry.th32ProcessID;
        break;
      }
    } while (Process32NextW(snapshot, &entry));
  }
  CloseHandle(snapshot);
  if (explorerPid == 0) return false;

  HANDLE explorer = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, explorerPid);
  if (!explorer) return false;
  HANDLE token = nullptr, primaryToken = nullptr;
  bool launched = false;
  if (OpenProcessToken(explorer, TOKEN_QUERY | TOKEN_DUPLICATE | TOKEN_ASSIGN_PRIMARY, &token) &&
      DuplicateTokenEx(token, MAXIMUM_ALLOWED, nullptr, SecurityImpersonation, TokenPrimary, &primaryToken)) {
    const fs::path exe(exePath);
    const std::wstring command = L"\"" + exePath + L"\" " + args;
    std::vector<wchar_t> buffer(command.begin(), command.end());
    buffer.push_back(L'\0');
    STARTUPINFOW startup = { sizeof(startup) };
    startup.dwFlags = STARTF_USESHOWWINDOW;
    startup.wShowWindow = SW_SHOWNORMAL;
    PROCESS_INFORMATION process = {};
    if (CreateProcessWithTokenW(primaryToken, LOGON_WITH_PROFILE, nullptr, buffer.data(),
          CREATE_NEW_PROCESS_GROUP, nullptr, exe.parent_path().c_str(), &startup, &process)) {
      CloseHandle(process.hThread);
      CloseHandle(process.hProcess);
      launched = true;
    }
  }
  if (primaryToken) CloseHandle(primaryToken);
  if (token) CloseHandle(token);
  CloseHandle(explorer);
  return launched;
}
bool launchDiscord(const std::wstring &exePath, const std::string &proxyEndpoint) {
  std::wstring realExe;
  if (!prepareDiscordForLaunch(exePath, &realExe)) return false;

  // Native Discord execution — TUN engine (sing-box) handles network routing at kernel level
  std::wstring discordArgs = L"--ignore-certificate-errors --force-webrtc-ip-handling-policy=default";

  fs::path pExe(realExe);
  std::wstring workingDir = pExe.parent_path().wstring();

  // Preserve the active Discord session and its user-selected presence. Explicit
  // restart actions terminate Discord before calling this function.
  if (isDiscordRunning(realExe)) return true;

  // Launch directly via Discord.exe first (bypasses Squirrel freeze)
  std::wstring cmdLine = L"\"" + realExe + L"\" " + discordArgs;

  STARTUPINFOW si = { sizeof(si) };
  si.dwFlags = STARTF_USESHOWWINDOW;
  si.wShowWindow = SW_SHOWNORMAL;
  PROCESS_INFORMATION pi = { 0 };
  std::vector<wchar_t> cmdBuf(cmdLine.begin(), cmdLine.end());
  cmdBuf.push_back(L'\0');

  BOOL success = CreateProcessW(
      nullptr, cmdBuf.data(), nullptr, nullptr, FALSE,
      CREATE_NEW_PROCESS_GROUP, nullptr,
      workingDir.empty() ? nullptr : workingDir.c_str(), &si, &pi);

  if (success) {
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);
    std::this_thread::sleep_for(std::chrono::milliseconds(1200));
    if (isDiscordRunning(realExe)) return true;
    success = FALSE;
  }

  if (!success) {
    // Fallback to Update.exe if direct launch fails
    fs::path updateExe = pExe.parent_path().parent_path() / "Update.exe";
    if (fs::exists(updateExe)) {
      cmdLine = L"\"" + updateExe.wstring() + L"\" --processStart Discord.exe --process-start-args \"" + discordArgs + L"\"";
      cmdBuf.assign(cmdLine.begin(), cmdLine.end());
      cmdBuf.push_back(L'\0');
      workingDir = updateExe.parent_path().wstring();
      success = CreateProcessW(
          nullptr, cmdBuf.data(), nullptr, nullptr, FALSE,
          CREATE_NEW_PROCESS_GROUP, nullptr,
          workingDir.empty() ? nullptr : workingDir.c_str(), &si, &pi);
    }
  }

  if (success) {
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);
    // CreateProcess apenas confirma que o launcher iniciou. Confirma que um
    // processo real do Discord apareceu antes de informar sucesso para a UI.
    for (int attempt = 0; attempt < 30; ++attempt) {
      if (isDiscordRunning(realExe)) return true;
      std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
  }
#ifdef FRIEND_DISCORD_LAUNCH_FALLBACK
  // Última tentativa: abre pelo Explorer, em integridade normal, após o launcher do Discord falhar.
  if (launchDiscordFromExplorer(realExe, discordArgs)) {
    for (int attempt = 0; attempt < 30; ++attempt) {
      if (isDiscordRunning(realExe)) return true;
      std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
  }
#endif
  return false;
}

void prepareBrowserExtension() {
  try {
    wchar_t appData[MAX_PATH] = {0};
    if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) == 0) return;
    fs::path extDir = fs::path(appData) / "DiscordUnlock" / "browser_extension";
    std::error_code ec;
    fs::create_directories(extDir, ec);

    const std::string manifest = R"JSON({
  "manifest_version": 3,
  "name": "Discord Unlock Web Theme",
  "version": "3.1",
  "description": "Aplica temas e papeis de parede locais no Discord Web",
  "content_scripts": [
    {
      "matches": ["https://discord.com/*", "https://*.discord.com/*"],
      "js": ["content.js"],
      "run_at": "document_start",
      "all_frames": false
    }
  ],
  "web_accessible_resources": [
    {
      "resources": ["wallpaper.mp4", "wallpaper.webm"],
      "matches": ["https://discord.com/*", "https://*.discord.com/*"]
    }
  ]
})JSON";
    std::ofstream fManifest((extDir / "manifest.json").string(), std::ios::binary | std::ios::trunc);
    if (fManifest.is_open()) fManifest << manifest;

    fs::path themePath = fs::path(appData) / "discord" / "discord_unlock_theme.css";
    fs::path wallpaperPath = fs::path(appData) / "discord" / "discord_unlock_wallpaper.json";
    std::string activeCss;
    if (fs::exists(themePath, ec)) {
      std::ifstream fTheme(themePath.string(), std::ios::binary);
      if (fTheme.is_open()) { std::stringstream ss; ss << fTheme.rdbuf(); activeCss = ss.str(); }
    }

    const bool hasActiveTheme = !activeCss.empty() &&
      activeCss.find("Default Discord Theme Restored") == std::string::npos &&
      activeCss.find("Default Restored") == std::string::npos;

    std::string videoAsset;
    std::string remoteVideoUrl;
    if (fs::exists(wallpaperPath, ec)) {
      try {
        std::ifstream fWallpaper(wallpaperPath.string(), std::ios::binary);
        std::stringstream rawStream; rawStream << fWallpaper.rdbuf();
        const std::string wallpaper = rawStream.str();
        const bool isVideo = extractJsonField(wallpaper, "isVideo") == "true";
        if (isVideo) {
          const std::string assetPath = extractJsonField(wallpaper, "assetPath");
          if (!assetPath.empty() && fs::exists(fs::path(assetPath), ec)) {
            std::string extension = fs::path(assetPath).extension().string();
            std::transform(extension.begin(), extension.end(), extension.begin(), [](unsigned char c) { return (char)std::tolower(c); });
            if (extension == ".mp4" || extension == ".webm") {
              videoAsset = "wallpaper" + extension;
              fs::copy_file(fs::path(assetPath), extDir / videoAsset, fs::copy_options::overwrite_existing, ec);
              if (ec) videoAsset.clear();
            }
          }
          if (videoAsset.empty()) {
            const std::string source = extractJsonField(wallpaper, "videoUri");
            if (source.rfind("https://", 0) == 0 || source.rfind("http://", 0) == 0) remoteVideoUrl = source;
          }
        }
      } catch (...) {}
    }

    // Sem tema ativo o Discord Web recebe apenas uma base escura. Com tema ativo,
    // nao sobrescrevemos #app-mount: imagens e video precisam permanecer visiveis.
    if (!hasActiveTheme) {
      activeCss += "\nhtml, body, #app-mount { background: #0b1020 !important; color-scheme: dark !important; }\n";
    } else {
      activeCss += "\nhtml, body { background: #0b1020 !important; color-scheme: dark !important; }\n";
    }

    auto quoteForJs = [](const std::string &value) {
      std::string escaped;
      escaped.reserve(value.size() + 16);
      for (char c : value) {
        if (c == '\\') escaped += "\\";
        else if (c == '\"') escaped += "\\\"";
        else if (c == '\n') escaped += "\\n";
        else if (c != '\r') escaped += c;
      }
      return std::string("\"") + escaped + "\"";
    };

    std::string contentJs = R"JS((() => {
  const styleId = 'discord-unlock-web-style';
  const videoId = 'discord-unlock-web-wallpaper';
  const css = __DU_CSS__;
  const bundledVideo = __DU_VIDEO_ASSET__;
  const remoteVideo = __DU_REMOTE_VIDEO__;

  function applyCss() {
    const root = document.head || document.documentElement;
    if (!root) return;
    let style = document.getElementById(styleId);
    if (!style) { style = document.createElement('style'); style.id = styleId; root.appendChild(style); }
    if (style.textContent !== css) style.textContent = css;
  }

  function applyWallpaper() {
    const source = bundledVideo && typeof chrome !== 'undefined' && chrome.runtime
      ? chrome.runtime.getURL(bundledVideo) : remoteVideo;
    let video = document.getElementById(videoId);
    if (!source) { if (video) video.remove(); return; }
    if (!video) {
      video = document.createElement('video');
      video.id = videoId;
      video.muted = true; video.defaultMuted = true; video.loop = true; video.autoplay = true; video.playsInline = true;
      video.setAttribute('aria-hidden', 'true');
      video.style.cssText = 'position:fixed;inset:0;width:100vw;height:100vh;object-fit:cover;z-index:0;pointer-events:none;background:#0b1020;';
      (document.body || document.documentElement).prepend(video);
    }
    if (video.dataset.duSource !== source) {
      video.dataset.duSource = source;
      video.src = source;
      video.load();
    }
    const mount = document.getElementById('app-mount');
    if (mount) { mount.style.setProperty('position', 'relative', 'important'); mount.style.setProperty('z-index', '1', 'important'); }
    if (!document.hidden) video.play().catch(() => {});
  }

  function applyAll() { applyCss(); applyWallpaper(); }
  applyAll();
  document.addEventListener('DOMContentLoaded', applyAll, { once: true });
  if (!window.__discordUnlockWebThemeHook) {
    window.__discordUnlockWebThemeHook = true;
    document.addEventListener('visibilitychange', () => {
      const video = document.getElementById(videoId);
      if (!video) return;
      if (document.hidden) video.pause(); else video.play().catch(() => {});
    });
    const root = document.documentElement;
    if (root) new MutationObserver(() => { if (!document.getElementById(styleId)) applyCss(); if (!document.getElementById(videoId)) applyWallpaper(); }).observe(root, { childList: true, subtree: true });
  }
})();
)JS";
    const auto replaceToken = [&](const std::string &token, const std::string &value) {
      const size_t pos = contentJs.find(token);
      if (pos != std::string::npos) contentJs.replace(pos, token.size(), quoteForJs(value));
    };
    replaceToken("__DU_CSS__", activeCss);
    replaceToken("__DU_VIDEO_ASSET__", videoAsset);
    replaceToken("__DU_REMOTE_VIDEO__", remoteVideoUrl);

    std::ofstream fContent((extDir / "content.js").string(), std::ios::binary | std::ios::trunc);
    if (fContent.is_open()) fContent << contentJs;
  } catch (...) {}
}
bool launchBrowserDiscord(const std::wstring &inExePath, const std::string &proxyEndpoint) {
  prepareBrowserExtension();

  std::wstring exePath = inExePath;
  if (exePath.empty()) exePath = locateBrowserExe();

  bool isFirefox = false;
  if (!exePath.empty()) {
    std::wstring lowerExe = exePath;
    for (auto &c : lowerExe) c = towlower(c);
    if (lowerExe.find(L"firefox") != std::wstring::npos) {
      isFirefox = true;
    }
  }

  // 1. Tentar executar em modo aplicativo nativo no navegador Chromium (Chrome, Edge, Brave, Opera)
  if (!exePath.empty() && !isFirefox) {
    std::wstring wProxy = toWide(proxyEndpoint);
    wchar_t appData[MAX_PATH] = {0};
    GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH);
    fs::path profilePath = fs::path(appData) / "DiscordUnlock" / "web_profile";
    std::error_code profileEc;
    fs::create_directories(profilePath, profileEc);
    std::wstring userDataDir = profilePath.wstring();
    std::wstring extDir = (fs::path(appData) / "DiscordUnlock" / "browser_extension").wstring();

    std::wstring cmdLine = L"\"" + exePath + L"\"";
    if (!proxyEndpoint.empty() && proxyEndpoint != "DIRECT" &&
        proxyEndpoint.find("wiresock://") == std::string::npos &&
        proxyEndpoint.find("wireguard://") == std::string::npos) {
      cmdLine += L" --proxy-server=\"" + wProxy + L"\"";
    }
    cmdLine += L" --user-data-dir=\"" + userDataDir + L"\"" +
               L" --disable-extensions-except=\"" + extDir + L"\"" +
               L" --load-extension=\"" + extDir + L"\"" +
               L" --no-first-run --no-default-browser-check" +
               L" --disable-background-networking" +
               L" --disable-background-timer-throttling" +
               L" --disable-client-side-phishing-detection" +
               L" --disable-default-apps" +
               L" --disable-sync" +
               L" --disable-translate" +
               L" --app=\"https://discord.com/app\"";

    STARTUPINFOW si = {sizeof(si)};
    si.cb = sizeof(si);
    PROCESS_INFORMATION pi = {0};
    std::vector<wchar_t> cmdBuf(cmdLine.begin(), cmdLine.end());
    cmdBuf.push_back(L'\0');
    std::wstring workingDir = fs::path(exePath).parent_path().wstring();

    BOOL success = CreateProcessW(
        nullptr, cmdBuf.data(), nullptr, nullptr, FALSE,
        CREATE_NEW_PROCESS_GROUP, nullptr,
        workingDir.empty() ? nullptr : workingDir.c_str(), &si, &pi);

    if (success) {
      CloseHandle(pi.hProcess);
      CloseHandle(pi.hThread);
      return true;
    }

    // 2. Segunda tentativa sem flag de extensão (caso a política de segurança bloqueie extensões descompactadas)
    std::wstring simpleCmd = L"\"" + exePath + L"\" --app=\"https://discord.com/app\"";
    std::vector<wchar_t> simpleBuf(simpleCmd.begin(), simpleCmd.end());
    simpleBuf.push_back(L'\0');
    success = CreateProcessW(
        nullptr, simpleBuf.data(), nullptr, nullptr, FALSE,
        CREATE_NEW_PROCESS_GROUP, nullptr,
        workingDir.empty() ? nullptr : workingDir.c_str(), &si, &pi);

    if (success) {
      CloseHandle(pi.hProcess);
      CloseHandle(pi.hThread);
      return true;
    }
  }

  // 3. Fallback Universal: ShellExecuteW
  // Abre https://discord.com/app de forma 100% garantida no navegador padrão do Windows (Firefox, Opera, Edge, etc.)
  HINSTANCE hInst = ShellExecuteW(nullptr, L"open", L"https://discord.com/app", nullptr, nullptr, SW_SHOWNORMAL);
  if ((INT_PTR)hInst > 32) return true;

  // 4. Sem navegador registrado, informa a falha sem abrir terminal.
  return false;
}

#define WM_POST_TO_WEBVIEW (WM_USER + 101)

void postJsonToUI(const std::string &jsonStr) {
  if (!g_hWnd) return;
  std::wstring *wjson = new std::wstring(toWide(jsonStr));
  PostMessageW(g_hWnd, WM_POST_TO_WEBVIEW, 0, (LPARAM)wjson);
}

std::string getGamerDnsProvider() {
  ULONG bufferSize = 0;
  if (GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, nullptr, nullptr, &bufferSize) != ERROR_BUFFER_OVERFLOW || bufferSize == 0) return "unknown";
  std::vector<unsigned char> buffer(bufferSize);
  auto* adapters = reinterpret_cast<IP_ADAPTER_ADDRESSES*>(buffer.data());
  if (GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, nullptr, adapters, &bufferSize) != NO_ERROR) return "unknown";
  bool cloudflare = false, google = false, other = false;
  for (auto* adapter = adapters; adapter; adapter = adapter->Next) {
    if (adapter->OperStatus != IfOperStatusUp) continue;
    for (auto* dns = adapter->FirstDnsServerAddress; dns; dns = dns->Next) {
      if (!dns->Address.lpSockaddr || dns->Address.lpSockaddr->sa_family != AF_INET) continue;
      const auto* ipv4 = reinterpret_cast<const sockaddr_in*>(dns->Address.lpSockaddr);
      const unsigned long address = ntohl(ipv4->sin_addr.s_addr);
      if (address == 0x01010101UL || address == 0x01000001UL) cloudflare = true;
      else if (address == 0x08080808UL || address == 0x08080404UL) google = true;
      else other = true;
    }
  }
  if (cloudflare && !google && !other) return "cloudflare";
  if (google && !cloudflare && !other) return "google";
  if (cloudflare || google) return "mixed";
  return other ? "default" : "unknown";
}

void postGamerDnsStatus() {
  postJsonToUI("{\"type\":\"dns_gamer_status\",\"provider\":\"" + getGamerDnsProvider() + "\"}");
}

bool runHiddenCommand(const std::wstring &exe, const std::wstring &parameters, DWORD timeoutMs = 30000) {
  std::wstring commandLine = L"\"" + exe + L"\" " + parameters;
  std::vector<wchar_t> buffer(commandLine.begin(), commandLine.end());
  buffer.push_back(L'\0');
  STARTUPINFOW startup = { sizeof(startup) };
  startup.dwFlags = STARTF_USESHOWWINDOW;
  startup.wShowWindow = SW_HIDE;
  PROCESS_INFORMATION process = {};
  if (!CreateProcessW(nullptr, buffer.data(), nullptr, nullptr, FALSE, CREATE_NO_WINDOW,
                      nullptr, nullptr, &startup, &process)) return false;
  const DWORD waited = WaitForSingleObject(process.hProcess, timeoutMs);
  DWORD exitCode = 1;
  if (waited == WAIT_OBJECT_0) GetExitCodeProcess(process.hProcess, &exitCode);
  CloseHandle(process.hThread);
  CloseHandle(process.hProcess);
  return waited == WAIT_OBJECT_0 && exitCode == 0;
}
void applyGamerDns(const std::string &provider) {
  std::thread([provider]() {
    runHiddenCommand(L"ipconfig.exe", L"/flushdns");
    if (provider == "cloudflare") {
      runHiddenCommand(L"powershell.exe", L"-NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -Command \"Get-NetAdapter | Where-Object Status -eq 'Up' | Set-DnsClientServerAddress -ServerAddresses ('1.1.1.1', '1.0.0.1')\"");
    } else if (provider == "google") {
      runHiddenCommand(L"powershell.exe", L"-NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -Command \"Get-NetAdapter | Where-Object Status -eq 'Up' | Set-DnsClientServerAddress -ServerAddresses ('8.8.8.8', '8.8.4.4')\"");
    } else if (provider == "dhcp" || provider == "reset" || provider == "remove") {
      runHiddenCommand(L"powershell.exe", L"-NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -Command \"Get-NetAdapter | Where-Object Status -eq 'Up' | Set-DnsClientServerAddress -ResetServerAddresses\"");
    }
    runHiddenCommand(L"ipconfig.exe", L"/flushdns");
    const std::string activeProvider = getGamerDnsProvider();
    postJsonToUI("{\"type\":\"dns_applied\",\"provider\":\"" + provider + "\",\"activeProvider\":\"" + activeProvider + "\"}");
  }).detach();
}
void sendFeedbackWebhook(const std::string &type, const std::string &message, const std::string &contact) {
  std::thread([type, message, contact]() {
    std::string hwid = toUtf8(getHWID());
    std::string key = getStoredLicenseKey();
    if (key.empty()) key = "Nenhuma / Trial";
    std::string proxy = g_currentProxy.empty() ? "Nenhum (Conexao Direta)" : g_currentProxy;

    wchar_t appData[MAX_PATH];
    GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH);
    fs::path duDir = fs::path(appData) / "DiscordUnlock";
    fs::path duBinDir = duDir / "bin";
    std::error_code ec;
    if (!fs::exists(duBinDir, ec)) fs::create_directories(duBinDir, ec);

    fs::path scriptPath = duBinDir / "send_diagnostic_feedback.ps1";

    wchar_t exePathBuf[MAX_PATH] = { 0 };
    GetModuleFileNameW(nullptr, exePathBuf, MAX_PATH);
    fs::path exeDir = fs::path(exePathBuf).parent_path();
    fs::path exeBinScript = exeDir / "bin" / "send_diagnostic_feedback.ps1";
    fs::path rootBinScript = L"C:/DiscordUnlock\\bin\\send_diagnostic_feedback.ps1";

    if (fs::exists(exeBinScript, ec)) {
      scriptPath = exeBinScript;
    } else if (fs::exists(rootBinScript, ec)) {
      scriptPath = rootBinScript;
    } else if (!fs::exists(scriptPath, ec)) {
      extractResourceToFile(103, scriptPath);
    }

    // Gravar argumentos de forma segura em arquivo JSON temporario
    wchar_t tempPath[MAX_PATH];
    GetTempPathW(MAX_PATH, tempPath);
    fs::path tempArgsJson = fs::path(tempPath) / ("du_diag_args_" + std::to_string(GetTickCount64()) + ".json");
    {
      std::ofstream fArgs(tempArgsJson.string(), std::ios::binary);
      if (fArgs.is_open()) {
        std::string jsonArgs = "{\n"
          "  \"type\": \"" + escapeJsonString(type) + "\",\n"
          "  \"message\": \"" + escapeJsonString(message) + "\",\n"
          "  \"contact\": \"" + escapeJsonString(contact) + "\",\n"
          "  \"hwid\": \"" + escapeJsonString(hwid) + "\",\n"
          "  \"key\": \"" + escapeJsonString(key) + "\",\n"
          "  \"proxy\": \"" + escapeJsonString(proxy) + "\"\n"
          "}";
        fArgs.write(jsonArgs.c_str(), jsonArgs.length());
        fArgs.close();
      }
    }

    bool sent = false;

    // Disparar o script PowerShell com diagnostico completo e anexo de log
    if (fs::exists(scriptPath, ec)) {
      std::wstring cmdLine = L"powershell.exe -ExecutionPolicy Bypass -WindowStyle Hidden -File \"" + scriptPath.wstring() + L"\" -ArgsJsonPath \"" + tempArgsJson.wstring() + L"\"";
      STARTUPINFOW si;
      PROCESS_INFORMATION pi;
      ZeroMemory(&si, sizeof(si));
      si.cb = sizeof(si);
      si.dwFlags = STARTF_USESHOWWINDOW;
      si.wShowWindow = SW_HIDE;
      ZeroMemory(&pi, sizeof(pi));

      std::vector<wchar_t> cmdBuf(cmdLine.begin(), cmdLine.end());
      cmdBuf.push_back(L'\0');

      if (CreateProcessW(nullptr, cmdBuf.data(), nullptr, nullptr, FALSE, CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT, nullptr, nullptr, &si, &pi)) {
        DWORD waitRes = WaitForSingleObject(pi.hProcess, 35000);
        if (waitRes == WAIT_OBJECT_0) {
          DWORD exitCode = 1;
          if (GetExitCodeProcess(pi.hProcess, &exitCode) && exitCode == 0) {
            sent = true;
          }
        }
        CloseHandle(pi.hProcess);
        CloseHandle(pi.hThread);
      }
    }

    // Fallback WinHTTP caso PowerShell seja restrito na maquina
    if (!sent) {
      bool isBugType = (type == "bug" || type == "Bug" || type.find("bug") != std::string::npos || type.find("Bug") != std::string::npos);
      std::string title = isBugType ? "🐛 Relatório de Bug - Discord Unlock" : "💡 Nova Sugestão - Discord Unlock";
      std::string color = isBugType ? "15158332" : "3447003";
      std::string payload = "{\"embeds\":[{"
                            "\"title\":\"" + escapeJsonString(title) + "\","
                            "\"description\":\"" + escapeJsonString(message) + "\","
                            "\"color\":" + color + ","
                            "\"fields\":["
                            "{\"name\":\"Tipo\",\"value\":\"" + escapeJsonString(type) + "\",\"inline\":true},"
                            "{\"name\":\"Contato\",\"value\":\"" + escapeJsonString(contact.empty() ? "Não informado" : contact) + "\",\"inline\":true},"
                            "{\"name\":\"Proxy Ativo\",\"value\":\"" + escapeJsonString(proxy) + "\",\"inline\":true}"
                            "],"
                            "\"footer\":{\"text\":\"ID: " + escapeJsonString(hwid) + " | Chave: " + escapeJsonString(key) + "\"}"
                            "}]}";
      HINTERNET hSession = WinHttpOpen(L"DiscordUnlock/3.3", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0);
      if (hSession) {
        WinHttpSetTimeouts(hSession, 3000, 4000, 4000, 6000);
        HINTERNET hConnect = WinHttpConnect(hSession, L"discord.com", INTERNET_DEFAULT_HTTPS_PORT, 0);
        if (hConnect) {
          HINTERNET hRequest = WinHttpOpenRequest(hConnect, L"POST", L"/api/webhooks/1543779966792237116/Yqoc4dBBoXxXB1J4RFn_SmKqHxlM1CgLF1OTHgB_v4HsdTfzz4dmlumtfl__hl3mfzxO", nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, WINHTTP_FLAG_SECURE);
          if (hRequest) {
            std::wstring headers = L"Content-Type: application/json\r\nUser-Agent: DiscordUnlock\r\n";
            if (WinHttpSendRequest(hRequest, headers.c_str(), headers.length(), (LPVOID)payload.c_str(), payload.length(), payload.length(), 0)) {
              if (WinHttpReceiveResponse(hRequest, nullptr)) {
                DWORD statusCode = 0;
                DWORD statusSize = sizeof(statusCode);
                if (WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &statusSize, WINHTTP_NO_HEADER_INDEX)) {
                  if (statusCode >= 200 && statusCode < 300) {
                    sent = true;
                  }
                }
              }
            }
            WinHttpCloseHandle(hRequest);
          }
          WinHttpCloseHandle(hConnect);
        }
        WinHttpCloseHandle(hSession);
      }
    }

    fs::remove(tempArgsJson, ec);
    postJsonToUI("{\"type\":\"feedback_sent\",\"success\":" + std::string(sent ? "true" : "false") + ",\"message\":\"" + escapeJsonString(sent ? "Relatório enviado com diagnóstico anexado." : "Não foi possível enviar o relatório agora. Verifique a conexão e tente novamente.") + "\"}");
  }).detach();
}

void openCloudFilePickerAsync(HWND hWnd, const std::string &eventType = "cloud_file_selected") {
  // A caixa de diálogo comum precisa ser aberta na thread da janela. Em uma
  // thread auxiliar ela pode não aparecer, especialmente com WebView2 em foco.
  OPENFILENAMEW ofn;
  wchar_t szFile[32768] = { 0 };
  ZeroMemory(&ofn, sizeof(ofn));
  ofn.lStructSize = sizeof(ofn);
  ofn.hwndOwner = hWnd;
  ofn.lpstrFile = szFile;
  ofn.nMaxFile = static_cast<DWORD>(sizeof(szFile) / sizeof(szFile[0]));
  ofn.lpstrFilter = L"Todos os Arquivos (*.*)\0*.*\0Videos (*.mp4;*.mkv;*.mov;*.avi)\0*.mp4;*.mkv;*.mov;*.avi\0Compactados (*.zip;*.rar;*.7z)\0*.zip;*.rar;*.7z\0Imagens (*.png;*.jpg;*.gif;*.webp)\0*.png;*.jpg;*.gif;*.webp\0\0";
  ofn.nFilterIndex = 1;
  ofn.lpstrTitle = L"Selecione o arquivo para enviar";
  ofn.Flags = OFN_PATHMUSTEXIST | OFN_FILEMUSTEXIST | OFN_NOCHANGEDIR | OFN_EXPLORER | OFN_HIDEREADONLY;
  if (GetOpenFileNameW(&ofn)) {
    std::string pathUtf8 = toUtf8(szFile);
    postJsonToUI(std::string(R"({"type":")") + eventType + R"(","filePath":")" + escapeJsonString(pathUtf8) + "\"}");
  } else {
    const DWORD dialogError = CommDlgExtendedError();
    if (dialogError != 0) {
      postJsonToUI(std::string("{\"type\":\"toast\",\"success\":false,\"message\":\"Nao foi possivel abrir o seletor de arquivos (codigo ") + std::to_string(dialogError) + ").\"}");
    }
  }
}

fs::path getCloudAccountTokenPath() {
  wchar_t appData[MAX_PATH] = {0};
  GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH);
  return fs::path(appData) / "DiscordUnlock" / "gofile_token.dat";
}

bool saveProtectedCloudAccountToken(const std::string &token) {
  if (token.size() < 20 || token.size() > 256) return false;
  for (unsigned char c : token) {
    if (!(std::isalnum(c) || c == '-' || c == '_')) return false;
  }
  DATA_BLOB plain{};
  plain.cbData = static_cast<DWORD>(token.size());
  plain.pbData = reinterpret_cast<BYTE *>(const_cast<char *>(token.data()));
  DATA_BLOB protectedData{};
  if (!CryptProtectData(&plain, L"Discord Unlock - Gofile", nullptr, nullptr, nullptr,
                        CRYPTPROTECT_UI_FORBIDDEN, &protectedData)) {
    return false;
  }

  const fs::path path = getCloudAccountTokenPath();
  std::error_code ec;
  fs::create_directories(path.parent_path(), ec);
  std::ofstream output(path, std::ios::binary | std::ios::trunc);
  bool ok = output.is_open();
  if (ok) {
    output.write(reinterpret_cast<const char *>(protectedData.pbData), protectedData.cbData);
    ok = output.good();
  }
  if (protectedData.pbData) {
    SecureZeroMemory(protectedData.pbData, protectedData.cbData);
    LocalFree(protectedData.pbData);
  }
  if (!ok) fs::remove(path, ec);

  // Remove o formato legado que guardava o token em texto simples.
  fs::remove(path.parent_path() / "gofile_account.json", ec);
  return ok;
}

bool deleteProtectedCloudAccountToken() {
  std::error_code ec;
  const fs::path path = getCloudAccountTokenPath();
  fs::remove(path, ec);
  fs::remove(path.parent_path() / "gofile_account.json", ec);
  return !fs::exists(path, ec);
}

void getCloudAccountInfoAsync() {
  std::thread([]() {
    wchar_t exePath[MAX_PATH] = {0};
    GetModuleFileNameW(nullptr, exePath, MAX_PATH);
    fs::path binScript = fs::path(exePath).parent_path() / "bin" / "get_cloud_account.ps1";
    std::error_code ec;
    if (!fs::exists(binScript, ec)) {
      binScript = L"C:/DiscordUnlock\\bin\\get_cloud_account.ps1";
    }
    if (!fs::exists(binScript, ec)) {
      wchar_t appData[MAX_PATH] = {0};
      GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH);
      fs::path embeddedScript = fs::path(appData) / "DiscordUnlock" / "bin" / "get_cloud_account.ps1";
      if (extractResourceToFile(105, embeddedScript)) binScript = embeddedScript;
    }
    if (!fs::exists(binScript, ec)) {
      postJsonToUI(R"({"type":"cloud_account_info","connected":false,"storageBytes":0,"fileCount":0,"error":"Componente de conta nao encontrado."})");
      return;
    }

    std::wstring cmdLine = L"powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File \"" + binScript.wstring() + L"\"";

    HANDLE hReadPipe = nullptr, hWritePipe = nullptr;
    SECURITY_ATTRIBUTES sa = { sizeof(sa), nullptr, TRUE };
    if (!CreatePipe(&hReadPipe, &hWritePipe, &sa, 0)) return;
    SetHandleInformation(hReadPipe, HANDLE_FLAG_INHERIT, 0);

    STARTUPINFOW si = { sizeof(si) };
    si.cb = sizeof(si);
    si.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
    si.hStdOutput = hWritePipe;
    si.hStdError = hWritePipe;
    si.wShowWindow = SW_HIDE;
    PROCESS_INFORMATION pi = { 0 };

    std::vector<wchar_t> cmdBuf(cmdLine.begin(), cmdLine.end());
    cmdBuf.push_back(L'\0');

    if (!CreateProcessW(nullptr, cmdBuf.data(), nullptr, nullptr, TRUE, CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT, nullptr, nullptr, &si, &pi)) {
      CloseHandle(hReadPipe);
      CloseHandle(hWritePipe);
      return;
    }

    CloseHandle(hWritePipe);
    hWritePipe = nullptr;

    std::string lineAccumulator;
    char readBuf[1024];
    DWORD bytesRead = 0;

    while (ReadFile(hReadPipe, readBuf, sizeof(readBuf), &bytesRead, nullptr) && bytesRead > 0) {
      for (DWORD i = 0; i < bytesRead; ++i) {
        char ch = readBuf[i];
        if (ch == '\n' || ch == '\r') {
          if (!lineAccumulator.empty()) {
            if (lineAccumulator.size() >= 3 && static_cast<unsigned char>(lineAccumulator[0]) == 0xEF && static_cast<unsigned char>(lineAccumulator[1]) == 0xBB && static_cast<unsigned char>(lineAccumulator[2]) == 0xBF) lineAccumulator.erase(0, 3);
            if (!lineAccumulator.empty() && lineAccumulator.front() == '{' && lineAccumulator.back() == '}') {
              postJsonToUI(lineAccumulator);
            }
            lineAccumulator.clear();
          }
        } else {
          lineAccumulator.push_back(ch);
        }
      }
    }

    if (!lineAccumulator.empty()) {
      if (lineAccumulator.size() >= 3 && static_cast<unsigned char>(lineAccumulator[0]) == 0xEF && static_cast<unsigned char>(lineAccumulator[1]) == 0xBB && static_cast<unsigned char>(lineAccumulator[2]) == 0xBF) lineAccumulator.erase(0, 3);
            if (!lineAccumulator.empty() && lineAccumulator.front() == '{' && lineAccumulator.back() == '}') {
        postJsonToUI(lineAccumulator);
      }
    }

    WaitForSingleObject(pi.hProcess, 3000);
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);
    CloseHandle(hReadPipe);
  }).detach();
}

void publishCloudUploadResult(const std::string &line, const std::string &messageConversationId) {
  if (messageConversationId.empty()) { postJsonToUI(line); return; }
  const bool success = line.find("\"success\":true") != std::string::npos;
  const std::string url = extractJsonField(line, "url");
  if (success && !url.empty()) {
    const std::string fileName = extractJsonField(line, "fileName");
    postJsonToUI(R"({"type":"cloud_message_upload_result","success":true,"message":"Upload concluido. Enviando o link na conversa."})");
    sendCloudMessageAsync(messageConversationId, "Arquivo compartilhado" + (fileName.empty() ? std::string() : ": " + fileName) + "\n" + url);
    return;
  }
  postJsonToUI(std::string(R"({"type":"cloud_message_upload_result","success":false,"message":")") + escapeJsonString(extractJsonField(line, "error")) + "\"}");
}
void postRecorderCloudUploadProgress(const std::string &stage, int percent, const std::wstring &filePath,
                                     const std::string &message, bool success = true) {
  const int safePercent = (std::max)(0, (std::min)(100, percent));
  // filename().string() usa a página de código local no Windows. O WebView exige UTF-8.
  const std::string fileNameUtf8 = toUtf8(fs::path(filePath).filename().wstring());
  postJsonToUI(std::string(R"({"type":"recorder_upload_progress","stage":")") + escapeJsonString(stage) +
    R"(","percent":)" + std::to_string(safePercent) + R"(,"fileName":") +
    escapeJsonString(fileNameUtf8) + R"(","message":") +
    escapeJsonString(message) + R"(","success":)" + (success ? "true" : "false") + "}");
}

void postRecorderManualUploadComplete(const std::wstring &filePath) {
  const std::string fileNameUtf8 = toUtf8(fs::path(filePath).filename().wstring());
  postJsonToUI(std::string(R"({"type":"recorder_manual_upload_complete","filePath":")") +
    escapeJsonString(toUtf8(filePath)) + R"(","fileName":") +
    escapeJsonString(fileNameUtf8) + R"("})");
}

void cleanupLocalRecordingAfterCloudUpload(const std::wstring &filePath, const std::string &messageConversationId,
                                           const std::string &result, bool recorderUpload,
                                           bool automaticRecorderUpload) {
  if (!messageConversationId.empty() || extractJsonField(result, "success") != "true") return;
  const auto settings = DiscordUnlock::ScreenRecorder::Instance().GetSettings();
  const bool mayDeleteAutomatically = automaticRecorderUpload && settings.autoUploadDeleteLocal;
  if (!mayDeleteAutomatically) {
    if (recorderUpload) {
      if (automaticRecorderUpload) {
        postRecorderCloudUploadProgress("concluido", 100, filePath, "Link verificado. Vídeo local mantido pela sua configuração.");
      } else {
        // A decisão do envio manual vem da interface e só é tratada depois que a resposta com o link é confirmada.
        postRecorderManualUploadComplete(filePath);
      }
    }
    return;
  }
  if (recorderUpload) postRecorderCloudUploadProgress("deletando", 100, filePath, "Link verificado. Removendo o vídeo local...");
  std::error_code removeError;
  const bool removed = fs::remove(filePath, removeError);
  const bool alreadyGone = !fs::exists(filePath, removeError);
  const bool success = removed || alreadyGone;
  postJsonToUI(std::string(R"({"type":"cloud_local_cleanup","success":)") + (success ? "true" : "false") +
    R"(,"message":") + escapeJsonString(success ? "Upload confirmado e arquivo local removido." : "Upload confirmado, mas o Windows não permitiu apagar o arquivo local.") + R"("})");
  if (recorderUpload) postRecorderCloudUploadProgress(success ? "deletado" : "deletando", 100, filePath,
    success ? "Envio concluído e arquivo local removido." : "O link foi confirmado, mas o arquivo local não pôde ser removido.", success);
}
void uploadToCloudGofile(const std::wstring &filePath, const std::string &expiry = "1h",
                         const std::string &messageConversationId = "", bool recorderUpload = false,
                         bool automaticRecorderUpload = false) {
  std::thread([filePath, expiry, messageConversationId, recorderUpload, automaticRecorderUpload]() {
    if (recorderUpload) postRecorderCloudUploadProgress("enviando", 0, filePath, "Preparando envio do vídeo...");
    std::error_code ec;
    if (!fs::exists(filePath, ec)) {
      if (recorderUpload) postRecorderCloudUploadProgress("erro", 0, filePath, "Arquivo local não encontrado. Nada foi apagado.", false);
      postJsonToUI(R"({"type":"cloud_upload_result","success":false,"error":"Arquivo nao encontrado no computador."})");
      return;
    }

    wchar_t exePath[MAX_PATH] = {0};
    GetModuleFileNameW(nullptr, exePath, MAX_PATH);
    fs::path binScript = fs::path(exePath).parent_path() / "bin" / "upload_cloud_file.ps1";
    if (!fs::exists(binScript, ec)) {
      binScript = L"C:/DiscordUnlock\\bin\\upload_cloud_file.ps1";
    }
    if (!fs::exists(binScript, ec)) {
      wchar_t appData[MAX_PATH];
      GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH);
      fs::path duBinScript = fs::path(appData) / "DiscordUnlock" / "bin" / "upload_cloud_file.ps1";
      if (extractResourceToFile(104, duBinScript)) {
        binScript = duBinScript;
      }
    }

    if (!fs::exists(binScript, ec)) {
      if (recorderUpload) postRecorderCloudUploadProgress("erro", 0, filePath, "O componente de upload não foi encontrado. Vídeo preservado.", false);
      postJsonToUI(R"({"type":"cloud_upload_result","success":false,"error":"Script bin/upload_cloud_file.ps1 nao encontrado."})");
      return;
    }

    std::wstring cmdLine = L"powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File \"" + binScript.wstring() + L"\" -FilePath \"" + filePath + L"\" -Expiry \"" + toWide(expiry) + L"\"";

    HANDLE hReadPipe = nullptr, hWritePipe = nullptr;
    SECURITY_ATTRIBUTES sa = { sizeof(sa), nullptr, TRUE };
    if (!CreatePipe(&hReadPipe, &hWritePipe, &sa, 0)) {
      if (recorderUpload) postRecorderCloudUploadProgress("erro", 0, filePath, "Não foi possível iniciar o envio. Vídeo preservado.", false);
      postJsonToUI(R"({"type":"cloud_upload_result","success":false,"error":"Falha ao criar canal de comunicacao."})");
      return;
    }
    SetHandleInformation(hReadPipe, HANDLE_FLAG_INHERIT, 0);

    STARTUPINFOW si = { sizeof(si) };
    si.cb = sizeof(si);
    si.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
    si.hStdOutput = hWritePipe;
    si.hStdError = hWritePipe;
    si.wShowWindow = SW_HIDE;
    PROCESS_INFORMATION pi = { 0 };

    std::vector<wchar_t> cmdBuf(cmdLine.begin(), cmdLine.end());
    cmdBuf.push_back(L'\0');

    if (!CreateProcessW(nullptr, cmdBuf.data(), nullptr, nullptr, TRUE, CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT, nullptr, nullptr, &si, &pi)) {
      CloseHandle(hReadPipe);
      CloseHandle(hWritePipe);
      if (recorderUpload) postRecorderCloudUploadProgress("erro", 0, filePath, "Não foi possível iniciar o envio. Vídeo preservado.", false);
      postJsonToUI(R"({"type":"cloud_upload_result","success":false,"error":"Falha ao iniciar processo de upload."})");
      return;
    }

    CloseHandle(hWritePipe);
    hWritePipe = nullptr;

    std::string lineAccumulator;
    char readBuf[1024];
    DWORD bytesRead = 0;
    bool gotResult = false;

    while (ReadFile(hReadPipe, readBuf, sizeof(readBuf), &bytesRead, nullptr) && bytesRead > 0) {
      for (DWORD i = 0; i < bytesRead; ++i) {
        char ch = readBuf[i];
        if (ch == '\n' || ch == '\r') {
          if (!lineAccumulator.empty()) {
            if (lineAccumulator.size() >= 3 && static_cast<unsigned char>(lineAccumulator[0]) == 0xEF && static_cast<unsigned char>(lineAccumulator[1]) == 0xBB && static_cast<unsigned char>(lineAccumulator[2]) == 0xBF) lineAccumulator.erase(0, 3);
            if (!lineAccumulator.empty() && lineAccumulator.front() == '{' && lineAccumulator.back() == '}') {
                            const std::string responseType = extractJsonField(lineAccumulator, "type");
              // Progresso do gravador já é convertido abaixo para o evento da barra.
              // Não encaminhar o JSON bruto evita que mensagens técnicas afetem a interface.
              publishCloudUploadResult(lineAccumulator, messageConversationId);
              if (recorderUpload && responseType == "cloud_upload_progress") {
                int percent = 0;
                try { percent = std::stoi(extractJsonField(lineAccumulator, "percent")); } catch (...) {}
                postRecorderCloudUploadProgress("enviando", percent, filePath, extractJsonField(lineAccumulator, "message"));
              }
              if (responseType == "cloud_upload_result") {
                gotResult = true;
                const bool confirmed = extractJsonField(lineAccumulator, "success") == "true" && !extractJsonField(lineAccumulator, "url").empty();
                if (recorderUpload) {
                  if (confirmed) {
                    postRecorderCloudUploadProgress("enviado", 100, filePath, "Vídeo enviado. Confirmando o link...");
                    postRecorderCloudUploadProgress("verificando", 100, filePath, "Link confirmado pelo servidor.");
                  } else {
                    postRecorderCloudUploadProgress("erro", 0, filePath, "O envio falhou. O vídeo local foi preservado.", false);
                  }
                }
                cleanupLocalRecordingAfterCloudUpload(filePath, messageConversationId, lineAccumulator, recorderUpload, automaticRecorderUpload);
              }
            }
            lineAccumulator.clear();
          }
        } else {
          lineAccumulator.push_back(ch);
        }
      }
    }

    if (!lineAccumulator.empty()) {
      if (lineAccumulator.size() >= 3 && static_cast<unsigned char>(lineAccumulator[0]) == 0xEF && static_cast<unsigned char>(lineAccumulator[1]) == 0xBB && static_cast<unsigned char>(lineAccumulator[2]) == 0xBF) lineAccumulator.erase(0, 3);
            if (!lineAccumulator.empty() && lineAccumulator.front() == '{' && lineAccumulator.back() == '}') {
                const std::string responseType = extractJsonField(lineAccumulator, "type");
        // Progresso do gravador já é convertido abaixo para o evento da barra.
        // Não encaminhar o JSON bruto evita que mensagens técnicas afetem a interface.
        publishCloudUploadResult(lineAccumulator, messageConversationId);
        if (recorderUpload && responseType == "cloud_upload_progress") {
          int percent = 0;
          try { percent = std::stoi(extractJsonField(lineAccumulator, "percent")); } catch (...) {}
          postRecorderCloudUploadProgress("enviando", percent, filePath, extractJsonField(lineAccumulator, "message"));
        }
        if (responseType == "cloud_upload_result") {
          gotResult = true;
          const bool confirmed = extractJsonField(lineAccumulator, "success") == "true" && !extractJsonField(lineAccumulator, "url").empty();
          if (recorderUpload) {
            if (confirmed) {
              postRecorderCloudUploadProgress("enviado", 100, filePath, "Vídeo enviado. Confirmando o link...");
              postRecorderCloudUploadProgress("verificando", 100, filePath, "Link confirmado pelo servidor.");
            } else {
              postRecorderCloudUploadProgress("erro", 0, filePath, "O envio falhou. O vídeo local foi preservado.", false);
            }
          }
          cleanupLocalRecordingAfterCloudUpload(filePath, messageConversationId, lineAccumulator, recorderUpload, automaticRecorderUpload);
        }
      }
    }

    WaitForSingleObject(pi.hProcess, 3000);
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);
    CloseHandle(hReadPipe);

    if (!gotResult) {
      if (recorderUpload) postRecorderCloudUploadProgress("erro", 0, filePath, "Upload interrompido. O vídeo local foi preservado.", false);
      postJsonToUI(R"({"type":"cloud_upload_result","success":false,"error":"Upload interrompido ou resposta invalida do servidor."})");
    }
  }).detach();
}

struct HotkeyConfigItem {
  bool ctrl = false;
  bool alt = false;
  bool shift = false;
  UINT vkCode = 0;
  std::string text = "";
};

struct AppHotkeysConfig {
  HotkeyConfigItem record = { true, false, false, VK_F9, "Ctrl+F9" };
  HotkeyConfigItem clip = { true, false, false, VK_F10, "Ctrl+F10" };
  HotkeyConfigItem overlay = { false, false, false, VK_F12, "F12" };
};

static AppHotkeysConfig g_hotkeysConfig;
static std::mutex g_hotkeysMutex;

static fs::path getHotkeysConfigPath() {
  wchar_t appDataBuf[MAX_PATH] = {0};
  GetEnvironmentVariableW(L"APPDATA", appDataBuf, MAX_PATH);
  return fs::path(appDataBuf) / "DiscordUnlock" / "hotkeys_config.json";
}

static void loadHotkeysConfig() {
  std::lock_guard<std::mutex> lock(g_hotkeysMutex);
  fs::path p = getHotkeysConfigPath();
  std::error_code ec;
  if (!fs::exists(p, ec)) return;
  std::ifstream fIn(p.string());
  if (!fIn.is_open()) return;
  std::string content((std::istreambuf_iterator<char>(fIn)), std::istreambuf_iterator<char>());
  if (content.empty()) return;

  auto parseItem = [](const std::string& sub, HotkeyConfigItem& item) {
    std::string ctrl = extractJsonField(sub, "ctrl");
    if (!ctrl.empty()) item.ctrl = (ctrl == "true" || ctrl == "1");
    std::string alt = extractJsonField(sub, "alt");
    if (!alt.empty()) item.alt = (alt == "true" || alt == "1");
    std::string shift = extractJsonField(sub, "shift");
    if (!shift.empty()) item.shift = (shift == "true" || shift == "1");
    std::string vk = extractJsonField(sub, "vk");
    if (!vk.empty()) {
      try { item.vkCode = (UINT)std::stoi(vk); } catch(...) {}
    }
    std::string txt = extractJsonField(sub, "text");
    if (!txt.empty()) item.text = txt;
  };

  std::string recStr = extractJsonField(content, "record");
  if (!recStr.empty()) parseItem(recStr, g_hotkeysConfig.record);
  std::string clipStr = extractJsonField(content, "clip");
  if (!clipStr.empty()) parseItem(clipStr, g_hotkeysConfig.clip);
  std::string ovStr = extractJsonField(content, "overlay");
  if (!ovStr.empty()) parseItem(ovStr, g_hotkeysConfig.overlay);
}

static void saveHotkeysConfig() {
  std::lock_guard<std::mutex> lock(g_hotkeysMutex);
  fs::path p = getHotkeysConfigPath();
  std::error_code ec;
  fs::create_directories(p.parent_path(), ec);
  std::ofstream fOut(p.string(), std::ios::trunc);
  if (!fOut.is_open()) return;

  auto itemJson = [](const HotkeyConfigItem& it) {
    return std::string("{\"ctrl\":") + (it.ctrl ? "true" : "false") +
           ",\"alt\":" + (it.alt ? "true" : "false") +
           ",\"shift\":" + (it.shift ? "true" : "false") +
           ",\"vk\":" + std::to_string(it.vkCode) +
           ",\"text\":\"" + escapeJsonString(it.text) + "\"}";
  };

  fOut << "{\n"
       << "  \"record\": " << itemJson(g_hotkeysConfig.record) << ",\n"
       << "  \"clip\": " << itemJson(g_hotkeysConfig.clip) << ",\n"
       << "  \"overlay\": " << itemJson(g_hotkeysConfig.overlay) << "\n"
       << "}\n";
}

static fs::path getRecorderConfigPath() {
  wchar_t appDataBuf[MAX_PATH] = {0};
  GetEnvironmentVariableW(L"APPDATA", appDataBuf, MAX_PATH);
  return fs::path(appDataBuf) / "DiscordUnlock" / "recorder_config.json";
}

static void loadRecorderConfig() {
  fs::path p = getRecorderConfigPath();
  std::error_code ec;
  if (!fs::exists(p, ec)) return;
  std::ifstream fIn(p.string());
  if (!fIn.is_open()) return;
  std::string content((std::istreambuf_iterator<char>(fIn)), std::istreambuf_iterator<char>());
  if (content.empty()) return;

  auto& rec = DiscordUnlock::ScreenRecorder::Instance();
  auto s = rec.GetSettings();

  std::string rmMode = extractJsonField(content, "resolutionMode");
  if (!rmMode.empty()) s.resolutionMode = rmMode;
  std::string rw = extractJsonField(content, "resolutionWidth");
  if (!rw.empty()) { try { s.targetWidth = std::stoi(rw); } catch(...) {} }
  std::string rh = extractJsonField(content, "resolutionHeight");
  if (!rh.empty()) { try { s.targetHeight = std::stoi(rh); } catch(...) {} }
  std::string fpsStr = extractJsonField(content, "fps");
  if (!fpsStr.empty()) { try { s.fps = std::stoi(fpsStr); } catch(...) {} }
  std::string brStr = extractJsonField(content, "bitrate");
  if (!brStr.empty()) { try { s.bitrate = std::stoi(brStr); } catch(...) {} }
  std::string am = extractJsonField(content, "audioMode");
  if (!am.empty()) s.audioMode = am;
  std::string rm = extractJsonField(content, "recordMic");
  if (!rm.empty()) s.recordMic = (rm == "true" || rm == "1");
  std::string micId = extractJsonField(content, "micDeviceId");
  if (!micId.empty()) s.micDeviceId = toWide(micId);
  std::string cursorMode = extractJsonField(content, "cursorMode");
  if (!cursorMode.empty()) s.cursorMode = cursorMode;
  std::string flip180 = extractJsonField(content, "flip180");
  if (!flip180.empty()) s.flip180 = (flip180 == "true" || flip180 == "1");

  rec.UpdateSettings(s);
}

static void saveRecorderConfig(const DiscordUnlock::RecorderSettings& s) {
  fs::path p = getRecorderConfigPath();
  std::error_code ec;
  fs::create_directories(p.parent_path(), ec);
  std::ofstream fOut(p.string(), std::ios::trunc);
  if (!fOut.is_open()) return;
  fOut << "{\n"
       << "  \"resolutionMode\": \"" << escapeJsonString(s.resolutionMode) << "\",\n"
       << "  \"resolutionWidth\": " << s.targetWidth << ",\n"
       << "  \"resolutionHeight\": " << s.targetHeight << ",\n"
       << "  \"fps\": " << s.fps << ",\n"
       << "  \"bitrate\": " << s.bitrate << ",\n"
       << "  \"audioMode\": \"" << escapeJsonString(s.audioMode) << "\",\n"
       << "  \"recordMic\": " << (s.recordMic ? "true" : "false") << ",\n"
       << "  \"micDeviceId\": \"" << escapeJsonString(toUtf8(s.micDeviceId)) << "\",\n"
       << "  \"cursorMode\": \"" << escapeJsonString(s.cursorMode) << "\",\n"
       << "  \"flip180\": " << (s.flip180 ? "true" : "false") << "\n"
       << "}\n";
}

static void broadcastHotkeysConfig() {
  std::lock_guard<std::mutex> lock(g_hotkeysMutex);
  auto itemJson = [](const HotkeyConfigItem& it) {
    return std::string("{\"ctrl\":") + (it.ctrl ? "true" : "false") +
           ",\"alt\":" + (it.alt ? "true" : "false") +
           ",\"shift\":" + (it.shift ? "true" : "false") +
           ",\"vk\":" + std::to_string(it.vkCode) +
           ",\"text\":\"" + escapeJsonString(it.text) + "\"}";
  };
  std::string json = "{\"type\":\"hotkeys_config\","
                     "\"record\":" + itemJson(g_hotkeysConfig.record) + ","
                     "\"clip\":" + itemJson(g_hotkeysConfig.clip) + ","
                     "\"overlay\":" + itemJson(g_hotkeysConfig.overlay) + "}";
  postJsonToUI(json);
}

