void broadcastRecorderMicrophones() {
  std::string json = "{\"type\":\"recorder_microphones\",\"microphones\":[";
  bool first = true;
  HRESULT initHr = CoInitializeEx(nullptr, COINIT_MULTITHREADED);
  IMMDeviceEnumerator* enumerator = nullptr;
  IMMDeviceCollection* devices = nullptr;
  if (SUCCEEDED(CoCreateInstance(__uuidof(MMDeviceEnumerator), nullptr, CLSCTX_ALL,
                                 __uuidof(IMMDeviceEnumerator), (void**)&enumerator)) &&
      SUCCEEDED(enumerator->EnumAudioEndpoints(eCapture, DEVICE_STATE_ACTIVE, &devices))) {
    UINT count = 0;
    devices->GetCount(&count);
    for (UINT i = 0; i < count; ++i) {
      IMMDevice* device = nullptr;
      if (FAILED(devices->Item(i, &device)) || !device) continue;
      LPWSTR id = nullptr;
      std::wstring name;
      IPropertyStore* props = nullptr;
      PROPVARIANT value;
      PropVariantInit(&value);
      if (SUCCEEDED(device->OpenPropertyStore(STGM_READ, &props)) && props &&
          SUCCEEDED(props->GetValue(PKEY_Device_FriendlyName, &value)) && value.vt == VT_LPWSTR && value.pwszVal) {
        name = value.pwszVal;
      }
      if (SUCCEEDED(device->GetId(&id)) && id) {
        if (name.empty()) name = id;
        if (!first) json += ",";
        first = false;
        json += "{\"id\":\"" + escapeJsonString(toUtf8(id)) + "\",\"name\":\"" +
                escapeJsonString(toUtf8(name)) + "\"}";
      }
      if (id) CoTaskMemFree(id);
      PropVariantClear(&value);
      if (props) props->Release();
      device->Release();
    }
  }
  if (devices) devices->Release();
  if (enumerator) enumerator->Release();
  if (SUCCEEDED(initHr)) CoUninitialize();
  auto settings = DiscordUnlock::ScreenRecorder::Instance().GetSettings();
  json += "],\"selectedId\":\"" + escapeJsonString(toUtf8(settings.micDeviceId)) + "\"}";
  postJsonToUI(json);
}
