static void applyStoragePolicyAsync(bool announce);

void handleRecorderToggleRecordingHotKey() {
  auto& rec = DiscordUnlock::ScreenRecorder::Instance();
  if (rec.IsRecording()) {
    std::wstring saved;
    if (rec.StopRecording(&saved)) {
      broadcastRecorderStatus();
      broadcastRecorderClips();
      showTrayNotification(L"Discord Unlock — Gravação", L"Gravação finalizada e vídeo salvo.");
    } else {
      broadcastRecorderStatus();
      broadcastRecorderClips();
      showTrayNotification(L"Discord Unlock — Gravação", L"A gravação falhou e o arquivo incompleto foi removido.");
    }
    auto s = rec.GetSettings();
    if (s.autoUploadCloud && !saved.empty()) {
      uploadToCloudGofile(saved, "1h", "", true, true);
    } else if (!saved.empty()) {
      applyStoragePolicyAsync(false);
    }
  } else {
    std::string err;
    if (rec.StartRecording(err)) {
      broadcastRecorderStatus();
      showTrayNotification(L"Discord Unlock — Gravação", L"Gravação de vídeo iniciada.");
    }
  }
}

void handleRecorderSaveClipHotKey() {
  auto& rec = DiscordUnlock::ScreenRecorder::Instance();
  std::wstring clipPath;
  std::string err;
  if (rec.SaveClipFromBuffer(clipPath, err)) {
    broadcastRecorderClips();
    postJsonToUI(R"({"type":"recorder_clip_saved","success":true})");
    showTrayNotification(L"Discord Unlock — Clipe salvo", L"Seu clipe foi salvo com sucesso.");
    auto s = rec.GetSettings();
    if (s.autoUploadCloud && !clipPath.empty()) {
      uploadToCloudGofile(clipPath, "1h", "", true, true);
    } else if (!clipPath.empty()) {
      applyStoragePolicyAsync(false);
    }
  } else {
    postJsonToUI("{\"type\":\"recorder_clip_saved\",\"success\":false,\"error\":\"" + escapeJsonString(err) + "\"}");
  }
}

// Forward declarations needed by handleRecorderAction (defined later in file)
struct ActiveAppInfo {
  DWORD pid;
  std::string name;
  std::string title;
  HWND hwnd;
};
static std::vector<ActiveAppInfo> getRunningApplications();

// Extracted from the main WebView dispatcher to reduce MSVC nesting depth.
void handleRecorderAction(const std::string& action, const std::string& json) {
  if (action == "recorder_get_status") {
    broadcastRecorderStatus();
  } else if (action == "recorder_get_settings") {
    broadcastRecorderSettings();
  } else if (action == "recorder_get_targets") {
    auto monitors = DiscordUnlock::GetSystemMonitors();
    auto windows = getRunningApplications();
    std::string jsonResp = "{\"type\":\"recorder_targets\",\"monitors\":[";
    for (size_t i = 0; i < monitors.size(); ++i) {
      if (i > 0) jsonResp += ",";
      jsonResp += "{\"index\":" + std::to_string(monitors[i].index) +
                  ",\"name\":\"" + escapeJsonString(monitors[i].name) + "\"" +
                  ",\"width\":" + std::to_string(monitors[i].width) +
                  ",\"height\":" + std::to_string(monitors[i].height) +
                  ",\"orientation\":" + std::to_string(monitors[i].orientation) +
                  ",\"isPrimary\":" + std::string(monitors[i].isPrimary ? "true" : "false") + "}";
    }
    jsonResp += "],\"windows\":[";
    for (size_t i = 0; i < windows.size(); ++i) {
      if (i > 0) jsonResp += ",";
      jsonResp += "{\"pid\":" + std::to_string(windows[i].pid) +
                  ",\"hwnd\":\"" + std::to_string((uintptr_t)windows[i].hwnd) + "\"" +
                  ",\"name\":\"" + escapeJsonString(windows[i].name) + "\"" +
                  ",\"title\":\"" + escapeJsonString(windows[i].title) + "\"}";
    }
    jsonResp += "]}";
    postJsonToUI(jsonResp);
  } else if (action == "get_hotkeys") {
    broadcastHotkeysConfig();
  } else if (action == "save_hotkeys") {
    std::string target = extractJsonField(json, "target");
    std::string ctrlStr = extractJsonField(json, "ctrl");
    std::string altStr = extractJsonField(json, "alt");
    std::string shiftStr = extractJsonField(json, "shift");
    std::string vkStr = extractJsonField(json, "vk");
    std::string txt = extractJsonField(json, "text");
    {
      std::lock_guard<std::mutex> lock(g_hotkeysMutex);
      auto applyItem = [&](HotkeyConfigItem& it) {
        if (!ctrlStr.empty()) it.ctrl = (ctrlStr == "true" || ctrlStr == "1");
        if (!altStr.empty()) it.alt = (altStr == "true" || altStr == "1");
        if (!shiftStr.empty()) it.shift = (shiftStr == "true" || shiftStr == "1");
        if (!vkStr.empty()) {
          try { it.vkCode = (UINT)std::stoi(vkStr); } catch(...) {}
        }
        if (!txt.empty()) it.text = txt;
      };
      if (target == "record") applyItem(g_hotkeysConfig.record);
      else if (target == "clip") applyItem(g_hotkeysConfig.clip);
      else if (target == "overlay") applyItem(g_hotkeysConfig.overlay);
    }
    saveHotkeysConfig();
    broadcastHotkeysConfig();
    broadcastRecorderSettings();
  } else if (action == "reset_hotkeys") {
    {
      std::lock_guard<std::mutex> lock(g_hotkeysMutex);
      g_hotkeysConfig.record = { true, false, false, VK_F9, "Ctrl+F9" };
      g_hotkeysConfig.clip = { true, false, false, VK_F10, "Ctrl+F10" };
      g_hotkeysConfig.overlay = { false, false, false, VK_F12, "F12" };
    }
    saveHotkeysConfig();
    broadcastHotkeysConfig();
    broadcastRecorderSettings();
  } else if (action == "recorder_get_microphones") {
    broadcastRecorderMicrophones();
  } else if (action == "recorder_save_settings") {
    auto& rec = DiscordUnlock::ScreenRecorder::Instance();
    auto s = rec.GetSettings();
    std::string ct = extractJsonField(json, "captureTarget");
    if (!ct.empty()) s.captureTarget = ct;
    std::string mi = extractJsonField(json, "monitorIndex");
    if (!mi.empty()) {
      try { s.monitorIndex = std::stoi(mi); } catch(...) {}
    }
    std::string hw = extractJsonField(json, "targetHwnd");
    if (!hw.empty()) {
      try { s.targetHwnd = (HWND)std::stoull(hw); } catch(...) {}
    }
    std::string wn = extractJsonField(json, "targetWindowName");
    if (!wn.empty()) s.targetWindowName = wn;
    std::string rmMode = extractJsonField(json, "resolutionMode");
    if (!rmMode.empty()) s.resolutionMode = rmMode;
    std::string rw = extractJsonField(json, "resolutionWidth");
    if (!rw.empty()) s.targetWidth = std::stoi(rw);
    std::string rh = extractJsonField(json, "resolutionHeight");
    if (!rh.empty()) s.targetHeight = std::stoi(rh);
    std::string fpsStr = extractJsonField(json, "fps");
    if (!fpsStr.empty()) s.fps = std::stoi(fpsStr);
    std::string brStr = extractJsonField(json, "bitrate");
    if (!brStr.empty()) s.bitrate = std::stoi(brStr);
    std::string am = extractJsonField(json, "audioMode");
    if (!am.empty()) s.audioMode = am;
    std::string rm = extractJsonField(json, "recordMic");
    if (!rm.empty()) s.recordMic = (rm == "true" || rm == "1");
    std::string micId = extractJsonField(json, "micDeviceId");
    s.micDeviceId = toWide(micId);
    std::string cursorMode = extractJsonField(json, "cursorMode");
    if (cursorMode == "hidden" || cursorMode == "cursor" || cursorMode == "highlight") s.cursorMode = cursorMode;
    std::string rb = extractJsonField(json, "replayBufferEnabled");
    bool prevBuffer = s.replayBufferEnabled;
    if (!rb.empty()) s.replayBufferEnabled = (rb == "true" || rb == "1");
    std::string rbs = extractJsonField(json, "replayBufferSeconds");
    const int previousReplaySeconds = s.replayBufferSeconds;
    const std::string previousReplayQuality = s.replayQuality;
    if (!rbs.empty()) s.replayBufferSeconds = std::clamp(std::stoi(rbs), 15, 300);
    std::string rq = extractJsonField(json, "replayQuality");
    if (rq == "economy" || rq == "balanced" || rq == "high") s.replayQuality = rq;
    const bool restartReplay = prevBuffer && (previousReplaySeconds != s.replayBufferSeconds || previousReplayQuality != s.replayQuality);
    std::string auc = extractJsonField(json, "autoUploadCloud");
    if (!auc.empty()) s.autoUploadCloud = (auc == "true" || auc == "1");
    std::string f180 = extractJsonField(json, "flip180");
    if (!f180.empty()) s.flip180 = (f180 == "true" || f180 == "1");
    std::string aud = extractJsonField(json, "autoUploadDeleteLocal");
    if (!aud.empty()) s.autoUploadDeleteLocal = (aud == "true" || aud == "1");
    // Nunca permitir apagar o arquivo antes de um upload automático.
    if (s.autoUploadDeleteLocal) s.autoUploadCloud = true;
    rec.UpdateSettings(s);
    saveRecorderConfig(s);
    if (s.replayBufferEnabled && !prevBuffer) {
      std::string err;
      rec.StartReplayBuffer(err);
    } else if (!s.replayBufferEnabled && prevBuffer) {
      rec.StopReplayBuffer();
    } else if (s.replayBufferEnabled && restartReplay) {
      rec.StopReplayBuffer();
      std::string err;
      rec.StartReplayBuffer(err);
    }
    broadcastRecorderStatus();
    broadcastRecorderSettings();
  } else if (action == "recorder_start") {
    auto& rec = DiscordUnlock::ScreenRecorder::Instance();
    std::string err;
    if (rec.StartRecording(err)) {
      broadcastRecorderStatus();
      showTrayNotification(L"Discord Unlock — Gravação", L"Gravação de vídeo iniciada.");
    }
  } else if (action == "recorder_stop") {
    auto& rec = DiscordUnlock::ScreenRecorder::Instance();
    std::wstring saved;
    if (rec.StopRecording(&saved)) {
      broadcastRecorderStatus();
      broadcastRecorderClips();
      showTrayNotification(L"Discord Unlock — Gravação", L"Gravação finalizada e vídeo salvo.");
    } else {
      broadcastRecorderStatus();
      broadcastRecorderClips();
      showTrayNotification(L"Discord Unlock — Gravação", L"A gravação falhou e o arquivo incompleto foi removido.");
    }
    auto s = rec.GetSettings();
    if (s.autoUploadCloud && !saved.empty()) {
      uploadToCloudGofile(saved, "1h", "", true, true);
    } else if (!saved.empty()) {
      applyStoragePolicyAsync(false);
    }
  } else if (action == "recorder_save_clip") {
    handleRecorderSaveClipHotKey();
  } else if (action == "recorder_trim_clip") {
    std::string fp = extractJsonField(json, "filePath");
    double startValue = std::strtod(extractJsonField(json, "startSec").c_str(), nullptr);
    double endValue = std::strtod(extractJsonField(json, "endSec").c_str(), nullptr);
    int rotation = 0;
    try {
      std::string rotStr = extractJsonField(json, "rotation");
      if (!rotStr.empty()) rotation = std::stoi(rotStr);
    } catch (...) {}
    double startSec = startValue > 0.0 ? startValue : 0.0;
    double endSec = endValue > 0.0 ? endValue : 0.0;
    std::thread([fp, startSec, endSec, rotation]() {
      std::wstring output; std::string err;
      bool ok = !fp.empty() && DiscordUnlock::ScreenRecorder::Instance().TrimClip(toWide(fp), startSec, endSec, rotation, output, err);
      if (ok) {
        postJsonToUI("{\"type\":\"recorder_trim_result\",\"success\":true,\"filename\":\"" + escapeJsonString(fs::path(output).filename().string()) + "\"}");
        broadcastRecorderClips();
      } else {
        if (err.empty()) err = "Não foi possível cortar este clipe.";
        postJsonToUI("{\"type\":\"recorder_trim_result\",\"success\":false,\"error\":\"" + escapeJsonString(err) + "\"}");
      }
    }).detach();
  } else if (action == "recorder_get_clips") {
    broadcastRecorderClips();
  } else if (action == "recorder_rename_clip") {
    std::string fp = extractJsonField(json, "filePath");
    std::string newName = extractJsonField(json, "newName");
    if (!fp.empty() && !newName.empty()) {
      std::wstring outPath; std::string err;
      bool ok = DiscordUnlock::ScreenRecorder::Instance().RenameClip(toWide(fp), toWide(newName), outPath, err);
      if (ok) {
        postJsonToUI("{\"type\":\"recorder_rename_result\",\"success\":true,\"newPath\":\"" + escapeJsonString(toUtf8(outPath)) + "\",\"newFilename\":\"" + escapeJsonString(fs::path(outPath).filename().string()) + "\"}");
        broadcastRecorderClips();
      } else {
        postJsonToUI("{\"type\":\"recorder_rename_result\",\"success\":false,\"error\":\"" + escapeJsonString(err) + "\"}");
      }
    }
  } else if (action == "recorder_rotate_clip") {
    std::string fp = extractJsonField(json, "filePath");
    int degrees = 90;
    try { degrees = std::stoi(extractJsonField(json, "degrees")); } catch (...) {}
    if (!fp.empty()) {
      std::thread([fp, degrees]() {
        std::wstring outPath; std::string err;
        bool ok = DiscordUnlock::ScreenRecorder::Instance().RotateClip(toWide(fp), degrees, outPath, err);
        if (ok) {
          postJsonToUI("{\"type\":\"recorder_rotate_result\",\"success\":true,\"filename\":\"" + escapeJsonString(fs::path(outPath).filename().string()) + "\"}");
          broadcastRecorderClips();
        } else {
          postJsonToUI("{\"type\":\"recorder_rotate_result\",\"success\":false,\"error\":\"" + escapeJsonString(err) + "\"}");
        }
      }).detach();
    }
  } else if (action == "recorder_delete_clip") {
    std::string fp = extractJsonField(json, "filePath");
    const bool fromManualUpload = extractJsonField(json, "fromManualUpload") == "true";
    if (!fp.empty()) {
      const std::wstring filePath = toWide(fp);
      if (fromManualUpload) postRecorderCloudUploadProgress("deletando", 100, filePath, "Removendo o vídeo local...");
      const bool deleted = DiscordUnlock::ScreenRecorder::Instance().DeleteClip(filePath) || !fs::exists(filePath);
      broadcastRecorderClips();
      if (fromManualUpload) {
        postRecorderCloudUploadProgress(deleted ? "deletado" : "deletando", 100, filePath,
          deleted ? "Arquivo local removido após sua confirmação." : "O Windows não permitiu apagar o arquivo local.", deleted);
        postJsonToUI(std::string(R"({"type":"recorder_delete_result","success":)") + (deleted ? "true" : "false") + R"(,"message":")" + escapeJsonString(deleted ? "Arquivo local removido após sua confirmação." : "O Windows não permitiu apagar o arquivo local.") + R"("})");
      }
    }
  } else if (action == "recorder_play_clip") {
    std::string fp = extractJsonField(json, "filePath");
    if (!fp.empty()) {
      ShellExecuteW(nullptr, L"open", toWide(fp).c_str(), nullptr, nullptr, SW_SHOWNORMAL);
    }
  } else if (action == "recorder_upload_cloud") {
    std::string fp = extractJsonField(json, "filePath");
    if (!fp.empty()) {
      uploadToCloudGofile(toWide(fp), "1h", "", true, false);
    }
  } else if (action == "recorder_open_folder") {
    auto s = DiscordUnlock::ScreenRecorder::Instance().GetSettings();
    ShellExecuteW(nullptr, L"open", s.outputFolder.c_str(), nullptr, nullptr, SW_SHOWNORMAL);
  }
}

void measureAllPingsAsync() {
  std::thread([]() {
    try {
      const auto &profiles = getServerProfiles();
      for (size_t i = 0; i < profiles.size() && g_appRunning; ++i) {
        int lat = 15;
        if (!profiles[i].isDirect && !profiles[i].endpoint.empty()) {
          lat = testSocks5Handshake(profiles[i].endpoint, 1200);
          if (lat <= 0) lat = 190;
        }
        std::string pingJson = "{\"type\":\"server_ping\",\"index\":" + std::to_string(i) + ",\"ping\":" + std::to_string(lat) + "}";
        postJsonToUI(pingJson);
      }
    } catch (...) {}
  }).detach();
}

void sendStatusToUI(const std::string &ipOrCountry, int ping) {
  auto cf = getCountryAndFlag(ipOrCountry);
  std::string country = cf.first;
  std::string code = cf.second;
  if (country == "Servidor Global" && !ipOrCountry.empty() && ipOrCountry.find('.') == std::string::npos) {
    country = ipOrCountry;
  }
  std::string json = "{\"type\":\"status\",\"country\":\"" + country + "\",\"code\":\"" + code + "\",\"ping\":" + std::to_string(ping) + "}";
  postJsonToUI(json);
}

std::mutex g_themeDownloadMutex;
std::unordered_map<std::string, std::shared_ptr<std::atomic<bool>>> g_themeDownloadCancelMap;

class ThemeDownloadCallback : public IBindStatusCallback {
  std::string m_themeId;
  std::shared_ptr<std::atomic<bool>> m_cancelFlag;
public:
  ThemeDownloadCallback(const std::string &id, std::shared_ptr<std::atomic<bool>> cancelFlag) 
      : m_themeId(id), m_cancelFlag(cancelFlag) {}

  STDMETHOD(QueryInterface)(REFIID riid, void **ppvObject) {
    if (riid == IID_IUnknown || riid == IID_IBindStatusCallback) {
      *ppvObject = this;
      return S_OK;
    }
    *ppvObject = nullptr;
    return E_NOINTERFACE;
  }
  STDMETHOD_(ULONG, AddRef)() { return 1; }
  STDMETHOD_(ULONG, Release)() { return 1; }
  STDMETHOD(OnStartBinding)(DWORD, IBinding *) { return S_OK; }
  STDMETHOD(GetPriority)(LONG *) { return S_OK; }
  STDMETHOD(OnLowResource)(DWORD) { return S_OK; }
  STDMETHOD(OnProgress)(ULONG ulProgress, ULONG ulProgressMax, ULONG ulStatusCode, LPCWSTR szStatusText) {
    if (m_cancelFlag && m_cancelFlag->load()) {
      return E_ABORT;
    }
    if (ulStatusCode == 1 || ulStatusCode == 2) {
      postJsonToUI("{\"type\":\"theme_download_stage\",\"themeId\":\"" + m_themeId + "\",\"stage\":\"connecting\",\"label\":\"Conectando...\"}");
    } else if (ulStatusCode == 11 || ulStatusCode == 3) {
      postJsonToUI("{\"type\":\"theme_download_stage\",\"themeId\":\"" + m_themeId + "\",\"stage\":\"waiting\",\"label\":\"Aguardando resposta do servidor...\"}");
    } else if (ulProgressMax > 0 || ulProgress > 0) {
      int percent = (ulProgressMax > 0) ? (int)(((double)ulProgress / (double)ulProgressMax) * 100.0) : 0;
      if (percent > 100) percent = 100;
      postJsonToUI("{\"type\":\"theme_download_progress\",\"themeId\":\"" + m_themeId + "\",\"stage\":\"downloading\",\"percent\":" + std::to_string(percent) + ",\"downloaded\":" + std::to_string(ulProgress) + ",\"total\":" + std::to_string(ulProgressMax) + "}");
    }
    return S_OK;
  }
  STDMETHOD(OnStopBinding)(HRESULT, LPCWSTR) { return S_OK; }
  STDMETHOD(GetBindInfo)(DWORD *pgrfBINDF, BINDINFO *pbindInfo) {
    if (pgrfBINDF) *pgrfBINDF = BINDF_ASYNCHRONOUS | BINDF_PULLDATA | BINDF_GETNEWESTVERSION | BINDF_NOWRITECACHE | BINDF_PRAGMA_NO_CACHE;
    return S_OK;
  }
  STDMETHOD(OnDataAvailable)(DWORD, DWORD, FORMATETC *, STGMEDIUM *) { return S_OK; }
  STDMETHOD(OnObjectAvailable)(REFIID, IUnknown *) { return S_OK; }
};

void cancelThemeDownload(const std::string &themeId) {
  std::lock_guard<std::mutex> lock(g_themeDownloadMutex);
  auto it = g_themeDownloadCancelMap.find(themeId);
  if (it != g_themeDownloadCancelMap.end() && it->second) {
    it->second->store(true);
  }
}


// Detect real image/video format by reading file magic bytes, regardless of extension.
// Returns the correct extension (e.g. ".gif", ".png", ".jpg") based on the file header.
static std::string detectRealMediaExtension(const fs::path& filePath) {
  try {
    std::ifstream f(filePath, std::ios::binary);
    if (!f.is_open()) return filePath.extension().string();
    unsigned char header[12] = {};
    f.read(reinterpret_cast<char*>(header), 12);
    f.close();
    // GIF87a or GIF89a
    if (header[0] == 0x47 && header[1] == 0x49 && header[2] == 0x46 &&
        header[3] == 0x38 && (header[4] == 0x37 || header[4] == 0x39) && header[5] == 0x61)
      return ".gif";
    // PNG: 89 50 4E 47 0D 0A 1A 0A
    if (header[0] == 0x89 && header[1] == 0x50 && header[2] == 0x4E && header[3] == 0x47 &&
        header[4] == 0x0D && header[5] == 0x0A && header[6] == 0x1A && header[7] == 0x0A)
      return ".png";
    // JPEG: FF D8 FF
    if (header[0] == 0xFF && header[1] == 0xD8 && header[2] == 0xFF)
      return ".jpg";
    // WEBP: RIFF....WEBP
    if (header[0] == 0x52 && header[1] == 0x49 && header[2] == 0x46 && header[3] == 0x46 &&
        header[8] == 0x57 && header[9] == 0x45 && header[10] == 0x42 && header[11] == 0x50)
      return ".webp";
    // MP4/MOV: ....ftyp
    if (header[4] == 0x66 && header[5] == 0x74 && header[6] == 0x79 && header[7] == 0x70)
      return ".mp4";
    // WebM/MKV: 1A 45 DF A3
    if (header[0] == 0x1A && header[1] == 0x45 && header[2] == 0xDF && header[3] == 0xA3)
      return ".webm";
  } catch (...) {}
  return filePath.extension().string();
}

// Rename files with wrong extension to match their real format (e.g. GIF saved as .png -> .gif).
// Returns the new path if renamed, or the original path if no change needed.
static fs::path fixMediaExtension(const fs::path& filePath) {
  std::string currentExt = filePath.extension().string();
  std::transform(currentExt.begin(), currentExt.end(), currentExt.begin(),
                 [](unsigned char ch) { return (char)std::tolower(ch); });
  std::string realExt = detectRealMediaExtension(filePath);
  if (realExt == currentExt) return filePath;
  fs::path newPath = filePath;
  newPath.replace_extension(realExt);
  std::error_code ec;
  fs::rename(filePath, newPath, ec);
  if (ec) return filePath;
  logThemeEngine("EXTENSION_FIX", "SUCCESS", "Renamed " + filePath.filename().string() + " -> " + newPath.filename().string() + " (real format: " + realExt + ")");
  return newPath;
}


static bool extractWallpaperEnginePackage(const fs::path &packageFile, const fs::path &outputDir,
                                          fs::path &mediaFile, std::string &error) {
  try {
    fs::path toolDir = getAppDataDirectory() / "tools" / "repkg";
    fs::path repkgExe = toolDir / "RePKG.exe";
    if (!extractResourceToFile(109, repkgExe)) {
      error = "Nao foi possivel preparar o conversor do Wallpaper Engine.";
      return false;
    }
    extractResourceToFile(110, toolDir / "LICENSE.txt");
    extractResourceToFile(111, toolDir / "THIRD-PARTY-NOTICES.txt");

    std::error_code ec;
    if (fs::exists(outputDir, ec)) fs::remove_all(outputDir, ec);
    fs::create_directories(outputDir, ec);
    if (ec) {
      error = "Nao foi possivel preparar a pasta de importacao.";
      return false;
    }

    std::wstring command = L"\"" + repkgExe.wstring() + L"\" extract -c -o \"" +
                           outputDir.wstring() + L"\" \"" + packageFile.wstring() + L"\"";
    std::vector<wchar_t> commandLine(command.begin(), command.end());
    commandLine.push_back(L'\0');

    STARTUPINFOW startup = {};
    startup.cb = sizeof(startup);
    startup.dwFlags = STARTF_USESHOWWINDOW;
    startup.wShowWindow = SW_HIDE;
    PROCESS_INFORMATION process = {};
    if (!CreateProcessW(nullptr, commandLine.data(), nullptr, nullptr, FALSE, CREATE_NO_WINDOW,
                        nullptr, toolDir.c_str(), &startup, &process)) {
      error = "Nao foi possivel iniciar o conversor do Wallpaper Engine.";
      return false;
    }

    const DWORD waitResult = WaitForSingleObject(process.hProcess, 180000);
    if (waitResult == WAIT_TIMEOUT) {
      TerminateProcess(process.hProcess, 1);
      CloseHandle(process.hThread);
      CloseHandle(process.hProcess);
      error = "A conversao do pacote demorou mais que 3 minutos.";
      return false;
    }
    DWORD exitCode = 1;
    GetExitCodeProcess(process.hProcess, &exitCode);
    CloseHandle(process.hThread);
    CloseHandle(process.hProcess);
    if (exitCode != 0) {
      error = "O pacote nao pode ser lido pelo conversor do Wallpaper Engine.";
      return false;
    }

    // Fix file extensions: RePKG sometimes saves animated GIF89a with .png extension.
    // Correct extensions BEFORE ranking so animated media gets proper priority.
    try {
      for (const auto& fixEntry : fs::recursive_directory_iterator(outputDir, fs::directory_options::skip_permission_denied, ec)) {
        if (ec) { ec.clear(); continue; }
        if (!fixEntry.is_regular_file(ec) || ec) { ec.clear(); continue; }
        std::string fixExt = fixEntry.path().extension().string();
        std::transform(fixExt.begin(), fixExt.end(), fixExt.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
        if (fixExt == ".png" || fixExt == ".jpg" || fixExt == ".jpeg") {
          fixMediaExtension(fixEntry.path());
        }
      }
    } catch (...) {}
    ec.clear();

    struct Candidate { fs::path path; int rank; uintmax_t size; };
    std::vector<Candidate> candidates;
    for (const auto &entry : fs::recursive_directory_iterator(outputDir, fs::directory_options::skip_permission_denied, ec)) {
      if (ec || !entry.is_regular_file(ec)) continue;
      std::string ext = entry.path().extension().string();
      std::transform(ext.begin(), ext.end(), ext.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
      std::string fn = entry.path().filename().string();
      std::transform(fn.begin(), fn.end(), fn.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
      int rank = 0;
      if (ext == ".mp4" || ext == ".webm") rank = 6;
      else if (ext == ".gif") rank = 4;
      else if (ext == ".png" || ext == ".jpg" || ext == ".jpeg" || ext == ".webp") rank = 3;
      if (rank == 0) continue;
      const uintmax_t size = entry.file_size(ec);
      if (!ec && size > 1024) {
        // Boost rank for files in materials/ (full-res scene textures)
        std::string relPath = entry.path().string();
        if (relPath.find("materials") != std::string::npos && relPath.find("masks") == std::string::npos
            && relPath.find("effects") == std::string::npos && relPath.find("presets") == std::string::npos) {
          if (ext == ".png" || ext == ".jpg" || ext == ".jpeg" || ext == ".webp") rank = 5; // Above GIF, below video
        }
        // Penalize tiny files (likely previews/icons)
        if (size < 50000 && (ext == ".png" || ext == ".jpg" || ext == ".gif")) rank = 1;
        // Skip particle textures, masks, effect textures
        if (fn.find("mask") != std::string::npos || fn.find("noise") != std::string::npos
            || fn.find("particle") != std::string::npos || fn.find("white") != std::string::npos
            || fn.find("skycolor") != std::string::npos || fn.find("spot") != std::string::npos
            || fn.find("cloud") != std::string::npos || fn.find("phase") != std::string::npos
            || fn.find("normal") != std::string::npos || fn.find("flow") != std::string::npos) continue;
        candidates.push_back({entry.path(), rank, size});
      }
    }
    if (candidates.empty()) {
      error = "Nenhum video ou imagem compativel foi encontrado no pacote.";
      return false;
    }
    std::sort(candidates.begin(), candidates.end(), [](const Candidate &a, const Candidate &b) {
      return a.rank != b.rank ? a.rank > b.rank : a.size > b.size;
    });
    mediaFile = candidates.front().path;

    // Wallpaper Engine material textures are stored Y-flipped (OpenGL origin).
    // Flip vertically so they display correctly as CSS/HTML backgrounds.
    {
      std::string selPath = mediaFile.string();
      std::string selExt = mediaFile.extension().string();
      std::transform(selExt.begin(), selExt.end(), selExt.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
      if (selPath.find("materials") != std::string::npos &&
          (selExt == ".png" || selExt == ".jpg" || selExt == ".jpeg" || selExt == ".bmp")) {
        try {
          Gdiplus::GdiplusStartupInput gdiplusStartupInput;
          ULONG_PTR gdiplusToken;
          Gdiplus::GdiplusStartup(&gdiplusToken, &gdiplusStartupInput, NULL);
          {
            std::wstring wpath(mediaFile.wstring());
            Gdiplus::Bitmap* bmp = new Gdiplus::Bitmap(wpath.c_str());
            if (bmp && bmp->GetLastStatus() == Gdiplus::Ok) {
              bmp->RotateFlip(Gdiplus::RotateNoneFlipY);
              // Determine encoder
              CLSID clsid;
              auto getEncoder = [](const WCHAR* format, CLSID* pClsid) -> bool {
                UINT num = 0, sz = 0;
                Gdiplus::GetImageEncodersSize(&num, &sz);
                if (sz == 0) return false;
                auto pEncoders = (Gdiplus::ImageCodecInfo*)(malloc(sz));
                if (!pEncoders) return false;
                Gdiplus::GetImageEncoders(num, sz, pEncoders);
                for (UINT j = 0; j < num; ++j) {
                  if (wcscmp(pEncoders[j].MimeType, format) == 0) {
                    *pClsid = pEncoders[j].Clsid;
                    free(pEncoders);
                    return true;
                  }
                }
                free(pEncoders);
                return false;
              };
              const WCHAR* mime = (selExt == ".png") ? L"image/png" : L"image/jpeg";
              if (getEncoder(mime, &clsid)) {
                bmp->Save(wpath.c_str(), &clsid, NULL);
              }
            }
            delete bmp;
          }
          Gdiplus::GdiplusShutdown(gdiplusToken);
        } catch (...) {}
      }
    }

    return true;
  } catch (...) {
    error = "Ocorreu uma falha ao preparar o tema do Wallpaper Engine.";
    return false;
  }
}


static std::vector<fs::path> getSteamLibraryRoots() {
  std::vector<fs::path> roots;
  auto addRoot = [&](fs::path value) {
    std::error_code ec;
    if (!value.empty() && fs::exists(value / "steamapps", ec) &&
        std::find(roots.begin(), roots.end(), value) == roots.end()) roots.push_back(value);
  };
  wchar_t steamPath[MAX_PATH] = {};
  DWORD steamPathSize = sizeof(steamPath);
  if (RegGetValueW(HKEY_CURRENT_USER, L"Software\\Valve\\Steam", L"SteamPath", RRF_RT_REG_SZ,
                   nullptr, steamPath, &steamPathSize) == ERROR_SUCCESS) addRoot(fs::path(steamPath));
  addRoot(L"C:/Program Files (x86)/Steam");
  addRoot(L"C:/Program Files/Steam");

  std::vector<fs::path> allRoots = roots;
  for (const auto &root : roots) {
    try {
      std::ifstream file((root / "steamapps" / "libraryfolders.vdf").string());
      std::string contents((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
      const std::regex pattern(R"REGEX("path"\s+"([^"]+)")REGEX", std::regex::icase);
      for (std::sregex_iterator it(contents.begin(), contents.end(), pattern), end; it != end; ++it) {
        std::string value = (*it)[1].str();
        size_t pos = 0;
        while ((pos = value.find("\\\\", pos)) != std::string::npos) value.replace(pos, 2, "\\");
        fs::path library = fs::u8path(value);
        std::error_code ec;
        if (fs::exists(library / "steamapps", ec) &&
            std::find(allRoots.begin(), allRoots.end(), library) == allRoots.end()) allRoots.push_back(library);
      }
    } catch (...) {}
  }
  return allRoots;
}

std::string getLocalWallpaperEngineThemesJson() {
  std::vector<std::string> entries;
  std::unordered_set<std::string> seenPackages;
  std::vector<fs::path> workshops = {
    fs::path(L"C:/Program Files (x86)/Steam/steamapps/workshop/content/431960"),
    fs::path(L"C:/Program Files/Steam/steamapps/workshop/content/431960")
  };
  for (const auto &steamRoot : getSteamLibraryRoots()) {
    workshops.push_back(steamRoot / "steamapps" / "workshop" / "content" / "431960");
  }

  for (const auto &workshop : workshops) {
    std::error_code ec;
    if (!fs::exists(workshop, ec) || ec) continue;
    try {
      for (const auto &folder : fs::directory_iterator(workshop, fs::directory_options::skip_permission_denied, ec)) {
        if (ec) { ec.clear(); continue; }
        if (!folder.is_directory(ec) || ec) { ec.clear(); continue; }

        fs::path package;
        fs::path nativeVideo;  // For video-type themes without .pkg
        for (const auto &candidate : fs::directory_iterator(folder.path(), fs::directory_options::skip_permission_denied, ec)) {
          if (ec) { ec.clear(); continue; }
          if (!candidate.is_regular_file(ec) || ec) { ec.clear(); continue; }
          std::string ext = candidate.path().extension().string();
          std::transform(ext.begin(), ext.end(), ext.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
          if (ext == ".pkg") { package = candidate.path(); break; }
          if (nativeVideo.empty() && (ext == ".mp4" || ext == ".webm")) {
            if (candidate.file_size(ec) >= 100000 && !ec) nativeVideo = candidate.path();
            ec.clear();
          }
        }

        // Skip folders with neither .pkg nor native video
        if (package.empty() && nativeVideo.empty()) continue;

        std::string uniqueKey;
        if (!package.empty()) {
          uniqueKey = package.lexically_normal().string();
        } else {
          uniqueKey = folder.path().lexically_normal().string();
        }
        std::transform(uniqueKey.begin(), uniqueKey.end(), uniqueKey.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
        if (!seenPackages.insert(uniqueKey).second) continue;

        std::string workId = folder.path().filename().string();
        for (char &ch : workId) if (!std::isalnum((unsigned char)ch) && ch != '_' && ch != '-') ch = '_';
        const std::string themeId = "local_engine_" + workId;
        std::string preview;
        for (const char *name : {"preview.jpg", "preview.png", "preview.gif"}) {
          fs::path candidate = folder.path() / name;
          if (fs::exists(candidate, ec) && !ec) {
            preview = "http://127.0.0.1:45123/file?file=" + urlEncode(candidate.string());
            break;
          }
          ec.clear();
        }

        bool hasAnimatedMedia = !nativeVideo.empty();  // video-type themes are always animated
        if (!hasAnimatedMedia) {
          try {
            for (const auto &mediaFile : fs::recursive_directory_iterator(folder.path(), fs::directory_options::skip_permission_denied, ec)) {
              if (ec) { ec.clear(); continue; }
              if (!mediaFile.is_regular_file(ec) || ec) { ec.clear(); continue; }
              std::string mediaExt = mediaFile.path().extension().string();
              std::transform(mediaExt.begin(), mediaExt.end(), mediaExt.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
              if (mediaExt != ".mp4" && mediaExt != ".webm" && mediaExt != ".gif") continue;
              const uintmax_t mediaSize = mediaFile.file_size(ec);
              if (!ec && mediaSize >= 100000) { hasAnimatedMedia = true; break; }
              ec.clear();
            }
          } catch (...) { ec.clear(); }
        }

        // Also check if this theme was previously imported and produced animated media
        if (!hasAnimatedMedia) {
          try {
            fs::path importedDir = getLocalTemasDir() / themeId;
            if (fs::exists(importedDir, ec) && !ec) {
              for (const auto& imported : fs::recursive_directory_iterator(importedDir, fs::directory_options::skip_permission_denied, ec)) {
                if (ec) { ec.clear(); continue; }
                if (!imported.is_regular_file(ec) || ec) { ec.clear(); continue; }
                std::string impExt = imported.path().extension().string();
                std::transform(impExt.begin(), impExt.end(), impExt.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
                if (impExt == ".gif" || impExt == ".mp4" || impExt == ".webm") {
                  const uintmax_t impSize = imported.file_size(ec);
                  if (!ec && impSize >= 50000) { hasAnimatedMedia = true; break; }
                  ec.clear();
                }
              }
            }
          } catch (...) { ec.clear(); }
        }

        // Determine source_path: .pkg for scenes, native video path for video-type
        fs::path sourcePath = !package.empty() ? package : nativeVideo;
        uintmax_t size = fs::file_size(sourcePath, ec);
        if (ec) { size = 0; ec.clear(); }
        std::stringstream mb;
        mb << std::fixed << std::setprecision(1) << (double)size / (1024.0 * 1024.0);
        std::string engineDesc, engineBadge;
        if (!nativeVideo.empty() && package.empty()) {
          // Video-type theme (no .pkg)
          engineDesc = "Video nativo do Wallpaper Engine. Reproduzido diretamente no Discord com qualidade original.";
          engineBadge = "ENGINE VIDEO";
        } else if (hasAnimatedMedia) {
          engineDesc = "Animacao detectada. Sera renderizada em tempo real no Discord com o motor WebGL.";
          engineBadge = "ENGINE ANIMADO";
        } else {
          engineDesc = "Cena com shaders do Wallpaper Engine. Sera renderizada em tempo real com o motor WebGL integrado.";
          engineBadge = "CENA ENGINE";
        }
        std::string themeTitle;
        fs::path projJson = folder.path() / "project.json";
        if (!fs::exists(projJson, ec)) {
          ec.clear();
          projJson = getLocalTemasDir() / themeId / "project.json";
        }
        if (fs::exists(projJson, ec) && !ec) {
          try {
            std::ifstream pj(projJson.string());
            if (pj.is_open()) {
              std::string pjc((std::istreambuf_iterator<char>(pj)), std::istreambuf_iterator<char>());
              pj.close();
              std::string t = extractJsonField(pjc, "title");
              if (!t.empty()) themeTitle = t;
            }
          } catch (...) {}
        }
        if (themeTitle.empty()) {
          themeTitle = "Wallpaper Engine " + workId;
        }

        entries.push_back("{\"id\":\"" + escapeJsonString(themeId) +
          "\",\"name\":\"" + escapeJsonString(themeTitle) +
          "\",\"desc\":\"" + escapeJsonString(engineDesc) + "\","
          "\"tags\":[\"Wallpaper Engine\"],\"file_name\":\"" + escapeJsonString(themeId + "_engine") +
          "\",\"source_path\":\"" + escapeJsonString(sourcePath.string()) +
          "\",\"preview\":\"" + escapeJsonString(preview) + "\",\"size_mb\":" + mb.str() +
          ",\"isAnimated\":" + (hasAnimatedMedia ? "true" : "false") +
          ",\"badge\":\"" + engineBadge + "\",\"isEngineLocal\":true}");
      }
    } catch (...) {}
  }
  std::sort(entries.begin(), entries.end());
  logThemeEngine("WALLPAPER_ENGINE_SCAN", "SUCCESS", "Found " + std::to_string(entries.size()) + " local package(s).");
  std::string json = "[";
  for (size_t i = 0; i < entries.size(); ++i) { if (i) json += ","; json += entries[i]; }
  return json + "]";
}
void importLocalWallpaperEngineThemeAsync(const std::string &themeId, const std::string &sourcePath) {
  std::thread([themeId, sourcePath]() {
    try {
      fs::path package = fs::u8path(sourcePath);
      std::error_code ec;
      std::string rawId = themeId;
      for (char &ch : rawId) if (!std::isalnum((unsigned char)ch) && ch != '_' && ch != '-') ch = '_';
      std::string extension = package.extension().string();
      std::transform(extension.begin(), extension.end(), extension.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
      const bool isDirectVideo = (extension == ".mp4" || extension == ".webm");
      if (!fs::exists(package, ec) || (extension != ".pkg" && !isDirectVideo)) {
        postJsonToUI("{\"type\":\"theme_download_error\",\"themeId\":\"" + escapeJsonString(themeId) + "\",\"error\":\"O pacote local do Wallpaper Engine nao foi encontrado.\"}");
        return;
      }

      fs::path themeDir = getLocalTemasDir();
      fs::path subDir = themeDir / rawId;
      fs::create_directories(subDir, ec);
      ec.clear();

      fs::path srcProjJson = package.parent_path() / "project.json";
      if (fs::exists(srcProjJson, ec) && !ec) {
        fs::copy_file(srcProjJson, subDir / "project.json", fs::copy_options::overwrite_existing, ec);
        ec.clear();
      }

      fs::path media;
      bool isNativeAnimatedMedia = false;

      if (isDirectVideo) {
        // Video-type theme: direct copy, no RePKG needed
        postJsonToUI("{\"type\":\"theme_download_stage\",\"themeId\":\"" + escapeJsonString(themeId) + "\",\"stage\":\"extracting\",\"label\":\"Copiando video do Wallpaper Engine...\"}");
        media = package;
        isNativeAnimatedMedia = true;
      } else {
        // Scene-type theme: check for native playable media first
        fs::path playableMedia;
        int bestRank = 0;
        uintmax_t bestSize = 0;
        try {
          for (const auto &candidate : fs::recursive_directory_iterator(package.parent_path(), fs::directory_options::skip_permission_denied, ec)) {
            if (ec) { ec.clear(); continue; }
            if (!candidate.is_regular_file(ec) || ec) { ec.clear(); continue; }
            std::string ext = candidate.path().extension().string();
            std::string name = candidate.path().filename().string();
            std::transform(ext.begin(), ext.end(), ext.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
            std::transform(name.begin(), name.end(), name.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
            const bool preview = name.find("preview") != std::string::npos;
            int rank = 0;
            if ((ext == ".mp4" || ext == ".webm") && !preview) rank = 5;
            else if (ext == ".gif" && !preview) rank = 4;
            else if (ext == ".mp4" || ext == ".webm") rank = 3;
            else if (ext == ".gif") rank = 2;
            if (!rank) continue;
            const uintmax_t size = candidate.file_size(ec);
            if (ec || size < 100000) { ec.clear(); continue; }
            if (rank > bestRank || (rank == bestRank && size > bestSize)) {
              playableMedia = candidate.path();
              bestRank = rank;
              bestSize = size;
            }
          }
        } catch (...) {}

        isNativeAnimatedMedia = !playableMedia.empty();
        if (isNativeAnimatedMedia) {
          postJsonToUI("{\"type\":\"theme_download_stage\",\"themeId\":\"" + escapeJsonString(themeId) + "\",\"stage\":\"extracting\",\"label\":\"Copiando vídeo animado do Wallpaper Engine...\"}");
          media = playableMedia;
        } else {
          postJsonToUI("{\"type\":\"theme_download_stage\",\"themeId\":\"" + escapeJsonString(themeId) + "\",\"stage\":\"extracting\",\"label\":\"Extraindo imagem do pacote do Wallpaper Engine...\"}");
          std::string extractionError;
          if (!extractWallpaperEnginePackage(package, subDir / "engine_extracted", media, extractionError)) {
            postJsonToUI("{\"type\":\"theme_download_error\",\"themeId\":\"" + escapeJsonString(themeId) + "\",\"error\":\"" + escapeJsonString(extractionError) + "\"}");
            return;
          }
        }
      }

      // Fix extension if RePKG saved animated GIF with wrong extension (e.g. .png)
      media = fixMediaExtension(media);

      // Re-check if the extracted file is actually animated (GIF/MP4/WebM)
      if (!isNativeAnimatedMedia) {
        std::string fixedExt = media.extension().string();
        std::transform(fixedExt.begin(), fixedExt.end(), fixedExt.begin(), [](unsigned char ch) { return (char)std::tolower(ch); });
        if (fixedExt == ".gif" || fixedExt == ".mp4" || fixedExt == ".webm") {
          isNativeAnimatedMedia = true;
          logThemeEngine("ENGINE_IMPORT", "ANIMATED_DETECTED", "Extracted file is actually animated: " + media.filename().string());
        }
      }

      const std::string mediaExt = media.extension().string();
      const std::string cleanFileName = rawId + "_engine" + mediaExt;
      fs::copy_file(media, themeDir / cleanFileName, fs::copy_options::overwrite_existing, ec);
      if (ec) { ec.clear(); }
      fs::copy_file(media, subDir / ("wallpaper_hd" + mediaExt), fs::copy_options::overwrite_existing, ec);
      if (ec) {
        postJsonToUI("{\"type\":\"theme_download_error\",\"themeId\":\"" + escapeJsonString(themeId) + "\",\"error\":\"Nao foi possivel salvar a mídia importada.\"}");
        return;
      }
      logThemeEngine("ENGINE_IMPORT", "SUCCESS", "Theme: " + themeId + " | Source: " + (isNativeAnimatedMedia ? "native animated media" : "RePKG extracted still media") + " | File: " + cleanFileName);
      postJsonToUI("{\"type\":\"theme_download_complete\",\"themeId\":\"" + escapeJsonString(themeId) + "\",\"fileName\":\"" + escapeJsonString(cleanFileName) + "\",\"localUri\":\"file:///\",\"animated\":" + (isNativeAnimatedMedia ? "true" : "false") + "}");
    } catch (...) {
      postJsonToUI("{\"type\":\"theme_download_error\",\"themeId\":\"" + escapeJsonString(themeId) + "\",\"error\":\"Falha ao importar o tema local.\"}");
    }
  }).detach();
}
void downloadThemeAssetAsync(const std::string &themeId, const std::string &url, const std::string &fileName, bool enginePackage = false) {
  auto cancelFlag = std::make_shared<std::atomic<bool>>(false);
  {
    std::lock_guard<std::mutex> lock(g_themeDownloadMutex);
    g_themeDownloadCancelMap[themeId] = cancelFlag;
  }

  std::thread([themeId, url, fileName, enginePackage, cancelFlag]() {
    fs::path themeDir = getLocalTemasDir();
    std::error_code ec;
    if (!fs::exists(themeDir, ec)) fs::create_directories(themeDir, ec);
    std::string cleanFileName = fileName.empty() ? (themeId + ".mp4") : fileName;
    fs::path targetFile = themeDir / cleanFileName;
    fs::path tempFile = themeDir / (cleanFileName + ".tmp");

    std::string downloadUrlStr = url;
    if (downloadUrlStr.find("images.steamusercontent.com") != std::string::npos && downloadUrlStr.find("imw=5000") == std::string::npos) {
      size_t q = downloadUrlStr.find('?');
      if (q != std::string::npos) downloadUrlStr = downloadUrlStr.substr(0, q);
      downloadUrlStr += "/?imw=5000&imh=5000&ima=fit&impolicy=Letterbox&imcolor=%23000000&letterbox=false";
    }

    logThemeEngine("DOWNLOAD_START", "IN_PROGRESS", "Theme: " + themeId + " | URL: " + downloadUrlStr + " | Target: " + targetFile.string());

    // Stage 1: Conectando...
    postJsonToUI("{\"type\":\"theme_download_stage\",\"themeId\":\"" + themeId + "\",\"stage\":\"connecting\",\"label\":\"Conectando...\"}");

    bool downloadSuccess = false;
    uintmax_t totalBytesDownloaded = 0;

    // Use WinHttp engine with auto-redirect, virus-scan warning token resolution and timeouts
    HINTERNET hSession = WinHttpOpen(L"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                                    WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                    WINHTTP_NO_PROXY_NAME,
                                    WINHTTP_NO_PROXY_BYPASS, 0);
    if (hSession) {
      WinHttpSetTimeouts(hSession, 8000, 10000, 10000, 15000);

      auto crackUrl = [](const std::wstring &wUrl) -> std::pair<std::wstring, std::pair<std::wstring, INTERNET_PORT>> {
        URL_COMPONENTS comp = { 0 };
        comp.dwStructSize = sizeof(comp);
        wchar_t host[512] = { 0 };
        wchar_t path[4096] = { 0 };
        comp.lpszHostName = host;
        comp.dwHostNameLength = 511;
        comp.lpszUrlPath = path;
        comp.dwUrlPathLength = 4095;
        if (WinHttpCrackUrl(wUrl.c_str(), (DWORD)wUrl.length(), 0, &comp)) {
          return { std::wstring(comp.lpszHostName, comp.dwHostNameLength), 
                   { std::wstring(comp.lpszUrlPath, comp.dwUrlPathLength), comp.nPort } };
        }
        return { L"", { L"/", INTERNET_DEFAULT_HTTPS_PORT } };
      };

      std::wstring currentUrl = toWide(downloadUrlStr);
      auto uParts = crackUrl(currentUrl);

      if (!uParts.first.empty()) {
        HINTERNET hConnect = WinHttpConnect(hSession, uParts.first.c_str(), uParts.second.second, 0);
        if (hConnect) {
          DWORD reqFlags = (uParts.second.second == INTERNET_DEFAULT_HTTPS_PORT || currentUrl.find(L"https://") == 0) ? WINHTTP_FLAG_SECURE : 0;
          HINTERNET hReq = WinHttpOpenRequest(hConnect, L"GET", uParts.second.first.c_str(), nullptr,
                                             WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, reqFlags);
          if (hReq) {
            DWORD redirectPolicy = WINHTTP_OPTION_REDIRECT_POLICY_ALWAYS;
            WinHttpSetOption(hReq, WINHTTP_OPTION_REDIRECT_POLICY, &redirectPolicy, sizeof(redirectPolicy));

            // Stage 2: Aguardando resposta do servidor...
            postJsonToUI("{\"type\":\"theme_download_stage\",\"themeId\":\"" + themeId + "\",\"stage\":\"waiting\",\"label\":\"Aguardando resposta do servidor...\"}");

            if (WinHttpSendRequest(hReq, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0) &&
                WinHttpReceiveResponse(hReq, nullptr)) {

              wchar_t contentType[256] = { 0 };
              DWORD ctSize = sizeof(contentType);
              WinHttpQueryHeaders(hReq, WINHTTP_QUERY_CONTENT_TYPE,
                                  WINHTTP_HEADER_NAME_BY_INDEX, contentType, &ctSize, WINHTTP_NO_HEADER_INDEX);
              std::string ctStr = toUtf8(contentType);

              HINTERNET streamReq = hReq;
              HINTERNET streamConnect = hConnect;

              // If Google Drive returned the Virus Scan Warning HTML page, parse form inputs (uuid, id)
              if (ctStr.find("text/html") != std::string::npos) {
                std::string body;
                char buf[4096];
                DWORD br = 0;
                while (WinHttpReadData(hReq, buf, sizeof(buf), &br) && br > 0) {
                  body.append(buf, br);
                  if (body.size() > 65536) break;
                }
                WinHttpCloseHandle(hReq);
                WinHttpCloseHandle(hConnect);
                streamReq = nullptr;
                streamConnect = nullptr;

                // Extract uuid and id
                auto getVal = [](const std::string &html, const std::string &name) -> std::string {
                  std::string n1 = "name=\"" + name + "\"";
                  size_t p = html.find(n1);
                  if (p == std::string::npos) {
                    n1 = "name='" + name + "'";
                    p = html.find(n1);
                  }
                  if (p != std::string::npos) {
                    size_t vp = html.find("value=\"", p);
                    if (vp != std::string::npos && vp - p < 150) {
                      size_t s = vp + 7;
                      size_t e = html.find("\"", s);
                      if (e != std::string::npos) return html.substr(s, e - s);
                    }
                    vp = html.find("value='", p);
                    if (vp != std::string::npos && vp - p < 150) {
                      size_t s = vp + 7;
                      size_t e = html.find("'", s);
                      if (e != std::string::npos) return html.substr(s, e - s);
                    }
                  }
                  return "";
                };

                std::string uuid = getVal(body, "uuid");
                std::string fileId = getVal(body, "id");
                if (fileId.empty()) {
                  size_t idPos = downloadUrlStr.find("id=");
                  if (idPos != std::string::npos) {
                    size_t idEnd = downloadUrlStr.find('&', idPos);
                    fileId = downloadUrlStr.substr(idPos + 3, (idEnd == std::string::npos ? downloadUrlStr.size() : idEnd) - (idPos + 3));
                  }
                }

                if (!uuid.empty() && !fileId.empty()) {
                  logThemeEngine("DOWNLOAD_CONFIRM", "IN_PROGRESS", "Theme: " + themeId + " requires virus bypass token: " + uuid);
                  streamConnect = WinHttpConnect(hSession, L"drive.usercontent.google.com", INTERNET_DEFAULT_HTTPS_PORT, 0);
                  if (streamConnect) {
                    std::wstring bypassPath = L"/download?id=" + toWide(fileId) + L"&export=download&confirm=t&uuid=" + toWide(uuid);
                    streamReq = WinHttpOpenRequest(streamConnect, L"GET", bypassPath.c_str(), nullptr,
                                                  WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, WINHTTP_FLAG_SECURE);
                    if (streamReq) {
                      WinHttpSetOption(streamReq, WINHTTP_OPTION_REDIRECT_POLICY, &redirectPolicy, sizeof(redirectPolicy));
                      if (!WinHttpSendRequest(streamReq, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0) ||
                          !WinHttpReceiveResponse(streamReq, nullptr)) {
                        WinHttpCloseHandle(streamReq);
                        streamReq = nullptr;
                      }
                    }
                  }
                }
              }

              if (streamReq) {
                DWORD contentLength = 0;
                DWORD clSize = sizeof(contentLength);
                WinHttpQueryHeaders(streamReq, WINHTTP_QUERY_CONTENT_LENGTH | WINHTTP_QUERY_FLAG_NUMBER,
                                    WINHTTP_HEADER_NAME_BY_INDEX, &contentLength, &clSize, WINHTTP_NO_HEADER_INDEX);

                std::ofstream out(tempFile, std::ios::binary);
                if (out.is_open()) {
                  std::vector<char> buffer(524288);
                  DWORD bytesRead = 0;
                  int lastReportedPercent = -1;
                  auto lastUiUpdate = std::chrono::steady_clock::now();

                  // Stage 3: Initial progress notification
                  postJsonToUI("{\"type\":\"theme_download_progress\",\"themeId\":\"" + themeId + "\",\"stage\":\"downloading\",\"percent\":0,\"downloaded\":0,\"total\":" + std::to_string(contentLength) + "}");

                  while (WinHttpReadData(streamReq, buffer.data(), (DWORD)buffer.size(), &bytesRead) && bytesRead > 0) {
                    if (cancelFlag && cancelFlag->load()) {
                      break;
                    }
                    out.write(buffer.data(), bytesRead);
                    totalBytesDownloaded += bytesRead;

                    int percent = (contentLength > 0) ? (int)((totalBytesDownloaded * 100) / contentLength) : 0;
                    if (percent > 100) percent = 100;

                    auto now = std::chrono::steady_clock::now();
                    double elapsedMs = std::chrono::duration<double, std::milli>(now - lastUiUpdate).count();
                    const bool milestone = (percent == 100) || (lastReportedPercent < 0) || (percent >= lastReportedPercent + 2);
                    if (milestone || elapsedMs >= 750) {
                      lastReportedPercent = percent;
                      lastUiUpdate = now;
                      postJsonToUI("{\"type\":\"theme_download_progress\",\"themeId\":\"" + themeId + "\",\"stage\":\"downloading\",\"percent\":" + std::to_string(percent) + ",\"downloaded\":" + std::to_string(totalBytesDownloaded) + ",\"total\":" + std::to_string(contentLength) + "}");
                    }
                  }
                  out.close();

                  // Check if download completed without cancellation and file is valid (> 50KB)
                  if (!cancelFlag->load() && totalBytesDownloaded > 50000) {
                    // Check first 16 bytes: make sure it's not HTML
                    std::ifstream checkIn(tempFile, std::ios::binary);
                    char magic[16] = { 0 };
                    checkIn.read(magic, 15);
                    checkIn.close();
                    std::string smagic(magic, 15);
                    if (smagic.find("<!DOCTYPE") == std::string::npos && smagic.find("<html") == std::string::npos) {
                      downloadSuccess = true;
                    } else {
                      logThemeEngine("DOWNLOAD_CORRUPT", "FAILED", "Theme: " + themeId + " downloaded as HTML instead of media");
                    }
                  }
                }
                WinHttpCloseHandle(streamReq);
              }
              if (streamConnect) WinHttpCloseHandle(streamConnect);
            } else {
              WinHttpCloseHandle(hReq);
              WinHttpCloseHandle(hConnect);
            }
          } else {
            WinHttpCloseHandle(hConnect);
          }
        }
      }
      WinHttpCloseHandle(hSession);
    }

    // Fallback: If WinHttp was not successful and not cancelled, attempt URLDownloadToFileW with cache clear
    if (!downloadSuccess && (!cancelFlag || !cancelFlag->load())) {
      logThemeEngine("DOWNLOAD_FALLBACK", "INFO", "Trying fallback URLDownloadToFileW for: " + themeId);
      DeleteUrlCacheEntryW(toWide(downloadUrlStr).c_str());
      ThemeDownloadCallback cb(themeId, cancelFlag);
      HRESULT hr = URLDownloadToFileW(nullptr, toWide(downloadUrlStr).c_str(), tempFile.c_str(), 0, &cb);
      if (SUCCEEDED(hr) && fs::exists(tempFile, ec) && fs::file_size(tempFile, ec) > 50000) {
        totalBytesDownloaded = fs::file_size(tempFile, ec);
        downloadSuccess = true;
      }
    }

    bool wasCancelled = (cancelFlag && cancelFlag->load());
    {
      std::lock_guard<std::mutex> lock(g_themeDownloadMutex);
      g_themeDownloadCancelMap.erase(themeId);
    }

    if (downloadSuccess && !wasCancelled && fs::exists(tempFile, ec)) {
      if (fs::exists(targetFile, ec)) fs::remove(targetFile, ec);
      fs::rename(tempFile, targetFile, ec);

      std::string rawId = themeId;
      if (rawId.rfind("theme_", 0) == 0) rawId = rawId.substr(6);
      if (rawId.rfind("steam_theme_", 0) == 0) rawId = rawId.substr(12);
      for (char &ch : rawId) {
        if (!std::isalnum((unsigned char)ch) && ch != '_' && ch != '-') ch = '_';
      }
      fs::path subDir = themeDir / rawId;
      if (!fs::exists(subDir, ec)) fs::create_directories(subDir, ec);

      if (enginePackage) {
        postJsonToUI("{\"type\":\"theme_download_stage\",\"themeId\":\"" + themeId + "\",\"stage\":\"extracting\",\"label\":\"Extraindo pacote do Wallpaper Engine...\"}");
        fs::path extractedMedia;
        std::string extractionError;
        if (!extractWallpaperEnginePackage(targetFile, subDir / "engine_extracted", extractedMedia, extractionError)) {
          fs::remove(targetFile, ec);
          logThemeEngine("ENGINE_IMPORT", "FAILED", "Theme: " + themeId + " | " + extractionError);
          postJsonToUI("{\"type\":\"theme_download_error\",\"themeId\":\"" + themeId + "\",\"error\":\"" + extractionError + "\"}");
          return;
        }
        const std::string mediaExt = extractedMedia.extension().string();
        cleanFileName = rawId + "_engine" + mediaExt;
        fs::path finalFile = themeDir / cleanFileName;
        fs::copy_file(extractedMedia, finalFile, fs::copy_options::overwrite_existing, ec);
        fs::copy_file(extractedMedia, subDir / ("wallpaper_hd" + mediaExt), fs::copy_options::overwrite_existing, ec);
        fs::remove(targetFile, ec);
        targetFile = finalFile;
      } else {
        std::string ext = targetFile.extension().string();
        fs::copy_file(targetFile, subDir / ("wallpaper_hd" + ext), fs::copy_options::overwrite_existing, ec);
      }

      std::string localUri = "file:///" + targetFile.generic_string();
      logThemeEngine(enginePackage ? "ENGINE_IMPORT" : "DOWNLOAD_COMPLETE", "SUCCESS", "Theme: " + themeId + " | File: " + cleanFileName + " | Bytes: " + std::to_string(totalBytesDownloaded) + " | Path: " + targetFile.string());
      postJsonToUI("{\"type\":\"theme_download_complete\",\"themeId\":\"" + themeId + "\",\"fileName\":\"" + cleanFileName + "\",\"localUri\":\"" + localUri + "\"}");
    } else {
      if (fs::exists(tempFile, ec)) fs::remove(tempFile, ec);
      if (wasCancelled) {
        logThemeEngine("DOWNLOAD_CANCEL", "CANCELLED", "Download cancelled by user: " + themeId);
        postJsonToUI("{\"type\":\"theme_download_cancelled\",\"themeId\":\"" + themeId + "\"}");
      } else {
        logThemeEngine("DOWNLOAD_ERROR", "FAILED", "Failed downloading theme: " + themeId);
        postJsonToUI("{\"type\":\"theme_download_error\",\"themeId\":\"" + themeId + "\",\"error\":\"Falha ao baixar tema do servidor.\"}");
      }
    }
  }).detach();
}

std::string getDownloadedThemesJson();
void loadAndSendLocalCustomThemes();
void importCustomTheme();
void openThemesFolder();

void deleteThemeAsset(const std::string &themeId, const std::string &fileName) {
  loadAndSendLocalCustomThemes();
  cancelThemeDownload(themeId);
  logThemeEngine("THEME_DELETE", "START", "Request to delete theme asset: " + themeId + " (" + fileName + ")");

  fs::path themeDir = getLocalTemasDir();
  std::error_code ec;

  std::string rawId = themeId;
  if (rawId.rfind("theme_", 0) == 0) rawId = rawId.substr(6);
  if (rawId.rfind("steam_theme_", 0) == 0) rawId = rawId.substr(12);

  int deletedCount = 0;
  if (!fileName.empty()) {
    fs::path targetFile = themeDir / fileName;
    fs::path tempFile = themeDir / (fileName + ".tmp");
    if (fs::exists(targetFile, ec)) { fs::remove(targetFile, ec); deletedCount++; }
    if (fs::exists(tempFile, ec)) fs::remove(tempFile, ec);
  }

  if (fs::exists(themeDir, ec)) {
    try {
      for (const auto &entry : fs::directory_iterator(themeDir, fs::directory_options::skip_permission_denied, ec)) {
        if (entry.is_regular_file()) {
          std::string stem = entry.path().stem().string();
          std::string fn = entry.path().filename().string();
          if (stem == themeId || stem == rawId || fn.find(themeId) == 0 || fn.find(rawId) == 0 || (!fileName.empty() && fn == fileName)) {
            fs::remove(entry.path(), ec);
            deletedCount++;
          }
        }
      }
      fs::path subDir = themeDir / rawId;
      if (fs::exists(subDir, ec)) {
        fs::remove_all(subDir, ec);
        deletedCount++;
      }
    } catch(...) {}
  }

  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    fs::path appThemeDir = fs::path(appData) / "DiscordUnlock" / "themes";
    if (fs::exists(appThemeDir, ec)) {
      try {
        for (const auto &entry : fs::directory_iterator(appThemeDir, fs::directory_options::skip_permission_denied, ec)) {
          if (entry.is_regular_file()) {
            std::string stem = entry.path().stem().string();
            std::string fn = entry.path().filename().string();
            if (stem == themeId || stem == rawId || fn.find(themeId) == 0 || fn.find(rawId) == 0 || (!fileName.empty() && fn == fileName)) {
              fs::remove(entry.path(), ec);
            }
          }
        }
      } catch(...) {}
    }
  }

  logThemeEngine("THEME_DELETE", "SUCCESS", "Deleted " + std::to_string(deletedCount) + " item(s) for theme: " + themeId);
  std::string filesJson = getDownloadedThemesJson();
  postJsonToUI("{ \"type\":\"theme_deleted\",\"themeId\":\"" + themeId + "\",\"files\":" + filesJson + "}");
  return;
  if (false) {
    fs::path themeDirLegacy;
    std::error_code ec;

    if (!fileName.empty()) {
      fs::path targetFile = themeDir / fileName;
      fs::path tempFile = themeDir / (fileName + ".tmp");
      if (fs::exists(targetFile, ec)) fs::remove(targetFile, ec);
      if (fs::exists(tempFile, ec)) fs::remove(tempFile, ec);
    }

    std::string rawId = themeId;
    if (rawId.rfind("theme_", 0) == 0) rawId = rawId.substr(6);
    if (rawId.rfind("steam_theme_", 0) == 0) rawId = rawId.substr(12);
    if (rawId.rfind("custom_theme_", 0) == 0) rawId = rawId.substr(13);
    if (rawId.rfind("local_custom_", 0) == 0) rawId = rawId.substr(13);

    int deletedCount = 0;
    if (fs::exists(themeDir, ec)) {
      try {
        for (const auto &entry : fs::directory_iterator(themeDir, fs::directory_options::skip_permission_denied, ec)) {
          if (entry.is_regular_file()) {
            std::string stem = entry.path().stem().string();
            std::string fn = entry.path().filename().string();
            if (stem == themeId || stem == rawId || fn.find(themeId) == 0 || fn.find(rawId) == 0 || (!fileName.empty() && fn == fileName)) {
              fs::remove(entry.path(), ec);
              deletedCount++;
            }
          }
        }
      } catch(...) {}
    }

    logThemeEngine("THEME_DELETE", "SUCCESS", "Deleted " + std::to_string(deletedCount) + " file(s) for theme: " + themeId);

    std::string filesJson = getDownloadedThemesJson();
    postJsonToUI("{\"type\":\"theme_deleted\",\"themeId\":\"" + themeId + "\",\"files\":" + filesJson + "}");
  }
}

std::string getDownloadedThemesJson() {
  std::string json = "[";
  std::vector<std::string> foundFiles;
  auto addUnique = [&](const std::string &s) {
    if (!s.empty() && std::find(foundFiles.begin(), foundFiles.end(), s) == foundFiles.end()) {
      foundFiles.push_back(s);
    }
  };

  // 1. Scan getLocalTemasDir() (C:/DiscordUnlock\temas)
  fs::path localTemas = getLocalTemasDir();
  if (fs::exists(localTemas)) {
    try {
      for (const auto &entry : fs::directory_iterator(localTemas)) {
        if (entry.path().extension() == ".tmp") continue;
        if (entry.is_directory()) {
          std::string dirName = entry.path().filename().string();
          addUnique(dirName);
          addUnique("theme_" + dirName);
          addUnique("steam_theme_" + dirName);
        } else if (entry.is_regular_file()) {
          std::string fn = entry.path().filename().string();
          std::string stem = entry.path().stem().string();
          addUnique(fn);
          addUnique(stem);
          addUnique("theme_" + stem);
          addUnique("steam_theme_" + stem);
        }
      }
    } catch (...) {}
  }

  // 2. Scan %APPDATA%\DiscordUnlock\themes
  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    fs::path themeDir = fs::path(appData) / "DiscordUnlock" / "themes";
    if (fs::exists(themeDir)) {
      try {
        for (const auto &entry : fs::directory_iterator(themeDir)) {
          if (entry.is_regular_file() && entry.path().extension() != ".tmp") {
            foundFiles.push_back(entry.path().filename().string());
          }
        }
      } catch (...) {}
    }
  }

  // Check local project themes
  fs::path localDir = fs::current_path() / "themes";
  if (fs::exists(localDir)) {
    try {
      for (const auto &entry : fs::directory_iterator(localDir)) {
        if (entry.is_regular_file() && entry.path().extension() != ".tmp") {
          std::string fn = entry.path().filename().string();
          if (std::find(foundFiles.begin(), foundFiles.end(), fn) == foundFiles.end()) {
            foundFiles.push_back(fn);
          }
        }
      }
    } catch (...) {}
  }

  for (size_t i = 0; i < foundFiles.size(); ++i) {
    if (i > 0) json += ",";
    json += "\"" + foundFiles[i] + "\"";
  }
  json += "]";
  return json;
}

std::string getLocalCustomThemesJson() {
  std::string json = "[";
  fs::path temasDir = getLocalTemasDir();
  std::error_code ec;
  if (fs::exists(temasDir, ec)) {
    static const std::unordered_set<std::string> knownCatalogIds = {
      "1979_pontiac_firebird", "aurora_borealis", "blue_space_black_hole", "car_floating_in_ocean",
      "cyberpunk_kobeni", "demon_samurai", "eve_frontier_black_holes", "ghibli_style_water_basin",
      "glowing_eyes_live", "ink_samurai", "jujutsu_kaisen_toji_fushiguro", "minecraft",
      "neverness_to_everness_nte_sakura", "prana_system_error", "rain_soaked_gt_r",
      "rezero_rem_under_the_moonlight", "running_water", "samurai_katana", "shadow_entity",
      "summer_mountain", "valorant_home_screen", "vampyre", "wanderer_and_misty_statues", "zane"
    };

    std::vector<std::string> customEntries;
    std::unordered_set<std::string> seenIds;
    std::unordered_set<std::string> seenFileNames;

    auto formatThemeTitle = [](const std::string &rawStem) -> std::string {
      std::string title = rawStem;
      if (title.rfind("theme_", 0) == 0) title = title.substr(6);
      if (title.rfind("steam_theme_", 0) == 0) title = title.substr(12);
      if (title.rfind("custom_theme_", 0) == 0) title = title.substr(13);
      for (char &ch : title) {
        if (ch == '_' || ch == '-') ch = ' ';
      }
      bool cap = true;
      for (char &ch : title) {
        if (cap && ch >= 'a' && ch <= 'z') ch = (char)(ch - 32);
        cap = (ch == ' ');
      }
      return title;
    };

    try {
      for (const auto &entry : fs::directory_iterator(temasDir, fs::directory_options::skip_permission_denied, ec)) {
        if (entry.path().extension() == ".tmp") continue;

        std::string fnLower = entry.path().filename().string();
        std::transform(fnLower.begin(), fnLower.end(), fnLower.begin(), ::tolower);
        if (fnLower.rfind("local_engine_", 0) == 0 || fnLower.find("_engine") != std::string::npos) continue;

        std::string stem = entry.path().stem().string();
        std::string rawId = stem;
        if (rawId.rfind("theme_", 0) == 0) rawId = rawId.substr(6);
        if (rawId.rfind("steam_theme_", 0) == 0) rawId = rawId.substr(12);
        if (rawId.rfind("custom_theme_", 0) == 0) rawId = rawId.substr(13);

        std::string rawIdLowerCheck = rawId;
        std::transform(rawIdLowerCheck.begin(), rawIdLowerCheck.end(), rawIdLowerCheck.begin(), ::tolower);
        if (rawIdLowerCheck.rfind("local_engine_", 0) == 0) continue;

        if (knownCatalogIds.count(rawId) || knownCatalogIds.count(stem)) continue;

        std::string rawIdLower = rawId;
        std::transform(rawIdLower.begin(), rawIdLower.end(), rawIdLower.begin(), ::tolower);
        if (seenIds.count(rawIdLower)) continue;

        fs::path actualFilePath;
        bool isVideo = false;

        if (entry.is_directory()) {
          for (const auto &sub : fs::directory_iterator(entry.path(), ec)) {
            if (!sub.is_regular_file()) continue;
            std::string ext = sub.path().extension().string();
            std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
            if (ext == ".mp4" || ext == ".webm" || ext == ".gif" || ext == ".png" || ext == ".jpg" || ext == ".jpeg" || ext == ".webp") {
              actualFilePath = sub.path();
              isVideo = (ext == ".mp4" || ext == ".webm" || ext == ".gif");
              break;
            }
          }
        } else if (entry.is_regular_file()) {
          std::string ext = entry.path().extension().string();
          std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
          if (ext == ".mp4" || ext == ".webm" || ext == ".gif" || ext == ".png" || ext == ".jpg" || ext == ".jpeg" || ext == ".webp") {
            actualFilePath = entry.path();
            isVideo = (ext == ".mp4" || ext == ".webm" || ext == ".gif");
          }
        }

        if (!actualFilePath.empty() && fs::exists(actualFilePath, ec)) {
          std::string fileName = actualFilePath.filename().string();
          std::string fnLower = fileName;
          std::transform(fnLower.begin(), fnLower.end(), fnLower.begin(), ::tolower);
          if (seenFileNames.count(fnLower)) continue;

          seenIds.insert(rawIdLower);
          seenIds.insert("custom_theme_" + rawIdLower);
          seenFileNames.insert(fnLower);

          uintmax_t sz = fs::file_size(actualFilePath, ec);
          double mb = (double)sz / (1024.0 * 1024.0);
          std::stringstream ssMb;
          ssMb << std::fixed << std::setprecision(1) << mb;

          std::string themeId = "custom_theme_" + rawId;
          std::string name = formatThemeTitle(rawId);
          std::string localUri = "http://127.0.0.1:45123/file?file=" + urlEncode(actualFilePath.string());

          std::string item = "{"
            "\"id\":\"" + escapeJsonString(themeId) + "\","
            "\"rawId\":\"" + escapeJsonString(rawId) + "\","
            "\"name\":\"" + escapeJsonString(name) + "\","
            "\"desc\":\"Tema local adicionado manualmente na pasta temas.\","
            "\"file_name\":\"" + escapeJsonString(fileName) + "\","
            "\"fileName\":\"" + escapeJsonString(fileName) + "\","
            "\"img\":\"" + escapeJsonString(localUri) + "\","
            "\"preview\":\"" + escapeJsonString(localUri) + "\","
            "\"size_mb\":" + ssMb.str() + ","
            "\"badge\":\"" + (isVideo ? "MP4 PERSONALIZADO" : "IMAGEM PERSONALIZADA") + "\","
            "\"accent\":\"#5865f2\","
            "\"isVideo\":" + (isVideo ? "true" : "false") + ","
            "\"isCustom\":true,"
            "\"isLocal\":true"
          "}";
          customEntries.push_back(item);
        }
      }
    } catch (...) {}

    for (size_t i = 0; i < customEntries.size(); ++i) {
      if (i > 0) json += ",";
      json += customEntries[i];
    }
  }
  json += "]";
  return json;
}

void loadAndSendLocalCustomThemes() {
  std::string json = getLocalCustomThemesJson();
  postJsonToUI("{\"type\":\"custom_themes_data\",\"themes\":" + json + "}");
}

void importCustomTheme() {
  std::thread([]() {
    wchar_t szFile[MAX_PATH] = { 0 };
    OPENFILENAMEW ofn = { 0 };
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = g_hWnd;
    ofn.lpstrFile = szFile;
    ofn.nMaxFile = sizeof(szFile) / sizeof(wchar_t);
    ofn.lpstrFilter = L"Todos os Formatos Suportados (*.mp4;*.webm;*.gif;*.png;*.jpg;*.jpeg;*.webp)\0*.mp4;*.webm;*.gif;*.png;*.jpg;*.jpeg;*.webp\0Vídeos MP4 / WebM (*.mp4;*.webm)\0*.mp4;*.webm\0Animações GIF (*.gif)\0*.gif\0Imagens (*.png;*.jpg;*.jpeg;*.webp)\0*.png;*.jpg;*.jpeg;*.webp\0Todos os Arquivos (*.*)\0*.*\0";
    ofn.nFilterIndex = 1;
    ofn.lpstrTitle = L"Selecione o Wallpaper / Vídeo para Adicionar ao Discord Unlock";
    ofn.Flags = OFN_PATHMUSTEXIST | OFN_FILEMUSTEXIST | OFN_NOCHANGEDIR;

    if (GetOpenFileNameW(&ofn)) {
      fs::path srcPath(szFile);
      std::error_code ec;
      if (fs::exists(srcPath, ec) && fs::file_size(srcPath, ec) > 1000) {
        fs::path temasDir = getLocalTemasDir();
        if (!fs::exists(temasDir, ec)) fs::create_directories(temasDir, ec);

        std::string fileName = srcPath.filename().string();
        std::string stem = srcPath.stem().string();

        fs::path destFile = temasDir / fileName;
        fs::copy_file(srcPath, destFile, fs::copy_options::overwrite_existing, ec);

        // Remove redundant duplicate subdirectory if one exists from older versions
        fs::path subDir = temasDir / stem;
        if (fs::exists(subDir, ec) && fs::is_directory(subDir, ec)) {
          fs::remove_all(subDir, ec);
        }

        logThemeEngine("THEME_IMPORT", "SUCCESS", "Imported custom theme: " + destFile.string());
        loadAndSendLocalCustomThemes();
        postJsonToUI("{\"type\":\"downloaded_themes_data\",\"files\":" + getDownloadedThemesJson() + "}");
        postJsonToUI("{\"type\":\"toast\",\"message\":\"Tema personalizado adicionado à galeria!\"}");
      }
    }
  }).detach();
}

void openThemesFolder() {
  fs::path temasDir = getLocalTemasDir();
  std::error_code ec;
  if (!fs::exists(temasDir, ec)) fs::create_directories(temasDir, ec);
  ShellExecuteW(nullptr, L"open", temasDir.c_str(), nullptr, nullptr, SW_SHOWNORMAL);
}

