std::string base64EncodeData(const std::vector<unsigned char>& data) {
  if (data.empty()) return "";
  DWORD size = 0;
  CryptBinaryToStringA(data.data(), (DWORD)data.size(), CRYPT_STRING_BASE64 | CRYPT_STRING_NOCRLF, nullptr, &size);
  if (size == 0) return "";
  std::string result(size, '\0');
  CryptBinaryToStringA(data.data(), (DWORD)data.size(), CRYPT_STRING_BASE64 | CRYPT_STRING_NOCRLF, &result[0], &size);
  if (!result.empty() && result.back() == '\0') result.pop_back();
  return result;
}

std::string sanitizeFilename(const std::string &name) {
  std::string clean;
  for (char c : name) {
    if (c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '-' || c == ' ') {
      clean += c;
    } else if (c == '.' || c == '/') {
      clean += '_';
    }
  }
  if (clean.empty()) clean = "sound_" + std::to_string(GetTickCount64());
  // trim spaces
  while (!clean.empty() && clean.front() == ' ') clean.erase(clean.begin());
  while (!clean.empty() && clean.back() == ' ') clean.pop_back();
  return clean;
}

#include "soundboard_integration.inc"

bool executeNativeSoundboardHotkey(const std::string &keyName) {
  const std::string key = normalizeNativeHotkey(keyName);
  if (key.empty()) return false;

  const ULONGLONG now = GetTickCount64();
  const ULONGLONG previous = g_lastNativeSoundboardHotkeyAt.load();
  if (previous && now - previous < 180) return true;

  NativeSoundboardBinding selected;
  bool playSound = false;
  bool stopAll = false;
  bool toggleVoice = false;
  std::string voicePreset;
  {
    std::lock_guard<std::mutex> lock(g_nativeSoundboardBindingsMutex);
    if (!g_nativeStopAllHotkey.empty() && key == g_nativeStopAllHotkey) {
      stopAll = true;
    } else if (!g_nativeVoiceToggleHotkey.empty() && key == g_nativeVoiceToggleHotkey) {
      toggleVoice = true;
      voicePreset = g_nativeVoicePreset;
    } else if (g_nativeSoundboardEnabled.load()) {
      for (const auto &binding : g_nativeSoundboardBindings) {
        if (key == binding.keybind) {
          selected = binding;
          playSound = true;
          break;
        }
      }
    }
  }
  if (!stopAll && !toggleVoice && !playSound) return false;
  g_lastNativeSoundboardHotkeyAt.store(now);

  if (stopAll) {
    DiscordUnlock::NativeSoundboardEngine::Instance().StopAll();
    std::string ignored;
    DiscordUnlock::ClownfishBridge::Send("0|", ignored);
    return true;
  }
  if (toggleVoice) {
    const bool enabled = !g_nativeVoiceEnabled.load();
    g_nativeVoiceEnabled.store(enabled);
    handleClownfishAction("clownfish_set_enabled", std::string("{\"enabled\":") + (enabled ? "true}" : "false}"));
    if (enabled) handleClownfishAction("clownfish_set_voice", "{\"preset\":\"" + escapeJsonString(voicePreset) + "\"}");
    return true;
  }

  std::thread([selected]() {
    std::string storedName, error;
    const fs::path filePath = materializeSoundboardFile(selected.id, selected.name, selected.fileName, "", storedName, error);
    if (filePath.empty()) return;
    // Use the same transmission, volume and error handling as the Play button.
    handleNativeSoundboardAction("soundboard_play_native",
        "{\"soundId\":\"" + escapeJsonString(selected.id) +
        "\",\"name\":\"" + escapeJsonString(selected.name) +
        "\",\"fileName\":\"" + escapeJsonString(storedName) +
        "\",\"gain\":" + std::to_string(selected.gain) + "}");
  }).detach();
  return true;
}

void searchMyInstantsAsync(const std::string &query) {
  std::thread([query]() {
    std::wstring path = L"/pt/index/br/";
    std::string cleanQuery = query;

    // trim
    while (!cleanQuery.empty() && (cleanQuery.front() == ' ' || cleanQuery.front() == '\t')) cleanQuery.erase(cleanQuery.begin());
    while (!cleanQuery.empty() && (cleanQuery.back() == ' ' || cleanQuery.back() == '\t')) cleanQuery.pop_back();

    if (!cleanQuery.empty() && cleanQuery != "top" && cleanQuery != "top_br") {
      // url encode simple
      std::string encoded;
      for (unsigned char c : cleanQuery) {
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.') {
          encoded += c;
        } else if (c == ' ') {
          encoded += '+';
        } else {
          char hex[8];
          sprintf_s(hex, "%%%02X", c);
          encoded += hex;
        }
      }
      path = L"/pt/search/?name=" + toWide(encoded);
    }

    HINTERNET hSession = WinHttpOpen(L"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                                    WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                    WINHTTP_NO_PROXY_NAME,
                                    WINHTTP_NO_PROXY_BYPASS, 0);
    if (!hSession) {
      postJsonToUI("{\"type\":\"myinstants_search_result\",\"query\":\"" + escapeJsonString(query) + "\",\"sounds\":[]}");
      return;
    }

    WinHttpSetTimeouts(hSession, 5000, 8000, 8000, 10000);

    HINTERNET hConnect = WinHttpConnect(hSession, L"www.myinstants.com", INTERNET_DEFAULT_HTTPS_PORT, 0);
    if (!hConnect) {
      WinHttpCloseHandle(hSession);
      postJsonToUI("{\"type\":\"myinstants_search_result\",\"query\":\"" + escapeJsonString(query) + "\",\"sounds\":[]}");
      return;
    }

    HINTERNET hReq = WinHttpOpenRequest(hConnect, L"GET", path.c_str(), nullptr,
                                       WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, WINHTTP_FLAG_SECURE);
    if (!hReq) {
      WinHttpCloseHandle(hConnect);
      WinHttpCloseHandle(hSession);
      postJsonToUI("{\"type\":\"myinstants_search_result\",\"query\":\"" + escapeJsonString(query) + "\",\"sounds\":[]}");
      return;
    }

    DWORD redirectPolicy = WINHTTP_OPTION_REDIRECT_POLICY_ALWAYS;
    WinHttpSetOption(hReq, WINHTTP_OPTION_REDIRECT_POLICY, &redirectPolicy, sizeof(redirectPolicy));

    std::string html;
    if (WinHttpSendRequest(hReq, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0) &&
        WinHttpReceiveResponse(hReq, nullptr)) {
      DWORD bytesAvailable = 0;
      while (WinHttpQueryDataAvailable(hReq, &bytesAvailable) && bytesAvailable > 0) {
        std::vector<char> buf(bytesAvailable);
        DWORD bytesRead = 0;
        if (WinHttpReadData(hReq, buf.data(), bytesAvailable, &bytesRead) && bytesRead > 0) {
          html.append(buf.data(), bytesRead);
        } else {
          break;
        }
      }
    }

    WinHttpCloseHandle(hReq);
    WinHttpCloseHandle(hConnect);
    WinHttpCloseHandle(hSession);

    // Parse HTML with regex
    std::string soundsJson = "[";
    if (!html.empty()) {
      try {
        std::regex instantRegex("<div class=\"instant\">([\\s\\S]*?)</div>\\s*</div>");
        std::regex mp3Regex("play\\(['\"]([^'\"]+\\.mp3)['\"]");
        std::regex linkRegex("<a[^>]*class=\"instant-link[^\"]*\"[^>]*>([\\s\\S]*?)</a>");

        auto begin = std::sregex_iterator(html.begin(), html.end(), instantRegex);
        auto end = std::sregex_iterator();

        int count = 0;
        for (std::sregex_iterator i = begin; i != end; ++i) {
          std::smatch match = *i;
          std::string block = match.str(1);

          std::smatch mp3Match, linkMatch;
          if (std::regex_search(block, mp3Match, mp3Regex) && std::regex_search(block, linkMatch, linkRegex)) {
            std::string mp3 = mp3Match.str(1);
            std::string name = linkMatch.str(1);
            // remove html tags
            name = std::regex_replace(name, std::regex("<[^>]+>"), "");
            while (!name.empty() && (name.front() == ' ' || name.front() == '\t' || name.front() == '\r' || name.front() == '\n')) name.erase(name.begin());
            while (!name.empty() && (name.back() == ' ' || name.back() == '\t' || name.back() == '\r' || name.back() == '\n')) name.pop_back();

            std::string audioUrl = mp3;
            if (audioUrl.rfind("/", 0) == 0) {
              audioUrl = "https://www.myinstants.com" + audioUrl;
            }

            // Extract sound id
            size_t slash = mp3.rfind('/');
            std::string idStr = (slash != std::string::npos) ? mp3.substr(slash + 1) : mp3;
            size_t dot = idStr.rfind(".mp3");
            if (dot != std::string::npos) idStr = idStr.substr(0, dot);
            for (char &c : idStr) {
              if (!isalnum((unsigned char)c) && c != '_') c = '_';
            }

            if (count > 0) soundsJson += ",";
            soundsJson += "{\"id\":\"" + escapeJsonString(idStr) + "\",\"name\":\"" + escapeJsonString(name) + "\",\"audioUrl\":\"" + escapeJsonString(audioUrl) + "\"}";
            count++;
            if (count >= 40) break;
          }
        }
      } catch(...) {}
    }
    soundsJson += "]";

    std::string response = "{\"type\":\"myinstants_search_result\",\"query\":\"" + escapeJsonString(query) + "\",\"sounds\":" + soundsJson + "}";
    postJsonToUI(response);
  }).detach();
}

void downloadSoundAsync(const std::string &soundId, const std::string &name, const std::string &audioUrl) {
  std::thread([soundId, name, audioUrl]() {
    std::string fullUrl = audioUrl;
    if (fullUrl.rfind("/", 0) == 0) {
      fullUrl = "https://www.myinstants.com" + fullUrl;
    }

    std::wstring host = L"www.myinstants.com";
    std::wstring path = L"/";

    // Parse host and path from URL
    size_t schemePos = fullUrl.find("://");
    std::string urlWithoutScheme = (schemePos != std::string::npos) ? fullUrl.substr(schemePos + 3) : fullUrl;
    size_t firstSlash = urlWithoutScheme.find('/');
    if (firstSlash != std::string::npos) {
      host = toWide(urlWithoutScheme.substr(0, firstSlash));
      path = toWide(urlWithoutScheme.substr(firstSlash));
    } else {
      host = toWide(urlWithoutScheme);
      path = L"/";
    }

    HINTERNET hSession = WinHttpOpen(L"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                                    WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                    WINHTTP_NO_PROXY_NAME,
                                    WINHTTP_NO_PROXY_BYPASS, 0);
    if (!hSession) {
      postJsonToUI("{\"type\":\"sound_download_complete\",\"soundId\":\"" + soundId + "\",\"name\":\"" + escapeJsonString(name) + "\",\"success\":false,\"error\":\"Falha ao inicializar HTTP\"}");
      return;
    }

    WinHttpSetTimeouts(hSession, 6000, 10000, 10000, 15000);

    HINTERNET hConnect = WinHttpConnect(hSession, host.c_str(), INTERNET_DEFAULT_HTTPS_PORT, 0);
    if (!hConnect) {
      WinHttpCloseHandle(hSession);
      postJsonToUI("{\"type\":\"sound_download_complete\",\"soundId\":\"" + soundId + "\",\"name\":\"" + escapeJsonString(name) + "\",\"success\":false,\"error\":\"Falha ao conectar ao servidor\"}");
      return;
    }

    HINTERNET hReq = WinHttpOpenRequest(hConnect, L"GET", path.c_str(), nullptr,
                                       WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, WINHTTP_FLAG_SECURE);
    if (!hReq) {
      WinHttpCloseHandle(hConnect);
      WinHttpCloseHandle(hSession);
      postJsonToUI("{\"type\":\"sound_download_complete\",\"soundId\":\"" + soundId + "\",\"name\":\"" + escapeJsonString(name) + "\",\"success\":false,\"error\":\"Falha na requisição HTTP\"}");
      return;
    }

    DWORD redirectPolicy = WINHTTP_OPTION_REDIRECT_POLICY_ALWAYS;
    WinHttpSetOption(hReq, WINHTTP_OPTION_REDIRECT_POLICY, &redirectPolicy, sizeof(redirectPolicy));

    std::vector<unsigned char> soundBytes;
    bool success = false;

    if (WinHttpSendRequest(hReq, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0) &&
        WinHttpReceiveResponse(hReq, nullptr)) {
      DWORD bytesAvailable = 0;
      while (WinHttpQueryDataAvailable(hReq, &bytesAvailable) && bytesAvailable > 0) {
        std::vector<unsigned char> buffer(bytesAvailable);
        DWORD bytesRead = 0;
        if (WinHttpReadData(hReq, buffer.data(), bytesAvailable, &bytesRead) && bytesRead > 0) {
          soundBytes.insert(soundBytes.end(), buffer.begin(), buffer.begin() + bytesRead);
        } else {
          break;
        }
      }
      if (!soundBytes.empty()) {
        success = true;
      }
    }

    WinHttpCloseHandle(hReq);
    WinHttpCloseHandle(hConnect);
    WinHttpCloseHandle(hSession);

    if (!success || soundBytes.empty()) {
      postJsonToUI("{\"type\":\"sound_download_complete\",\"soundId\":\"" + soundId + "\",\"name\":\"" + escapeJsonString(name) + "\",\"success\":false,\"error\":\"Arquivo de som vazio ou indisponível\"}");
      return;
    }

    // Save to disk
    fs::path soundsDir = getLocalSoundsDir();
    std::string safeName = sanitizeFilename(name);
    if (safeName.empty()) safeName = "sound_" + soundId;
    std::string fileName = safeName + ".mp3";
    fs::path targetFile = soundsDir / fileName;

    std::error_code ec;
    std::ofstream out(targetFile, std::ios::binary);
    if (out.is_open()) {
      out.write(reinterpret_cast<const char*>(soundBytes.data()), soundBytes.size());
      out.close();
    }

    // Mirror copy to %APPDATA%\DiscordUnlock\sons
    wchar_t *appData = nullptr;
    if (_wdupenv_s(&appData, nullptr, L"APPDATA") == 0 && appData) {
      fs::path appDataDir = fs::path(appData) / "DiscordUnlock" / "sons";
      if (fs::exists(appDataDir, ec)) {
        std::ofstream outApp(appDataDir / fileName, std::ios::binary);
        if (outApp.is_open()) {
          outApp.write(reinterpret_cast<const char*>(soundBytes.data()), soundBytes.size());
          outApp.close();
        }
      }
      free(appData);
    }
    std::string response = "{\"type\":\"sound_download_complete\",\"soundId\":\"" + soundId + "\",\"name\":\"" + escapeJsonString(name) + "\",\"fileName\":\"" + escapeJsonString(fileName) + "\",\"success\":true}";
    postJsonToUI(response);
  }).detach();
}

void scanLocalSounds() {
  std::thread([]() {
    fs::path soundsDir = getLocalSoundsDir();
    std::error_code ec;
    if (!fs::exists(soundsDir, ec)) return;

    std::string soundsJson = "[";
    int count = 0;
    for (const auto &entry : fs::directory_iterator(soundsDir, fs::directory_options::skip_permission_denied, ec)) {
      if (entry.is_regular_file()) {
        std::string ext = entry.path().extension().string();
        for (char &c : ext) c = (char)tolower(c);
        if (ext == ".mp3" || ext == ".wav") {
          std::string fn = entry.path().filename().string();
          std::string soundName = entry.path().stem().string();

          if (count > 0) soundsJson += ",";
          soundsJson += "{\"name\":\"" + escapeJsonString(soundName) + "\",\"filename\":\"" + escapeJsonString(fn) + "\"}";
          count++;
        }
      }
    }
    soundsJson += "]";

    if (count > 0) {
      postJsonToUI("{\"type\":\"local_sounds_synced\",\"sounds\":" + soundsJson + "}");
    }
  }).detach();
}



