inline fs::path getWireSockLogPath() {
  wchar_t appData[MAX_PATH] = { 0 };
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) == 0) return fs::path();
  fs::path dataDir = fs::path(appData) / "DiscordUnlock";
  std::error_code ec;
  fs::create_directories(dataDir, ec);
  return dataDir / "golivebypass.log";
}

inline void logWireSock(const std::string &eventName, const std::string &details = "") {
  try {
    const fs::path logPath = getWireSockLogPath();
    if (logPath.empty()) return;
    SYSTEMTIME st;
    GetLocalTime(&st);
    std::ostringstream line;
    line << std::setfill('0') << std::setw(4) << st.wYear << "-"
         << std::setw(2) << st.wMonth << "-" << std::setw(2) << st.wDay << " "
         << std::setw(2) << st.wHour << ":" << std::setw(2) << st.wMinute << ":"
         << std::setw(2) << st.wSecond << " [" << eventName << "]";
    if (!details.empty()) line << " " << details;
    line << "\r\n";
    const std::string bytes = line.str();

    std::lock_guard<std::mutex> lock(g_wireSockLogMutex);
    HANDLE file = CreateFileW(logPath.wstring().c_str(), FILE_APPEND_DATA,
                              FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr, OPEN_ALWAYS,
                              FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) return;
    DWORD written = 0;
    WriteFile(file, bytes.data(), static_cast<DWORD>(bytes.size()), &written, nullptr);
    CloseHandle(file);
  } catch (...) {}
}
inline bool isWireSockEngineAlive(DWORD *lastExitCode = nullptr) {
  {
    std::lock_guard<std::mutex> lock(g_wireSockHandleMutex);
    if (g_hWireSockProcess) {
      DWORD exitCode = 0;
      if (GetExitCodeProcess(g_hWireSockProcess, &exitCode) && exitCode == STILL_ACTIVE) return true;
      if (lastExitCode) *lastExitCode = exitCode;
      CloseHandle(g_hWireSockProcess);
      g_hWireSockProcess = nullptr;
    }
  }

  SC_HANDLE hSCM = OpenSCManagerW(nullptr, nullptr, SC_MANAGER_CONNECT);
  if (!hSCM) return false;
  bool running = false;
  const wchar_t *serviceNames[] = { L"wiresock-client-service", L"wiresock-pro-client-service" };
  for (const wchar_t *serviceName : serviceNames) {
    SC_HANDLE hSvc = OpenServiceW(hSCM, serviceName, SERVICE_QUERY_STATUS);
    if (!hSvc) continue;
    SERVICE_STATUS_PROCESS ssp = { 0 };
    DWORD bytesNeeded = 0;
    if (QueryServiceStatusEx(hSvc, SC_STATUS_PROCESS_INFO, reinterpret_cast<LPBYTE>(&ssp), sizeof(ssp), &bytesNeeded)) {
      running = (ssp.dwCurrentState == SERVICE_RUNNING || ssp.dwCurrentState == SERVICE_START_PENDING);
      if (lastExitCode && !running) *lastExitCode = ssp.dwWin32ExitCode;
    }
    CloseServiceHandle(hSvc);
    if (running) break;
  }
  CloseServiceHandle(hSCM);
  return running;
}
static std::string g_customConfName = "";
