inline bool hasCompleteWireSockPackage(const fs::path &clientExe) {
  try {
    static const std::string kWireSockExeSha256 = "1c9a3fb963fe20c23ab3a8fcbf738c57cb29142d9da161f522aa0290d741443d";
    std::error_code ec;
    if (!fs::exists(clientExe, ec) || fs::file_size(clientExe, ec) <= 100000 ||
        computeFileSHA256(clientExe.wstring()) != kWireSockExeSha256) return false;
    const fs::path packageDir = clientExe.parent_path();
    const fs::path probeSource = packageDir / "Discord.exe";
    return fs::exists(probeSource, ec) && fs::file_size(probeSource, ec) > 100000 &&
           fs::exists(packageDir / "ndiswgc_lwf.inf", ec) &&
           fs::exists(packageDir / "wiresock-client.exe", ec);
  } catch (...) { return false; }
}
inline std::wstring locateWireSockExe() {
  static const std::string kWireSockExeSha256 = "1c9a3fb963fe20c23ab3a8fcbf738c57cb29142d9da161f522aa0290d741443d";
  static const std::string kWireSockZipSha256 = "a200a76d823fe68f01d2599bc5eee85b71d7ef8d062b9c8b0dfcb9fe8d0369fd";
  wchar_t exePath[MAX_PATH];
  GetModuleFileNameW(nullptr, exePath, MAX_PATH);
  fs::path exeDir = fs::path(exePath).parent_path();
  std::vector<fs::path> candidates = {
    exeDir / "bin" / "wiresock" / "wiresock-client.exe",
    exeDir / "wiresock" / "wiresock-client.exe",
    exeDir / "bin" / "wiresock.exe",
    fs::path("C:/DiscordUnlock/Release_GUI/bin/wiresock/wiresock-client.exe"),
    fs::path("C:/DiscordUnlock/bin/wiresock/wiresock-client.exe"),
    fs::path("C:/Program Files/WireSock Secure Connect/sdk/wiresock-client.exe"),
    fs::path("C:/Program Files/WireSock Secure Connect/wiresock-client.exe")
  };
  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    candidates.push_back(fs::path(appData) / "DiscordUnlock" / "bin" / "wiresock" / "wiresock-client.exe");
  }
  for (const auto &p : candidates) {
    std::error_code ec;
    if (hasCompleteWireSockPackage(p)) return p.wstring();
  }

  // AUTO-PROVISIONING: Baixar wiresock.zip do GitHub automaticamente se ausente
  try {
    fs::path wsDir = exeDir / "bin" / "wiresock";
    std::error_code ec;
    if (!fs::exists(wsDir, ec)) fs::create_directories(wsDir, ec);

    fs::path wsZip = exeDir / "bin" / "wiresock.zip";
    // O pacote acompanha o executavel para funcionar em PCs sem acesso ao GitHub.
    bool ok = extractResourceToFile(106, wsZip);
    if (!ok || !fs::exists(wsZip, ec) || fs::file_size(wsZip, ec) < 50000) {
      ok = downloadBinary(CLOUD_API_HOST, L"/updates/dependencies/wiresock.zip", wsZip.wstring());
    }
    if (!ok) {
      ok = downloadBinary(CLOUD_API_HOST, L"/updates/dependencies/wiresock.zip", wsZip.wstring());
    }
    if (ok && computeFileSHA256(wsZip.wstring()) != kWireSockZipSha256) {
      fs::remove(wsZip, ec);
      ok = false;
    }
    if (ok && fs::exists(wsZip, ec) && fs::file_size(wsZip, ec) > 50000) {
      std::wstring psCmd = L"powershell.exe -NoProfile -ExecutionPolicy Bypass -Command \"Expand-Archive -Path '" + wsZip.wstring() + L"' -DestinationPath '" + wsDir.wstring() + L"' -Force\"";
      std::vector<wchar_t> buf(psCmd.begin(), psCmd.end()); buf.push_back(wchar_t(0));
      STARTUPINFOW si = { sizeof(si) }; si.dwFlags = STARTF_USESHOWWINDOW; si.wShowWindow = SW_HIDE;
      PROCESS_INFORMATION pi = { 0 };
      if (CreateProcessW(nullptr, buf.data(), nullptr, nullptr, FALSE, CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT, nullptr, nullptr, &si, &pi)) {
        WaitForSingleObject(pi.hProcess, 15000);
        CloseHandle(pi.hProcess); CloseHandle(pi.hThread);
      }
      fs::remove(wsZip, ec);
    }

    fs::path targetExe = wsDir / "wiresock-client.exe";
    if (hasCompleteWireSockPackage(targetExe)) {
      logWireSock("PACKAGE_READY", "Pacote WireSock validado e componentes de rota presentes.");
      return targetExe.wstring();
    }
  } catch (...) {}

  return L"";
}

inline void stopWireSockEngine() {
  g_wireSockExpectedActive = false;

  HANDLE processToStop = nullptr;
  {
    std::lock_guard<std::mutex> lock(g_wireSockHandleMutex);
    processToStop = g_hWireSockProcess;
    g_hWireSockProcess = nullptr;
  }
  if (processToStop) {
    TerminateProcess(processToStop, 0);
    WaitForSingleObject(processToStop, 1500);
    CloseHandle(processToStop);
  }

  // Stop either WireSock service edition if it was used as a recovery fallback.
  SC_HANDLE hSCM = OpenSCManagerW(nullptr, nullptr, SC_MANAGER_CONNECT);
  if (hSCM) {
    const wchar_t *serviceNames[] = { L"wiresock-client-service", L"wiresock-pro-client-service" };
    for (const wchar_t *serviceName : serviceNames) {
      SC_HANDLE hSvc = OpenServiceW(hSCM, serviceName, SERVICE_STOP | SERVICE_QUERY_STATUS);
      if (!hSvc) continue;
      SERVICE_STATUS status = { 0 };
      ControlService(hSvc, SERVICE_CONTROL_STOP, &status);
      CloseServiceHandle(hSvc);
    }
    CloseServiceHandle(hSCM);
  }

  killProcessByName(L"wiresock-client.exe");

  // Reset network lock to restore clean driver state.
  std::wstring wsExe = locateWireSockExe();
  if (!wsExe.empty()) {
    STARTUPINFOW si = { sizeof(si) };
    si.cb = sizeof(si);
    si.dwFlags = STARTF_USESHOWWINDOW;
    si.wShowWindow = SW_HIDE;
    PROCESS_INFORMATION pi = { 0 };
    std::wstring cmd = L"\"" + wsExe + L"\" reset-network-lock";
    std::vector<wchar_t> buf(cmd.begin(), cmd.end());
    buf.push_back(wchar_t(0));
    if (CreateProcessW(nullptr, buf.data(), nullptr, nullptr, FALSE, CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT, nullptr, nullptr, &si, &pi)) {
      WaitForSingleObject(pi.hProcess, 3000);
      CloseHandle(pi.hProcess);
      CloseHandle(pi.hThread);
    }
  }

  STARTUPINFOW siDns = { sizeof(siDns) };
  siDns.cb = sizeof(siDns);
  siDns.dwFlags = STARTF_USESHOWWINDOW;
  siDns.wShowWindow = SW_HIDE;
  PROCESS_INFORMATION piDns = { 0 };
  wchar_t dnsCmd[] = L"ipconfig /flushdns";
  if (CreateProcessW(nullptr, dnsCmd, nullptr, nullptr, FALSE, CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT, nullptr, nullptr, &siDns, &piDns)) {
    WaitForSingleObject(piDns.hProcess, 2000);
    CloseHandle(piDns.hProcess);
    CloseHandle(piDns.hThread);
  }
  logWireSock("STOP", "WireSock encerrado e estado de rede limpo.");
}
