void executeEmergencyKillSwitch() {
  try {
    // 1. Kill Discord
    enableDebugPrivilege();
    killDiscord();
    killProcessByName(L"Discord.exe");
    killProcessByName(L"DiscordCanary.exe");
    killProcessByName(L"DiscordPTB.exe");
    killProcessByName(L"DiscordDevelopment.exe");
    killProcessByName(L"Update.exe");

    // 2. Stop WireSock & all network tunnels / filters
    stopWireSockEngine();
    killProcessByName(L"wiresock-client.exe");
    killProcessByName(L"sing-box.exe");
    killProcessByName(L"ca.psiphon.PsiphonTunnel.tunnel-core.exe");

    // Terminate node helper processes
    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (hSnap != INVALID_HANDLE_VALUE) {
      PROCESSENTRY32W pe = { sizeof(pe) };
      if (Process32FirstW(hSnap, &pe)) {
        do {
          if (_wcsicmp(pe.szExeFile, L"node.exe") == 0) {
            HANDLE hProc = OpenProcess(PROCESS_TERMINATE, FALSE, pe.th32ProcessID);
            if (hProc) {
              TerminateProcess(hProc, 0);
              CloseHandle(hProc);
            }
          }
        } while (Process32NextW(hSnap, &pe));
      }
      CloseHandle(hSnap);
    }

    // Reset Windows Internet / Proxy options to DIRECT (no proxy / PAC)
    try {
      INTERNET_PER_CONN_OPTION_LISTW list;
      INTERNET_PER_CONN_OPTIONW options[1];
      DWORD dwBufSize = sizeof(list);
      list.dwSize = sizeof(list);
      list.pszConnection = nullptr;
      list.dwOptionCount = 1;
      list.dwOptionError = 0;
      list.pOptions = options;
      options[0].dwOption = INTERNET_PER_CONN_FLAGS;
      options[0].Value.dwValue = PROXY_TYPE_DIRECT;
      InternetSetOptionW(nullptr, INTERNET_OPTION_PER_CONNECTION_OPTION, &list, dwBufSize);
      InternetSetOptionW(nullptr, INTERNET_OPTION_SETTINGS_CHANGED, nullptr, 0);
      InternetSetOptionW(nullptr, INTERNET_OPTION_REFRESH, nullptr, 0);
    } catch (...) {}

    // 3. Restore Discord to genuine clean/original factory state
    std::vector<fs::path> searchRoots;
    if (!g_targetExe.empty()) {
      fs::path directExe(g_targetExe);
      fs::path parentDir = directExe.parent_path();
      searchRoots.push_back(parentDir);
      if (parentDir.has_parent_path()) searchRoots.push_back(parentDir.parent_path());
    }
    const wchar_t drives[] = L"CDEFGHIJKLMNOPQRSTUVWXYZ";
    for (int d = 0; drives[d] != L'\0'; ++d) {
      searchRoots.push_back(std::wstring(1, drives[d]) + L":\\Discord");
    }
    wchar_t localApp[MAX_PATH];
    if (GetEnvironmentVariableW(L"LOCALAPPDATA", localApp, MAX_PATH) > 0) {
      searchRoots.push_back(fs::path(localApp) / "Discord");
      searchRoots.push_back(fs::path(localApp) / "DiscordCanary");
      searchRoots.push_back(fs::path(localApp) / "DiscordPTB");
    }

    std::vector<fs::path> appDirs;
    for (const auto &root : searchRoots) {
      if (fs::exists(root)) {
        try {
          if (root.filename().string().find("app-") == 0) {
            appDirs.push_back(root);
          }
          for (const auto &entry : fs::directory_iterator(root)) {
            if (entry.is_directory() && entry.path().filename().string().find("app-") == 0) {
              appDirs.push_back(entry.path());
            }
          }
        } catch(...) {}
      }
    }
    std::sort(appDirs.begin(), appDirs.end());
    appDirs.erase(std::unique(appDirs.begin(), appDirs.end()), appDirs.end());

    std::string stockIndexJs = "module.exports = require('./core.asar');\n";
    for (const auto &ad : appDirs) {
      fs::path modulesDir = ad / "modules";
      if (fs::exists(modulesDir)) {
        try {
          for (const auto &mEntry : fs::directory_iterator(modulesDir)) {
            if (mEntry.is_directory() && mEntry.path().filename().string().find("discord_desktop_core") == 0) {
              fs::path coreSub = mEntry.path() / "discord_desktop_core";
              fs::path targetIndex = fs::exists(coreSub) ? (coreSub / "index.js") : (mEntry.path() / "index.js");
              std::ofstream f(targetIndex.string());
              if (f.is_open()) {
                f << stockIndexJs;
                f.close();
              }
            }
          }
        } catch(...) {}
      }
    }

    // Clean up theme configs, locks, and active proxy
    wchar_t appData[MAX_PATH];
    if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
      std::error_code ec;
      fs::remove(fs::path(appData) / "discord" / "lockfile", ec);
      fs::remove(fs::path(appData) / "discord" / "theme_trigger.json", ec);
      fs::remove(fs::path(appData) / "BetterDiscord" / "data" / "theme_trigger.json", ec);

      fs::path themePath = fs::path(appData) / "discord" / "discord_unlock_theme.css";
      if (fs::exists(themePath, ec)) {
        std::ofstream ft(themePath.string());
        if (ft.is_open()) { ft << "/* Default Discord Theme Restored */\n"; ft.close(); }
      }
      fs::path wpPath = fs::path(appData) / "discord" / "discord_unlock_wallpaper.json";
      if (fs::exists(wpPath, ec)) fs::remove(wpPath, ec);

      fs::path bdThemesJson = fs::path(appData) / "BetterDiscord" / "data" / "stable" / "themes.json";
      if (fs::exists(bdThemesJson, ec)) {
        std::ofstream fb(bdThemesJson.string());
        if (fb.is_open()) { fb << "{}"; fb.close(); }
      }

      fs::path activeProxy = fs::path(appData) / "DiscordUnlock" / "active_proxy.txt";
      if (fs::exists(activeProxy, ec)) fs::remove(activeProxy, ec);
    }

    // Flush DNS
    STARTUPINFOW siDns = { sizeof(siDns) };
    siDns.cb = sizeof(siDns);
    siDns.dwFlags = STARTF_USESHOWWINDOW;
    siDns.wShowWindow = SW_HIDE;
    PROCESS_INFORMATION piDns = { 0 };
    wchar_t dnsCmd[] = L"ipconfig /flushdns";
    if (CreateProcessW(nullptr, dnsCmd, nullptr, nullptr, FALSE, CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT, nullptr, nullptr, &siDns, &piDns)) {
      WaitForSingleObject(piDns.hProcess, 1500);
      CloseHandle(piDns.hProcess);
      CloseHandle(piDns.hThread);
    }

    // Terminate any other DiscordUnlock instances
    DWORD myPid = GetCurrentProcessId();
    HANDLE hSnapDU = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (hSnapDU != INVALID_HANDLE_VALUE) {
      PROCESSENTRY32W pe = { sizeof(pe) };
      if (Process32FirstW(hSnapDU, &pe)) {
        do {
          if (pe.th32ProcessID != myPid) {
            if (_wcsicmp(pe.szExeFile, L"DiscordUnlock.exe") == 0 ||
                _wcsicmp(pe.szExeFile, L"DiscordUnlock_Special.exe") == 0 ||
                _wcsicmp(pe.szExeFile, L"DiscordUnlock_Web.exe") == 0 ||
                _wcsicmp(pe.szExeFile, L"DiscordUnlock_Chrome.exe") == 0) {
              HANDLE hProc = OpenProcess(PROCESS_TERMINATE, FALSE, pe.th32ProcessID);
              if (hProc) {
                TerminateProcess(hProc, 0);
                CloseHandle(hProc);
              }
            }
          }
        } while (Process32NextW(hSnapDU, &pe));
      }
      CloseHandle(hSnapDU);
    }
  } catch (...) {}

  // 5. Terminate this process
  ExitProcess(0);
}

