inline std::wstring locateProtonConfgenExe() {
  static const std::string kProtonExeSha256 = "ed2efe8f2db4bcb8275a3091d7b0408d22e1b1c8a434b55ca6fcc58d167a755e";
  static const std::string kProtonZipSha256 = "309b0c63b65aebff0b25f85e6b94709e673b75ed23b0422dffb442e81372b622";
  wchar_t exePath[MAX_PATH];
  GetModuleFileNameW(nullptr, exePath, MAX_PATH);
  fs::path exeDir = fs::path(exePath).parent_path();
  std::vector<fs::path> candidates = {
    exeDir / "bin" / "protonvpn-wg-confgen.exe",
    exeDir / "bin" / "proton-confgen.exe",
    exeDir / "protonvpn-wg-confgen.exe",
    exeDir / "proton-confgen.exe",
    fs::path("C:/DiscordUnlock/bin/protonvpn-wg-confgen.exe"),
    fs::path("C:/DiscordUnlock/bin/proton-confgen.exe")
  };
  wchar_t appData[MAX_PATH];
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    candidates.push_back(fs::path(appData) / "DiscordUnlock" / "bin" / "protonvpn-wg-confgen.exe");
    candidates.push_back(fs::path(appData) / "DiscordUnlock" / "bin" / "proton-confgen.exe");
  }
  for (const auto &p : candidates) {
    std::error_code ec;
    if (fs::exists(p, ec) && fs::file_size(p, ec) > 500000 &&
        computeFileSHA256(p.wstring()) == kProtonExeSha256) return p.wstring();
  }

  // AUTO-PROVISIONING: Se ausente, baixa e instala automaticamente sem exibir erro
  try {
    fs::path binDir = exeDir / "bin";
    std::error_code ec;
    if (!fs::exists(binDir, ec)) fs::create_directories(binDir, ec);

    fs::path targetExe = binDir / "protonvpn-wg-confgen.exe";
    fs::path targetZip = binDir / "protonvpn-wg-confgen.zip";

    // Primeiro usa o pacote embutido; download e apenas um fallback.
    bool ok = extractResourceToFile(107, targetZip);
    if (ok && computeFileSHA256(targetZip.wstring()) != kProtonZipSha256) {
      fs::remove(targetZip, ec);
      ok = false;
    }
    if (ok && fs::exists(targetZip, ec) && fs::file_size(targetZip, ec) > 50000) {
      std::wstring psCmd = L"powershell.exe -NoProfile -ExecutionPolicy Bypass -Command \"Expand-Archive -Path '" + targetZip.wstring() + L"' -DestinationPath '" + binDir.wstring() + L"' -Force\"";
      std::vector<wchar_t> buf(psCmd.begin(), psCmd.end()); buf.push_back(wchar_t(0));
      STARTUPINFOW si = { sizeof(si) }; si.dwFlags = STARTF_USESHOWWINDOW; si.wShowWindow = SW_HIDE;
      PROCESS_INFORMATION pi = { 0 };
      if (CreateProcessW(nullptr, buf.data(), nullptr, nullptr, FALSE, CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT, nullptr, nullptr, &si, &pi)) {
        WaitForSingleObject(pi.hProcess, 15000);
        CloseHandle(pi.hProcess); CloseHandle(pi.hThread);
      }
      fs::remove(targetZip, ec);
    }

    // Se a extracao local falhar, tenta baixar o executavel direto.
    if (!fs::exists(targetExe, ec) || fs::file_size(targetExe, ec) < 500000) {
      ok = downloadBinary(CLOUD_API_HOST, L"/updates/dependencies/protonvpn-wg-confgen.exe", targetExe.wstring());
      if (ok && computeFileSHA256(targetExe.wstring()) != kProtonExeSha256) {
        fs::remove(targetExe, ec);
        ok = false;
      }
    }
    if (!ok || !fs::exists(targetExe, ec) || fs::file_size(targetExe, ec) < 500000) {
      // 2. Tenta baixar o ZIP compactado (3.6MB) e extrair
      ok = downloadBinary(CLOUD_API_HOST, L"/updates/dependencies/protonvpn-wg-confgen.zip", targetZip.wstring());
      if (!ok) {
        ok = downloadBinary(CLOUD_API_HOST, L"/updates/dependencies/protonvpn-wg-confgen.zip", targetZip.wstring());
      }
      if (ok && computeFileSHA256(targetZip.wstring()) != kProtonZipSha256) {
        fs::remove(targetZip, ec);
        ok = false;
      }
      if (ok && fs::exists(targetZip, ec) && fs::file_size(targetZip, ec) > 50000) {
        std::wstring psCmd = L"powershell.exe -NoProfile -ExecutionPolicy Bypass -Command \"Expand-Archive -Path '" + targetZip.wstring() + L"' -DestinationPath '" + binDir.wstring() + L"' -Force\"";
        std::vector<wchar_t> buf(psCmd.begin(), psCmd.end()); buf.push_back(wchar_t(0));
        STARTUPINFOW si = { sizeof(si) }; si.dwFlags = STARTF_USESHOWWINDOW; si.wShowWindow = SW_HIDE;
        PROCESS_INFORMATION pi = { 0 };
        if (CreateProcessW(nullptr, buf.data(), nullptr, nullptr, FALSE, CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT, nullptr, nullptr, &si, &pi)) {
          WaitForSingleObject(pi.hProcess, 15000);
          CloseHandle(pi.hProcess); CloseHandle(pi.hThread);
        }
        fs::remove(targetZip, ec);
      }
    }

    if (fs::exists(targetExe, ec) && fs::file_size(targetExe, ec) > 500000 &&
        computeFileSHA256(targetExe.wstring()) == kProtonExeSha256) {
      return targetExe.wstring();
    }
  } catch (...) {}

  return L"";
}

