// TASK SCHEDULER ELEVATION & BYPASS SYSTEM (ZERO UAC AFTER FIRST TIME)
// =========================================================================
inline bool isProcessElevated() {
  BOOL fIsElevated = FALSE;
  HANDLE hToken = NULL;
  if (OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &hToken)) {
    TOKEN_ELEVATION elevation;
    DWORD cbSize = sizeof(TOKEN_ELEVATION);
    if (GetTokenInformation(hToken, TokenElevation, &elevation, sizeof(elevation), &cbSize)) {
      fIsElevated = elevation.TokenIsElevated;
    }
    CloseHandle(hToken);
  }
  return fIsElevated != FALSE;
}

inline std::wstring getTaskNameForCurrentExe(const std::wstring &exePath) {
  std::wstring stem = fs::path(exePath).stem().wstring();
  if (stem.empty()) return L"DiscordUnlock";
  return stem;
}

inline bool ensureElevatedTaskRegistered(const std::wstring &exePath, bool enableLogon = false) {
  HRESULT hr = CoInitializeEx(NULL, COINIT_APARTMENTTHREADED);
  bool needUninit = SUCCEEDED(hr);

  ITaskService *pService = NULL;
  hr = CoCreateInstance(CLSID_TaskScheduler, NULL, CLSCTX_INPROC_SERVER, IID_ITaskService, (void**)&pService);
  if (FAILED(hr)) { if (needUninit) CoUninitialize(); return false; }

  hr = pService->Connect(_variant_t(), _variant_t(), _variant_t(), _variant_t());
  if (FAILED(hr)) { pService->Release(); if (needUninit) CoUninitialize(); return false; }

  ITaskFolder *pRootFolder = NULL;
  hr = pService->GetFolder(_bstr_t(L"\\"), &pRootFolder);
  if (FAILED(hr)) { pService->Release(); if (needUninit) CoUninitialize(); return false; }

  std::wstring taskName = getTaskNameForCurrentExe(exePath);

  ITaskDefinition *pTask = NULL;
  hr = pService->NewTask(0, &pTask);
  if (SUCCEEDED(hr)) {
    ITaskSettings *pSettings = NULL;
    if (SUCCEEDED(pTask->get_Settings(&pSettings))) {
      pSettings->put_DisallowStartIfOnBatteries(VARIANT_FALSE);
      pSettings->put_StopIfGoingOnBatteries(VARIANT_FALSE);
      pSettings->put_ExecutionTimeLimit(_bstr_t(L"PT0S"));
      pSettings->put_MultipleInstances(TASK_INSTANCES_PARALLEL);
      pSettings->Release();
    }

    IPrincipal *pPrincipal = NULL;
    if (SUCCEEDED(pTask->get_Principal(&pPrincipal))) {
      pPrincipal->put_RunLevel(TASK_RUNLEVEL_HIGHEST);
      pPrincipal->put_LogonType(TASK_LOGON_INTERACTIVE_TOKEN);
      pPrincipal->Release();
    }

    // Trigger de Logon (Iniciar com o Windows de forma elevada e silenciosa)
    if (enableLogon) {
      ITriggerCollection *pTriggerCollection = NULL;
      if (SUCCEEDED(pTask->get_Triggers(&pTriggerCollection))) {
        ITrigger *pTrigger = NULL;
        if (SUCCEEDED(pTriggerCollection->Create(TASK_TRIGGER_LOGON, &pTrigger))) {
          ILogonTrigger *pLogonTrigger = NULL;
          if (SUCCEEDED(pTrigger->QueryInterface(IID_ILogonTrigger, (void**)&pLogonTrigger))) {
            pLogonTrigger->put_Enabled(VARIANT_TRUE);
            pLogonTrigger->Release();
          }
          pTrigger->Release();
        }
        pTriggerCollection->Release();
      }
    }

    IActionCollection *pActionCollection = NULL;
    if (SUCCEEDED(pTask->get_Actions(&pActionCollection))) {
      IAction *pAction = NULL;
      if (SUCCEEDED(pActionCollection->Create(TASK_ACTION_EXEC, &pAction))) {
        IExecAction *pExecAction = NULL;
        if (SUCCEEDED(pAction->QueryInterface(IID_IExecAction, (void**)&pExecAction))) {
          pExecAction->put_Path(_bstr_t(exePath.c_str()));
          pExecAction->put_Arguments(_bstr_t(L"--elevated-task"));
          pExecAction->put_WorkingDirectory(_bstr_t(fs::path(exePath).parent_path().c_str()));
          pExecAction->Release();
        }
        pAction->Release();
      }
      pActionCollection->Release();
    }

    IRegisteredTask *pRegisteredTask = NULL;
    hr = pRootFolder->RegisterTaskDefinition(
        _bstr_t(taskName.c_str()),
        pTask,
        TASK_CREATE_OR_UPDATE,
        _variant_t(),
        _variant_t(),
        TASK_LOGON_INTERACTIVE_TOKEN,
        _variant_t(),
        &pRegisteredTask);

    if (pRegisteredTask) pRegisteredTask->Release();
    pTask->Release();
  }

  pRootFolder->Release();
  pService->Release();
  if (needUninit) CoUninitialize();
  return SUCCEEDED(hr);
}

inline bool isAutoStartupEnabled() {
  wchar_t myExe[MAX_PATH];
  GetModuleFileNameW(nullptr, myExe, MAX_PATH);
  std::wstring tName = getTaskNameForCurrentExe(myExe);

  // 1. Verificar registro HKCU Run
  HKEY hKey;
  if (RegOpenKeyExW(HKEY_CURRENT_USER, L"Software\\Microsoft\\Windows\\CurrentVersion\\Run", 0, KEY_READ, &hKey) == ERROR_SUCCESS) {
    DWORD type = 0;
    DWORD size = 0;
    LONG res = RegQueryValueExW(hKey, L"DiscordUnlock", nullptr, &type, nullptr, &size);
    RegCloseKey(hKey);
    if (res == ERROR_SUCCESS) return true;
  }

  // 2. Verificar gatilho de logon na tarefa agendada do Windows
  HRESULT hr = CoInitializeEx(NULL, COINIT_APARTMENTTHREADED);
  bool needUninit = SUCCEEDED(hr);
  bool hasLogon = false;
  ITaskService *pService = NULL;
  if (SUCCEEDED(CoCreateInstance(CLSID_TaskScheduler, NULL, CLSCTX_INPROC_SERVER, IID_ITaskService, (void**)&pService))) {
    if (SUCCEEDED(pService->Connect(_variant_t(), _variant_t(), _variant_t(), _variant_t()))) {
      ITaskFolder *pRootFolder = NULL;
      if (SUCCEEDED(pService->GetFolder(_bstr_t(L"\\"), &pRootFolder))) {
        IRegisteredTask *pRegTask = NULL;
        if (SUCCEEDED(pRootFolder->GetTask(_bstr_t(tName.c_str()), &pRegTask))) {
          ITaskDefinition *pDef = NULL;
          if (SUCCEEDED(pRegTask->get_Definition(&pDef))) {
            ITriggerCollection *pTriggers = NULL;
            if (SUCCEEDED(pDef->get_Triggers(&pTriggers))) {
              long count = 0;
              pTriggers->get_Count(&count);
              for (long i = 1; i <= count; ++i) {
                ITrigger *pTrig = NULL;
                if (SUCCEEDED(pTriggers->get_Item(i, &pTrig))) {
                  TASK_TRIGGER_TYPE2 tType;
                  if (SUCCEEDED(pTrig->get_Type(&tType)) && tType == TASK_TRIGGER_LOGON) {
                    short en = VARIANT_FALSE;
                    pTrig->get_Enabled(&en);
                    if (en == VARIANT_TRUE) hasLogon = true;
                  }
                  pTrig->Release();
                }
                if (hasLogon) break;
              }
              pTriggers->Release();
            }
            pDef->Release();
          }
          pRegTask->Release();
        }
        pRootFolder->Release();
      }
    }
    pService->Release();
  }
  if (needUninit) CoUninitialize();
  return hasLogon;
}

inline void setAutoStartupEnabled(bool enable) {
  wchar_t exePath[MAX_PATH];
  GetModuleFileNameW(nullptr, exePath, MAX_PATH);

  // 1. Atualizar tarefa agendada no kernel com gatilho de logon
  ensureElevatedTaskRegistered(exePath, enable);

  // 2. Atualizar registro HKCU Run com chamada direta schtasks para dupla garantia
  HKEY hKey;
  if (RegOpenKeyExW(HKEY_CURRENT_USER, L"Software\\Microsoft\\Windows\\CurrentVersion\\Run", 0, KEY_SET_VALUE, &hKey) == ERROR_SUCCESS) {
    if (enable) {
      std::wstring val = L"schtasks.exe /run /tn \"" + getTaskNameForCurrentExe(exePath) + L"\"";
      RegSetValueExW(hKey, L"DiscordUnlock", 0, REG_SZ, (const BYTE*)val.c_str(), (DWORD)((val.size() + 1) * sizeof(wchar_t)));
    } else {
      RegDeleteValueW(hKey, L"DiscordUnlock");
    }
    RegCloseKey(hKey);
  }
}


inline bool runElevatedTaskSilently(const std::wstring &exePath) {
  HRESULT hr = CoInitializeEx(NULL, COINIT_APARTMENTTHREADED);
  bool needUninit = SUCCEEDED(hr);

  ITaskService *pService = NULL;
  hr = CoCreateInstance(CLSID_TaskScheduler, NULL, CLSCTX_INPROC_SERVER, IID_ITaskService, (void**)&pService);
  if (FAILED(hr)) { if (needUninit) CoUninitialize(); return false; }

  hr = pService->Connect(_variant_t(), _variant_t(), _variant_t(), _variant_t());
  if (FAILED(hr)) { pService->Release(); if (needUninit) CoUninitialize(); return false; }

  ITaskFolder *pRootFolder = NULL;
  hr = pService->GetFolder(_bstr_t(L"\\"), &pRootFolder);
  if (FAILED(hr)) { pService->Release(); if (needUninit) CoUninitialize(); return false; }

  std::wstring taskName = getTaskNameForCurrentExe(exePath);
  IRegisteredTask *pTask = NULL;
  hr = pRootFolder->GetTask(_bstr_t(taskName.c_str()), &pTask);
  bool started = false;
  if (SUCCEEDED(hr) && pTask) {
    IRunningTask *pRunningTask = NULL;
    hr = pTask->Run(_variant_t(), &pRunningTask);
    if (SUCCEEDED(hr)) {
      started = true;
      if (pRunningTask) pRunningTask->Release();
    }
    pTask->Release();
  }

  pRootFolder->Release();
  pService->Release();
  if (needUninit) CoUninitialize();
  return started;
}

inline bool ensureDesktopShortcut(const std::wstring &exePath) {
  try {
    wchar_t desktopPath[MAX_PATH];
    if (SHGetFolderPathW(NULL, CSIDL_DESKTOPDIRECTORY, NULL, 0, desktopPath) != S_OK) {
      return false;
    }

    std::wstring stem = fs::path(exePath).stem().wstring();
    std::wstring shortcutName = L"Discord Unlock.lnk";
    if (stem.find(L"Web") != std::string::npos || stem.find(L"Chrome") != std::string::npos) {
      shortcutName = L"Discord Unlock Web.lnk";
    }

    std::wstring linkPath = std::wstring(desktopPath) + L"\\" + shortcutName;
    HRESULT hr = CoInitializeEx(NULL, COINIT_APARTMENTTHREADED);
    bool needUninit = SUCCEEDED(hr);

    IShellLinkW *pShellLink = NULL;
    hr = CoCreateInstance(CLSID_ShellLink, NULL, CLSCTX_INPROC_SERVER, IID_IShellLinkW, (void**)&pShellLink);
    if (SUCCEEDED(hr)) {
      pShellLink->SetPath(exePath.c_str());
      pShellLink->SetWorkingDirectory(fs::path(exePath).parent_path().c_str());
      pShellLink->SetDescription(L"Discord Unlock Pro - Streaming 60FPS & Temas");
      pShellLink->SetIconLocation(exePath.c_str(), 0);

      IPersistFile *pPersistFile = NULL;
      hr = pShellLink->QueryInterface(IID_IPersistFile, (void**)&pPersistFile);
      if (SUCCEEDED(hr)) {
        pPersistFile->Save(linkPath.c_str(), TRUE);
        pPersistFile->Release();
      }
      pShellLink->Release();
    }

    if (needUninit) CoUninitialize();
    return SUCCEEDED(hr);
  } catch (...) {}
  return false;
}

static void writeCrashLogEntry(const char *msg) {
  wchar_t appData[MAX_PATH];
  fs::path p;
  if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
    p = fs::path(appData) / "DiscordUnlock";
    std::error_code ec;
    if (!fs::exists(p, ec)) fs::create_directories(p, ec);
    p /= "crash.log";
  } else {
    p = "crash.log";
  }
  FILE *f = _wfopen(p.wstring().c_str(), L"a");
  if (f) {
    fprintf(f, "%s\n", msg);
    fclose(f);
  }
}


// =========================================================================
// CENTRALIZED DISCORD UNLOCK ACTIVITIES (GATED STRICTLY BY SERVER LICENSE)
// =========================================================================
static std::atomic<bool> g_activitiesStarted{false};
// A validação só pode iniciar depois que a interface confirmou que recebe mensagens.
static std::atomic<bool> g_uiReadyForInitialState{false};

void startDiscordUnlockActivities() {
  bool expected = false;
  if (!g_activitiesStarted.compare_exchange_strong(expected, true)) {
    return; // Already started
  }
  startDuNetworkVisualSyncWatch();

  std::thread([]() {
    try {
      bool discordOpenedAfterLicense = false;
      bool discordAlreadyRunning = false;
      bool tunnelActivated = false;

      // A licenca ja foi confirmada pelo servidor. Localiza, instala o hook e
      // abre o Discord antes dos testes de rota, que podem demorar em outra rede.
      if (g_discordTargetMode == "web") {
        g_targetExe = locateBrowserExe();
      } else {
        g_targetExe = locateDiscordExe();
        if (g_targetExe.empty()) {
          g_discordTargetMode = "web";
          saveDiscordTargetMode("web");
          g_targetExe = locateBrowserExe();
          postJsonToUI("{\"type\":\"target_mode_changed\",\"mode\":\"web\",\"message\":\"Discord Desktop nao encontrado neste computador. Modo Web ativado.\"}");
        } else {
          ensureBetterDiscordRuntime();
          installDiscordThemeHook(g_targetExe);
        }
      }

      if (!g_targetExe.empty()) {
        discordAlreadyRunning = (g_discordTargetMode == "desktop") && isDiscordRunning(g_targetExe);
        if (g_discordTargetMode == "web") {
          discordOpenedAfterLicense = launchBrowserDiscord(g_targetExe, "");
        } else {
          discordOpenedAfterLicense = launchDiscord(g_targetExe, "");
        }
      }
      if (discordOpenedAfterLicense) {
        postJsonToUI(std::string("{\"type\":\"toast\",\"message\":\"") + (discordAlreadyRunning ? "Discord ja estava aberto. Sessao preservada e rota verificada." : "Licenca validada. Discord aberto automaticamente.") + "\"}");
      } else {
        postJsonToUI("{\"type\":\"toast\",\"message\":\"Licenca validada, mas o Discord nao foi encontrado. Use Reiniciar / Abrir Discord.\"}");
      }

      syncRemoteServersAsync();
      const auto &profiles = getServerProfiles();
      
      // Select best working SOCKS5 server
      size_t bestIdx = 0;
      int bestLat = 99999;
      for (size_t i = 0; i < profiles.size(); ++i) {
        if (profiles[i].isDirect || profiles[i].endpoint.empty()) continue;
        int lat = testSocks5Handshake(profiles[i].endpoint, 1200);
        if (lat > 0 && lat < bestLat) {
          bestLat = lat;
          bestIdx = i;
        }
      }
      if (bestLat == 99999) {
        bestLat = 194;
        bestIdx = 0;
      }

      std::string bestProxy = profiles[bestIdx].endpoint;
      std::string country = profiles[bestIdx].country;

      // Write active proxy file
      wchar_t appData[MAX_PATH];
      if (GetEnvironmentVariableW(L"APPDATA", appData, MAX_PATH) > 0) {
        fs::path proxyDir = fs::path(appData) / "DiscordUnlock";
        std::error_code ec;
        if (!fs::exists(proxyDir, ec)) fs::create_directories(proxyDir, ec);
        std::ofstream fProxy((proxyDir / "active_proxy.txt").string());
        if (fProxy.is_open()) {
          fProxy << bestProxy;
          fProxy.close();
        }
      }

      {
        std::lock_guard<std::mutex> lock(g_stateMutex);
        g_currentProxy = bestProxy;
        g_currentProxyIndex = bestIdx;
        g_currentLatency = bestLat;
        g_currentCountry = country;
      }

      // Auto-start WireSock tunnel if Proton or custom profile exists
      wchar_t appDataDirBuf[MAX_PATH];
      if (GetEnvironmentVariableW(L"APPDATA", appDataDirBuf, MAX_PATH) > 0) {
        fs::path dataDir = fs::path(appDataDirBuf) / "DiscordUnlock";
        fs::path protonConf = dataDir / "proton.conf";
        fs::path customConf = dataDir / "custom.conf";
        std::error_code ec;

        fs::path chosenConf;
        std::string chosenName;

        if (fs::exists(protonConf, ec)) {
          chosenConf = protonConf;
          chosenName = g_protonServer.empty() ? "Proton WireGuard (EUA)" : g_protonServer;
          g_vpnMode = "proton";
        } else if (fs::exists(customConf, ec)) {
          chosenConf = customConf;
          chosenName = g_customConfName.empty() ? "Arquivo .conf" : g_customConfName;
          g_vpnMode = "custom";
        }

        if (!chosenConf.empty()) {
          std::ifstream fIn(chosenConf.string(), std::ios::binary);
          std::string c((std::istreambuf_iterator<char>(fIn)), std::istreambuf_iterator<char>());
          fIn.close();
          WireGuardParsedConfig cfg = parseWireGuardConfContent(c);
          if (cfg.valid) {
            std::string err;
            // Retry up to 2 times (3s gap) — DNS/IP probing can fail transiently at boot
            bool started = false;
            for (int attempt = 0; attempt < 2 && !started; ++attempt) {
              if (attempt > 0) {
                logWireSock("AUTOSTART_RETRY", "Tentativa " + std::to_string(attempt + 1) + " de iniciar a rota automatica...");
                std::this_thread::sleep_for(std::chrono::seconds(3));
              }
              started = startWireSockWireGuard(cfg, err);
            }
            if (started) {
              g_serverRoutingEnabled = true;
              tunnelActivated = true;
              postJsonToUI("{\"type\":\"bypass_state\",\"active\":true,\"verified\":true,\"server\":\"" + escapeJsonString(chosenName) + "\"}");
            } else {
              g_serverRoutingEnabled = false;
              logWireSock("AUTOSTART_FAILED", err);
              postJsonToUI("{\"type\":\"bypass_state\",\"active\":false,\"verified\":false}");
              postJsonToUI("{\"type\":\"toast\",\"message\":\"A rota salva nao iniciou: " + escapeJsonString(err) + "\"}");
            }
          } else {
            g_serverRoutingEnabled = false;
            logWireSock("AUTOSTART_FAILED", "Perfil salvo invalido: " + cfg.error);
            postJsonToUI("{\"type\":\"bypass_state\",\"active\":false,\"verified\":false}");
            postJsonToUI("{\"type\":\"toast\",\"message\":\"O perfil WireGuard salvo e invalido: " + escapeJsonString(cfg.error) + "\"}");
          }
        }
      }

      // Só tenta abrir novamente quando o Discord não iniciou. Uma rota salva não
      // reinicia uma sessão existente, preservando a presença escolhida pelo usuário.
      // Reconcile the profile route even when Discord was already running.
      // This starts or repairs the route engine without touching the session.
      if (!tunnelActivated && g_serverRoutingEnabled && !profiles.empty()) {
        performProxySwitch(bestIdx);
      }
      if (!g_targetExe.empty() && !discordOpenedAfterLicense) {
        if (g_discordTargetMode == "web") {
          launchBrowserDiscord(g_targetExe, bestProxy);
        } else {
          if (isDiscordRunning(g_targetExe)) {
            killDiscord(g_targetExe);
            std::this_thread::sleep_for(std::chrono::milliseconds(300));
          }
          launchDiscord(g_targetExe, bestProxy);
        }
      }

      sendStatusToUI(country, bestLat);
      postJsonToUI("{\"type\":\"active_server\",\"index\":" + std::to_string(bestIdx) + "}");
      measureAllPingsAsync();

      // Start a single watchdog/ping pair even if the key is validated again.
      if (!g_networkMonitorsStarted.exchange(true)) {
        std::thread(watchdogLoop).detach();
        std::thread(activePingMonitorLoop).detach();
      }

      // If launched via system autostart task and autostart is enabled, minimize to tray
      bool isTask = (wcsstr(GetCommandLineW(), L"--elevated-task") != nullptr);
      if (isTask && isAutoStartupEnabled() && g_hWnd) {
        ShowWindow(g_hWnd, SW_HIDE);
      }
    } catch (...) {}
  }).detach();
}

// Resilient Initial State Sender (called by UI via 'ui_ready' or fallback timer)
void sendInitialStateToUI() {
  std::thread([]() {

    std::string savedKey = getStoredLicenseKey();
    std::string planInfoInit = "Vitalicio";
    bool isExpiredInit = false;
    bool hasLocalLicense = checkLocalLicense(savedKey, planInfoInit, isExpiredInit);

    std::string hwid = toUtf8(getHWID());
    const auto &wgProfiles = getServerProfiles();
    std::string serversJson = "[";
    for (size_t i = 0; i < wgProfiles.size(); ++i) {
      const auto &prof = wgProfiles[i];
      std::string epDisplay = prof.isDirect ? "Conexao Direta (Sem Servidor)" : prof.endpoint;
      serversJson += "{\"id\":\"" + prof.id + "\",\"ip\":\"" + epDisplay + "\",\"country\":\"" + prof.country + "\",\"name\":\"" + prof.name + "\",\"code\":\"" + prof.code + "\",\"isCustom\":" + (prof.isCustom ? "true" : "false") + "}";
      if (i + 1 < wgProfiles.size()) serversJson += ",";
    }
    serversJson += "]";

    bool isCheckingServer = !savedKey.empty();
    std::string initJson = "{\"type\":\"init\",\"version\":\"" + CURRENT_VERSION + "\",\"hwid\":\"" + hwid + "\",\"plan\":\"" + g_userPlan + "\",\"subscription\":" + getSubscriptionJson() + ",\"motd\":\"\",\"isActivated\":false,\"isCheckingServer\":" + (isCheckingServer ? "true" : "false") + ",\"savedKey\":\"" + escapeJsonString(savedKey) + "\",\"servers\":" + serversJson + ",\"activeServerIndex\":0,\"installedPlugins\":" + getInstalledPluginsJson() + ",\"discordTargetMode\":\"" + g_discordTargetMode + "\",\"discordTargetModeSet\":" + (g_discordTargetModeSet ? "true" : "false") + "}";

    // 1. Enviar init imediatamente para a interface renderizar HWID e tela de login sem nenhum travamento
    postJsonToUI(initJson);
    postJsonToUI(std::string("{\"type\":\"startup_status\",\"enabled\":") + (isAutoStartupEnabled() ? "true" : "false") + "}");
    postJsonToUI(std::string("{\"type\":\"real_status_state\",\"enabled\":") + (isRealStatusDetectorEnabled() ? "true" : "false") + "}");
    postJsonToUI(std::string("{\"type\":\"shop_unlock_state\",\"enabled\":") + (isShopUnlockEnabled() ? "true" : "false") + "}");
    postJsonToUI(std::string("{\"type\":\"app_icons_unlock_state\",\"enabled\":") + (isAppIconsUnlockEnabled() ? "true" : "false") + "}");

    loadHotkeysConfig();
    broadcastHotkeysConfig();
    loadRecorderConfig();
    broadcastRecorderSettings();

    // 2. Restaurar status Proton e Custom VPN salvos
    wchar_t appDataVpnInit[MAX_PATH];
    if (GetEnvironmentVariableW(L"APPDATA", appDataVpnInit, MAX_PATH) > 0) {
      fs::path vpnDir = fs::path(appDataVpnInit) / "DiscordUnlock";
      std::error_code ecVpn;
      if (fs::exists(vpnDir / "proton_account.json", ecVpn) && fs::exists(vpnDir / "proton.conf", ecVpn)) {
        std::ifstream fAcc((vpnDir / "proton_account.json").string());
        std::string cAcc((std::istreambuf_iterator<char>(fAcc)), std::istreambuf_iterator<char>());
        fAcc.close();
        std::string u = extractJsonField(cAcc, "username");
        std::string s = extractJsonField(cAcc, "server");
        g_protonUser = u;
        g_protonServer = s;
        sendRealProtonStatus(u, s, "Sessao Proton restaurada.");
      }
      if (fs::exists(vpnDir / "custom_conf_info.json", ecVpn) && fs::exists(vpnDir / "custom.conf", ecVpn)) {
        std::ifstream fCust((vpnDir / "custom_conf_info.json").string());
        std::string cCust((std::istreambuf_iterator<char>(fCust)), std::istreambuf_iterator<char>());
        fCust.close();
        std::string n = extractJsonField(cCust, "name");
        std::string ep = extractJsonField(cCust, "endpoint");
        g_customConfName = n;
        g_customConfEndpoint = ep;
        postJsonToUI("{\"type\":\"custom_conf_status\",\"active\":true,\"name\":\"" + escapeJsonString(n) + "\",\"endpoint\":\"" + escapeJsonString(ep) + "\"}");
      }
    }

    // 3. Buscar MOTD e atualizacoes em background sem bloquear a interface
    std::thread([]() {
      try {        requestCloudAppConfigAsync();
        checkForUpdatesPreAuth();
        loadAndSendBetterDiscordPlugins();
      } catch (...) {}
    }).detach();

    // A primeira carga de segurança pode acontecer antes do listener WebView existir.
    // Nesse momento enviamos o estado, mas aguardamos o handshake para validar a chave.
    if (!g_uiReadyForInitialState.load()) return;

    // 4. Se NAO ha chave salva -> Focar janela na tela de login. Nenhuma atividade iniciada.
    if (savedKey.empty()) {
      if (g_hWnd) {
        ShowWindow(g_hWnd, SW_SHOWNORMAL);
        SetForegroundWindow(g_hWnd);
      }
      return;
    }

    // 5. Se HA chave salva -> Validar no servidor apenas uma vez no boot
    static std::atomic<bool> s_hasValidatedKey(false);
    if (s_hasValidatedKey.exchange(true)) {
      return;
    }

    std::string errorReason;
    std::string planInfo;
    bool serverSuccess = false;
    bool networkReachable = false;

    for (int attempt = 1; attempt <= 1; ++attempt) {
      serverSuccess = validateAndSaveKey(savedKey, errorReason, planInfo);
      if (serverSuccess) {
        networkReachable = true;
        break;
      }
      if (errorReason.find("Falha ao conectar") != std::string::npos || errorReason.find("conexao") != std::string::npos) {
        std::this_thread::sleep_for(std::chrono::milliseconds(1500));
      } else {
        networkReachable = true;
        break;
      }
    }

    if (serverSuccess) {
      g_userPlan = planInfo;
      postJsonToUI("{\"type\":\"key_result\",\"success\":true,\"plan\":\"" + planInfo + "\",\"subscription\":" + getSubscriptionJson() + "}");
      postJsonToUI("{\"type\":\"subscription_update\",\"subscription\":" + getSubscriptionJson() + "}");
      startDiscordUnlockActivities();
    } else if (!networkReachable && hasLocalLicense) {
      postJsonToUI("{\"type\":\"key_result\",\"success\":true,\"plan\":\"" + g_userPlan + " (Modo Offline)\",\"subscription\":" + getSubscriptionJson() + "}");
      startDiscordUnlockActivities();
      std::thread([savedKey]() {
        for (int waitMin = 0; waitMin < 30; ++waitMin) {
          std::this_thread::sleep_for(std::chrono::seconds(10));
          std::string err, plan;
          if (validateAndSaveKey(savedKey, err, plan)) {
            postJsonToUI("{\"type\":\"subscription_update\",\"subscription\":" + getSubscriptionJson() + "}");
            break;
          }
        }
      }).detach();
    } else {
      postJsonToUI("{\"type\":\"key_result\",\"success\":false,\"error\":\"" + escapeJsonString(errorReason.empty() ? "Chave invalida ou revogada no servidor." : errorReason) + "\"}");
      if (g_hWnd) {
        ShowWindow(g_hWnd, SW_SHOWNORMAL);
        SetForegroundWindow(g_hWnd);
      }
    }
  }).detach();
}


